/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180122-6","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"区民委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"荏原第四区民集会所の４月からの利用","agenda":"荏原第四区民集会所の４月からの利用","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか要望として挙がっていた、プロジェクターやスクリーン、マイクについてはどのように改善されたのかをお伺いしたいと思います。住民から様々な要望が寄せられるかと思いますけれども、それについても真摯に対応してほしいと求めました、その点についてもお伺いします。","respondent":"伊崎地域活動課長","answer":"間のパーテーションを開いて１室として使えるようになっておりますので、第１集会室にプロジェクターとスクリーンを設置したところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"今後もこういう条件が合えば、カラオケが使用できる防音設備を進めていく方向があるのか、どういうお考えなのか。その辺をお伺いしたいと思います。","respondent":"伊崎地域活動課長","answer":"シルバーセンターなどがすぐ近くにないということもありまして、地域の方のご要望がございましたので、設置をしたものです。は立地や施設など、いろいろな状況もありますので、そういったことを勘案しながら対応していきたいと考えております。","id":"exchange-002"}]},{"id":"topic-02","title":"交流都市地方物産展の開催","agenda":"交流都市地方物産展の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前回、実施をされて、まちの元気につながる取組みがどう進み、地方創生への協力・貢献にどのような効果があったのか、区の評価を伺いたいと思います。３００万円という予算を使っていますので、このあり方はどうなのかという思いは、正直、持っていますので、効果についてお伺いしたいと思います。","respondent":"伊崎地域活動課長","answer":"こちらの経費につきましては、東京都からの観光まちづくり推進支援事業補助金という補助金で１２５万円ほどの補助をいただく予定となっております。東京都も挙げて、都あるいは２３区と全国の市町村との交流を進めるというところでは、その一端を担えたと自負しております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"実施している側はそういうご意見なのかと思うのですけれども、出店している自治体の皆さんからは、どんなご意見や意義、声が上がっているのか。もちろん自治体間が交流をしたり、出店自治体からどういうご意見・ご要望がというのを最後に伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"なかなか都会の品川区の皆様が集まるところで、物品を売ってＰＲができる機会が少ないということで、大変感謝をされてあります。千葉県物産展はかなり売上げも上がったということで、そういった点でも感謝をいただいているところです。","id":"exchange-004"}]},{"id":"topic-03","title":"「品川区サイバーセキュリティに関する協定」の締結","agenda":"「品川区サイバーセキュリティに関する協定」の締結","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"お伺いしたいのは、都内で初ということもありますが、区内中小企業の被害の実態や状況です。今回、協定締結に至った動機、その実態について伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"大企業と違いまして、サイバーセキュリティに対していろいろな対策を打つだけの、人的にも経済的にも十分な余裕がない状況があります。","id":"exchange-005"}]},{"id":"topic-04","title":"目黒サービスコーナーの開設および運営","agenda":"目黒サービスコーナーの開設および運営","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"その上で伺いたいのですけれども、何が効率的になるのか、その点を伺いたいと思います。業務をされていると思うのですけれども、それにも勝るというのは何を指しているのか、その点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"建設業の許可の申請受付、そういうノウハウを持った業者が複数社いると思いますので、そういうところにお願いしたいということ。多言語対応ということで、外国語の案内ボードを作成するとか、そういう区ではなかなかアイデアが思い浮かばない部分を民間企業にお願いするものです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"この民間事業者に委託することで、今までの金額から年間幾らに変わったのか、その点についても伺いたいと思います。事務の流れはむしろ複雑化し、ひいては住民サービスの向上にはつながっていかないと思いますけれども、この点についてはいかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"大井町サービスコーナーについては、平成２９年度、今年度に始まった事業ですけれども、まだ決算は出ておりませんので、今は詳細にお答えしかねます。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"関連して１点伺いたいのですけれども、私が原因について質問したところ、失念したというご答弁がありました。同じことが繰り返されない対策というのは、どう具体化されているのか、改めて伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"４月にご報告した漏えいの件につきましては、正式なＤＶ支援が出ていない方について、そこら辺の認識を職員が失念してしまって。基本的にはご本人と同一世帯、もし出せないものについてはお出しできないということで、きっぱりとお断りする形をとらせていただきたいと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"同一世帯にありながら、民間事業者に委託をすると、窓口での対応と交付での対応に齟齬が生まれる仕組みが発生することはないのかと思うのです。仕組み上、なぜ防げるとなるのか、そこをご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"当然、聴聞等を行って、お出しできない分についてはお出しできないとお断りする形をとります。今回の教訓を踏まえまして、サービスコーナーと本庁舎と各地域センターでも、しっかりと個人情報の保護に努めてまいりたいと思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"疑義が生じた、そこで疑義が判断できなければスルーしてしまう仕組み上の盲点がそこにあるのではないか、この２点を最後に伺いたいと思います。改めて、こうした民間事業者への委託は、私はやめるべきだと思います。","respondent":"提坂戸籍住民課長","answer":"即、そこで事業者に判断していただかないで、すぐに区の職員に代わる形です。一義的に窓口対応をするわけですけれども、自分で判断できなければ、誤って情報漏えいをするということは決して今後はないと考えています。","id":"exchange-010"},{"speaker":"藤原委員","kind":"確認","question":"本人確認は免許証とかパスポートでするということですが、あれは光なのですか、免許証を置いて調べます。私はパスポートで本人確認したことはないですから、目視ではなくて機械等でやる方法というのはあるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"その辺を確認する機械は導入していませんので、その辺はご本人様と顔写真で確認するしかないのが実情です。それは民間委託でも直営でも同じことですけれども、その辺はしっかりと今後も確認をしてまいりたいと思います。","id":"exchange-011"},{"speaker":"藤原委員","kind":"確認","question":"免許証だけはやる、パスポートとマイナンバーカードは目視でというのはどうしてかと私は思うのです、免許証はやるわけですから。その辺についてはいかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"運転免許証のように透かしを確認することはできませんが、ただ、それがなかなか判別しにくいというのが事実です。その辺は十分に、個別によく確認させていただきたいと考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"半分ぐらいこうやると透かしのような効果が出てくるという、そういう事実があるのは知らなかったもので、こういう質問をしてしまったのです。パスポートは半分にして、そうすると透かしみたいになるということは、職員の皆さんはわかっているということですね。","respondent":"提坂戸籍住民課長","answer":"十分、職員は認識しているはずですけれども、再認識してもらうためにも、もう一回周知徹底を図ってまいります。","id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"１月末には事業者が決定されるスケジュールですけれども、この簡易型総合評価方式での事業者選定に際し、そのスキルを見る上での評価がどうされているのかを少しご説明いただきたい。","respondent":"提坂戸籍住民課長","answer":"簡易型総合評価方式について簡単にご説明いたしますけれども、過去の実績等、受託者の選定を行うものです。まずは説明会を開いて、その事業の概要をご説明した上で、それに参加してみようという事業者に名乗りを上げていただきます。","id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"簡易型と簡易型でないというのは、どの程度の違いがあるのかをご説明いただきたいと。どういう類の事業者、どういった形の事業者がこういうところに応募してきたのかということの説明をできる範囲でしてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"こちらとしては、そういう経費は出さないので、簡易型総合評価という形で考えております。旅券関係の事業を行っているとか、登記簿謄本の作成・交付を行っているとか、そういうところに由来している事業者が多いかと考えています。","id":"exchange-015"}]},{"id":"topic-05","title":"「第２８回 伝統の技と味／しながわ展」の開催","agenda":"「第２８回 伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１１５万７,０００円は、使用料という点で、どこからこういう数字が出てくるのでしょうか。まず使用料についてお伺いしたいのと、使用料と設営で２８０万円ぐらいかかる、この辺についても教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"そうしたものを組み上げたり組み立てたりということ、それは委託をかける関係で、委託料なども含まれてこちらの金額になってあります。会場使用料と、そうしたことをお願いする委託料という性格のものがここに入ってあります。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"細かくてすみませんけれども、入口に枠をとか、それは設営経費ではないのですか。それも使用料なのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"イベントホールにいろいろな機材を運び込むための運搬業者の委託料だとか、そうした諸々のものが「等」で含まれてあります。それから、それを形にして組み上げるための部分も委託として計上させていただいているところをもって、会場等使用料の「等」がそこに入ってあります。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"だけれども、今ご説明してくださって、車で搬入だとか云々でつくっているというと、一般的にそういうのが設営ではないですか。だから、これだけ使用料という形で出るのがどうしてですかというのを伺っているのですけれども、そうなのですかとしか言えないんですが。","respondent":"山崎商業・ものづくり課長","answer":"るる説明申し上げたのは、会場等使用料の部分で、会場設営経費と実演等委託料、これは伝統工芸の方々にお支払いするものが１６０万円と、その下の１００万円弱という内容になっています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう工夫や、課題になっていることがあるのか、お伺いしたいと思います。世代継承というのでしょうか、保存会の方からはどういうご要望があるのか、お伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"１００年を超える伝統を守り続けているという意味では、同じものを愛着を持ってつくり続けているという継続性と、そこが一番の課題かと思っています。そういったものも考えながら、今、やらせていただいているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ＰＲグッズの話もありましたけれども、年に１回のこの企画を通じて、そういう視点でさらに盛り上がっていけるような、また、地域の方々とともに来訪者の方々にも触れたり接したり購入していただけたり、そういう方向でぜひとも進めてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"申し訳ございません、先ほどの答弁、会場等使用料の説明が伝わらなかった点で、きゅりあんのイベントホールの利用料と、それから、いろいろな備品をレンタルしているレンタル料で、そこはハードのものですので、ご理解を賜りたいと思います。","id":"exchange-020"}]},{"id":"topic-06","title":"「事業承継フォーラムおよび永年継続事業所表彰式」の開催","agenda":"「事業承継フォーラムおよび永年継続事業所表彰式」の開催","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご相談だったり、実際の成立の件数であったり、どういう規模で今は進んでいるのか。現状について伺いたいのと、多くの方にそういう事業の周知が広がったらいいと思いますが、現状を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今は２０名ほどで、２０回ほど連続で同じ方に対して組んでいく、そういった特徴的な後継者塾をやりました。一定、継続性を持ちながら、工夫を持って続けていく必要があるという形で捉えてあります。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"今のお話でご答弁をいろいろお聞きしていて、廃業だと、ひいては雇用が消失していくというところかと思っていたのですが。この事業のフォーカスしている狙いというのは、そういうことでよろしいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"区内では、比率で言いますと２３.５％ということで、そうした理由が少ないわけではございません。やはり事業の将来性とか後継者の育成とか、全く打つ手がない状態ではないというところを切り口にして、頑張ってまいりたいとは思っております。","id":"exchange-022"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"お伺いしたいのは、任せる人が見当たらないというのは、どういう実態なのでしょうか。どういう事業にそういう、黒字なのに後継者が出てこないところがあるのかを教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"区内の中小企業の規模でいいますと、やはり２０人を下回るような小規模事業所がかなりの比率で存在している、現状はそういう状況です。","id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"なかなか確かにすんなりいかないという気もしないでもない、それは先ほどの株式の問題とかになるのかもしれないのですけれども。いわゆる後継者をどのように見つけていくか、指名していくかというところでの、現段階での展開なりを教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"先ほど説明した事例は、高技術によってもたらされている効果は、やはり区内中小企業の皆さんに多いのです。いわゆる家族ではありませんが、後継者の方に譲ることも一つ考えようではないかという意識改革に持っていくような流れもつくってまいりたい。","id":"exchange-024"}]},{"id":"topic-07","title":"「ウーマンズビジネスグランプリ２０１８」の開催","agenda":"「ウーマンズビジネスグランプリ２０１８」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"プラス、今の前の品川情報クラスターフェアで言うならば、それも都市型観光の１つになっていくと思うのです。産業の振興という意味の課としての考えはどうかということと、こういう施策をどう活用していくか、お考えがあるならば教えていただければ幸いです。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長","answer":"ちょっとずつ情報通信業が増えているのではなくて、２５０消えて３００増えるという感じで増えている。ある意味、観光視点にも資するような、関係があるかと考えています。グランプリなり、いろいろ楽しんでいただくという意味では、集客という面では観光に協力いただいて資するところはあるかと思います。","id":"exchange-025"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"スクエア荏原のほうだけ伺いたいのですけれども、事情はよくわかりました。そうでないときと、おそらく幅広く検討されているとは思いますが、現状の中で説明できる範囲でご説明ほしいと求めました。","respondent":"鈴木文化観光課長","answer":"申請の予定期限より早く借りるのをやめるという申し出になりますので、年度末までと、お願いや強制はなかなかできないスタイルになります。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":29102,"voices":97}},{"id":"h30-20180122-7","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"品川区立発達障害者支援施設 就労支援事業の変更","agenda":"品川区立発達障害者支援施設 就労支援事業の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的なところで何点か教えていただきたいと思うのですけれども、委託されている事業者がどこかということの確認をお願いしたいと思います。Ｂ型の需要がそれぞれどうなっているのか、その方はその後どういうふうになっていくのか、そこら辺のところを説明を求めました。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型とＢ型の需要についてなのですけれども、そこから一般就労みたいな循環型を考えていたところではあるのですが、逆に能力がある方。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"就労継続支援Ａ型は、現在３人から２人になったということで、それほどたくさんの人数ではないということでずっと来ていたのでしょうか。もう１つ、ジョブコーチですとか、どういう体制になっていくのかという点についてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"就労した後に、仕事はできても、またそこは成人期支援事業リクトに相談に来てもらって様子を見るということも重ねてやってまいりたいと考えています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで最後に、ぷらーすの体制は、職員が９人ですか。職員はどういう資格の方がどういう形で仕事をされているかという、その体制だけ、教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型とＢ型は１０人に対して１人、それ以外にたしか３人職員がいて、そちらは臨床心理士なども配置しております。申し訳ありません、平成２８年度で４７７回個人面談をし、グループワークに参加した人が３０１人ということで統計が出ております。","id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"Ａ型のエヴリィではどんな作業がされていたのかの確認と、今７０人登録とあったのですけれども、登録定員はあるのでしょうか。そこだけお願いします。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型の作業内容ですが、テープ起こし、こうしたような作業もやっているところです。リクトの利用が多くなってきたので、この間、心理士を１人追加しています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"平成２６年から約４年間で、先ほどのご説明でも循環型で一般就労のほうにというところだったのですけれども、ここを通して一般就労に移った方がどれくらいいらっしゃるのかということだけ、説明を求めました。","respondent":"中山障害者福祉課長","answer":"全部で、就労継続支援Ａ型から４人、Ｂ型から６人の方が一般就労に移られております。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問","question":"ただ、この間、約４年間やってきたところの目的は、一般就労へのステップをつなぐことを目的にしてきたと。区としてもそういうふうに判断をしていると捉えてよろしいのか尋ねました。","respondent":"中山障害者福祉課長","answer":"委員おっしゃるように、就労継続支援Ａ型というのは、最低賃金を保障し、そこで雇用を継続していくというのが主目的になると思います。そうした形の支援のあり方がいいのではないかということで、今回、このように決めさせていただいたところです。","id":"exchange-006"}]},{"id":"topic-02","title":"（仮称）品川区立障害児者総合支援施設開設に向けての進捗状況","agenda":"（仮称）品川区立障害児者総合支援施設開設に向けての進捗状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前のところで１カ月に一、どういう中身で、課題はあるのかというあたりもお聞かせほしいと求めました。そして指定管理者を１２月には決定していくということなのですが、どういう日程で、どういう形で行われるのかという点についても説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今後の地域への説明会の件ですが、港特別支援学校や城南特別支援学校の現在高校１年生、３月上旬あたりにやりたいなと考えているところです。地域への説明会ですが、工事の前から全部で４回行っているところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"というのも、私、委員会でどの事業をどこが受け持つというのを報告しているというのがわかるところがあったら教えていただきたいのが１つです。４つの法人でそれぞれ職員体制、４つの法人がそれぞれどれくらいの職員体制になるのか、その辺がわかったら教えてほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"例えば２階の就労継続支援Ｂ型と訪問系サービスに愛成会と書いてありますけれども、今、そういうところも協議しています。もちろん最初からフルというのはなかなか難しいので、徐々に定員数を増やしていこうと考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総合ですから、この総合支援施設で職員としてはイメージとして何人ぐらいになるというところがわかったら、教えてほしいと求めました。そこら辺もわかる範囲で結構なのですけれども、おおよそそういう方向だというのがわかるものがありましたら、説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、１００人近くにはなるのではないかなと考えています。例えば２階部分の遊戯の場所とか、子どもの遊び場の確保も必要なので、そういうところも今協議しております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この施設は、各障害者団体の方々からもすごく期待の大きい施設だと思うのです。ぜひ団体の皆さんのご意見やご要望にもお応えいただけるような形で進めていただきたいと思うのですけれども、最後にその点だけ、お願いします。","respondent":"飛田障害者施策推進担当課長","answer":"３月上旬には、特別支援学校の保護者、少しでも皆さんの期待に応えられるようにできればいいかなと考えています。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今後のスケジュールの件で確認なのですけれども、私もこの近くを通るときに見ているのですが、開設、完成は間に合うのですか。その辺、まず１点、説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今、建築のほうで、基礎をやっているというところです。今、私が聞いているところでは、平成３１年２月竣工を目指して、設計業者と施工業者、いろいろと協議しながら進めていると聞いております。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一番最初の関係で、指定管理候補者である共同事業体フリーユニティーという言葉、これは最初からあったのでしょうか。私の感覚では、４つの事業者が指定管理を受けるのかなと思っていたのですが、最初からこの１つのものになっていたのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"４つの共同事業体、４つのところが一緒になってプロポーザルをして、共同事業体フリーユニティーというところでこちらに出てきたということです。あくまでも４つの法人の共同体の名称となります。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川の指定管理で今までそういう形がずっとあるのでしょうか。そこら辺が私の知識にないので。","respondent":"飛田障害者施策推進担当課長","answer":"それぞれ４法人、社会福祉法人３つと一般社団法人１つというところで取りまとまっております。ほかの例というところでは、図書館などが行っていると聞いております。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"要するに、共同事業体というのは１つの法人にはなっていないわけですよね。１つになっていないところ、その中に４つ入っているものと指定管理というケースがあるのか、ちょっとわからなかったのでとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"現在、共同事業体ということでは、図書館の運営もやっていると聞いております。各法人、４つの法人のまとまりがフリーユニティーということで、ただ名称がついているということになっております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"共同事業体で、ここ１つであれば、それは違うと思うのだけれども、そこら辺が区としてどうなのかなと。最初、契約が４つがまとまった１つのものと、というときに本当にさっき言った法人格のないもので対応し切れるのかどうか。","respondent":"飛田障害者施策推進担当課長、川島健康課長","answer":"委員がおっしゃるとおり、今までそういう４つの法人、各指定管理、また、同じ建物というものは、なかったところです。ですので、どういうやり方がいいのか、もう一度、内部で協議しているという現状にあります。 今のやりとりのお答えになるかどうかというのはあるのですが、健康センターが、住友不動産エスフォルタ、それからＮＴＴファシリティーズ、住友不動産の共同事業体という形で指定管理をしていただいているという状況があります。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"４つの法人の中の人数の問題とか経理上の問題というのも相当複雑になるのではないかなというところなので、もう１回、確認だけお願いします。","respondent":"中山障害者福祉課長","answer":"プロポーザルに応募されたときに、４つのそれぞれの法人が一体となって運営をするということで、共同事業体ということで手を挙げてくださいました。どういったやり方があるかについて、今、検討を進めているところです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"この資料も読ませていただいたのですけれども、進捗状況の中で４行目に「２法人が開設前より事業を開始し、教えていただきたいと思うのです。お願いいたします。","respondent":"飛田障害者施策推進担当課長","answer":"こちらの基盤整備の２法人というところでは、１つはゆうゆうという北海道の事業者、そしてグローという滋賀県の事業者です。どのように進めていくかというところを今まさに模索しながら、各施設の連携等、今やっているというところになります。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"いつまでかかるのかなというのを教えていただきたいと思うのですが、４法人ということですので、概要で結構ですので説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"開設まで１年ありますので、まずその１年をめどにして基盤をまとめ、それをまた新しく入ってくる２法人、そこも同じ施設に入りますので、そこでまた連携しながら、今まで培った基盤を整備したところを次の法人にも伝えるというふうに考えております。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"全体に対しての割合というのは、あと３カ所あると思うのですけれども、これはどうなっているのかというところ。ここまではしっかりやってほしいという、区としてはグローにはどういうふうにお願いしているのか、端的にお願いしたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"昨年度、ケアプランの数というところでは、身体と知的が平成２９年３月１日現在７７２件、精神が２６５件、合わせて１,０３７件と聞いております。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"４つにすれば、こういうメリットがあるのだけれども、なかなか中身のある審査はできないのだろうなというのは指摘をさせてほしいと求めました。区民にこういう理念で１つ１つの事業を進めていくという、非常に雑駁な質問になりますけれども、ご答弁ほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今、グローが４つの法人をまとめて行っているところです。そういうところでグローの力を発揮しながら、あとの３つの法人も一緒に力を合わせて行っていければなと考えております。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"人材確保も本当に大変で、月に２回やられている運営会議の中で、人材確保も含めてさまざま課題が見えてきているのではないかなと。１つ１つ課題についてもチェックして解決に向けてやっているという答弁があるのですけれども、現時点での課題があれば、伺いたいなと思います。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、そういうところを１つ１つ解決できるように、しっかりグローが中心となってやっていただけるように進めているところです。子ども一人ひとりに合った研修等も行っていると聞いておりますので、開設前に少しでもよい人材を確保していただければなと願っているところです。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に大きな、新たな、そして期待も大きい施設になってくるので、人材確保というのはすごく要になってくるなと思いますので、ぜひ丁寧に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"品川区第二期データヘルス計画","agenda":"品川区第二期データヘルス計画","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第一期が平成２８年３月につくられて、第一期が２年間で今回６年間となったのはどういう理由からなのかということをお聞かせいただきたいのと、今回。どういうつながりというか、連動というか、そういうふうなことで考えられているのかという点についてもお聞かせほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"今回、データヘルス計画は国民の健康保険法に基づく保健事業の実施等に関する指針に基づき計画しているもので、密接に関係しております。今回の第二期データヘルス計画と第三期国保基本健康診査等実施計画は、また、同じようなことにならないようにしてまいります。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"第一期データヘルスの中でもこれだけ取り組みがされているのだなと改めて私も確認させていただいたのですけれども、用紙が１回送られてきますよね。用紙をなくした場合、なくしてもその場で受けたいと言ったら受けられる仕組みになっているのかという確認もお願いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"少なくとも国保基本健康診査等実施計画が５０ページ程度で、全体で１００ページには満たないと８０ページ前後かなと思います。教育などとの連携ですが、若年層につきましては特に連携はとってはいないのですけれども、また国保について学んでいただきたいなと考えています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１回しか受けられないので、２回受けた場合は１回分は自費になりますよというところにサインをすれば、そういうふうにはなっていないのでしょうか。そこのところをお聞かせいただきたいのと、それから、受診者はかかりつけのところに大体行っているではないか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"実際にデータ等々については、例えば国保の方であれば国保の基本健診が受けられるということで、非常に難しい部分もあります。個々のかかりつけ医の先生方の考え方もまたさまざまでございまして、受診率の向上については、国保の基本健診ですよという部分は統一しております。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"受診券を忘れた、クリニックに誰もが使用できる受診券が置いてあって、それで受けられるという仕組みにはなっていないということなのですか。区民健診のときのような形でぜひご検討いただけないかなと思うのですけれども、その点、お願いします。","respondent":"三ッ橋国保医療年金課長","answer":"置いてあれば、その場で国保基本健診ができますので、実際にはお手間をとらせないような方法とはなっております。かかりつけ医の先生方ももちろん、やはり受診率向上に関しては、なるべく先生方の手をわずらわせないような方法をとっていきたいなと思っています。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"受診の勧奨をよろしくお願いしたい中で、検討してもらいたいなというのが、受診率向上対策の(2)です。だから、そこら辺も先々考えておいてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"平成３０年度に一、二カ所モデル実施、地域別にちゃんと受診率をずっととられてきていたということがすごいなと単純に思ったのですね。受診しやすい体制を構築するというのはどういうことなのかなというのと、どこか調査なんかは委託されたのか、伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"モデル実施の部分ですが、地域別のデータにつきましては、健診の状況を地域別にはかってあります。詳細な分析をしていただいており、事務局といたしましては、区が事務局となっております。","id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"受診しやすい体制というのは、受けていない方には引き続き通知をとおっしゃっていたのですけれども、それなのか、もうちょっと違った形があるのかというのと、あと、委託先はどこなのかというのを伺えたらと思います。","respondent":"三ッ橋国保医療年金課長","answer":"２年、３年受診していない方にはこのように工夫しましょうと、できる限り受診しやすい体制をとっているという部分です。あまり聞きなれないかもしれないのですが、その分野のエキスパートでございまして、株式会社ミナケアという会社です。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"２３区で５０％を超えているところがあるのだから、三十五、六％まで持っていこうみたいなのはちょっといかがなものなのでしょうか。最初からそういう計画なのかと、いきなりそういうふうになってしまうので、そこのところはどうなのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"実施計画の部分にも関係してくるのですけれども、だけれども、地方自治体によっては４５％程度でいいですよという考え方があります。品川区全体から考えますと、より力を入れていきたいという考えで、こちらを挙げしています。","id":"exchange-030"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"教えていただきたい点が何点かあるのですけれども、教えていただきたいのですけれども、そこら辺も教えていただけたらと思います。そうすると、一般相談なしに計画相談だけというのは、どういう形であり得るのかなというあたりもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"要するに事業所の名前ではなく、障害者相談支援センター何々とするのか、地域ごとにわかるような形に変更したいと考えています。４つの拠点相談支援センターも、連携の仕組みをつくることで、なるべく身近なところでケアプランの作成ができるようにしていきたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"お話を伺いにいったりもしたのですけれども、大変な状況というのも伺ったのですが、数字がわかったら教えていただけないか尋ねました。","respondent":"中山障害者福祉課長","answer":"そこでの体制というところですが、心身障害者福祉会館では５人の常勤職員が対応しております。福栄会相談支援センターは常勤と非常勤も含めて６人、特に相談のところを中心に３人の職員が、計画相談と委託相談というところで従事しています。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"相談もあるので、一般相談が拠点の相談支援センター４カ所でやっているということになると、まず回っていかないという状況になると思うのですね。もう１つ、１年何カ月後までは今の体制でいくのか、そこら辺はどう考えられているのかという点についてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"児から者まで一貫した相談がいいのか、あるいは児から者まで連続した相談支援の仕組みをつくっていくのか、これらの課題を今まさに検討しています。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"支給決定３７人で、下のところには支給決定数は５９６件と書かれているのですが、そこら辺の中身についてもお聞かせほしいと求めました。私も荏原地域に住んでいまして、そこら辺の具体的な見通しというのはどう考えられているのかについても説明を求めました。","respondent":"中山障害者福祉課長","answer":"は認識するところからスタートだなと思っています。その他、さまざま情報収集に努めていければと思っているところです。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、その点を１点お聞かせいただきたいのと、グループホーム金子山なんかについても区が土地を取得して無償で提供してというのがありましたよね。今回、そういうのをもっと進めていくような方針を持ったほうがいいのではないかなと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"グループホームが１個なくなってしまうということもありまして、急ぎ、補正もお願いして対応したところです。土地の情報も注意はしてまいりますが、賃貸型のものも民間の事業所と相談して、荏原地域にこうした事業所を開設できればと考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここはどうですかという形にするのが基本なのではないかなと思うのですけれども、その点も最後、お聞かせほしいと求めました。それともう１つ、具体的なところで教えていただきたいのが、この中身についても教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"タイムの中にある居場所としては、例えば精神障害者の方が急に就労継続支援Ｂに通うとかということも難しいときに、まずは相談の段階で。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"サポート２４なのですけれども、要項を見ているのですが、登録した人は２４時間体制で相談ができるという体制になっているのでしょうか。その中でされている取り組みとか何かあったら、教えていただけたらと思います。","respondent":"中山障害者福祉課長","answer":"地域活動支援センターの具体的な中身というところになろうかと思います。料理教室とか、そういうものについては一定の利用の契約を結ばせていただいて、通ってきていただくようにしています。","id":"exchange-037"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えてほしいのと、その情報収集というのはどういうことなのか、教えてください。民間からも相談が来るという中で、民間からの情報収集なのかなとも思っているのですが、その辺について教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"この中で、就労継続支援のところは自力通所ということになっていますので、この事業についてはやはり地域ごとにあったほうがいいと認識しています。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"ありがとうございました。どうしてなかなかそううまくいかないかというところの区の考えと、最後、その辺についての考え方を教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"区立でつくるものもあれば、やはり民間主導で民間の方にご協力いただいてつくっていくものがあると思っています。グループホームですとか就労継続支援Ｂ型というのは、必要な支援が何なのかというのをご相談の中で考えられればと考えていますので。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"計画相談をやって、プランが立てられて、それでいいでしょうということで支給決定がされるのですかね、プロセスとしては。そうですかで終わってしまうのかもしれないのだけれども、また、１人１００件という言い方のところの問題をもう１回鮮明にしていただきたい。","respondent":"中山障害者福祉課長","answer":"すみません、私の説明もちょっとわかりにくかったと思います。専任の人を置くためには、ご相談しながらにはなると思うのですけれども、なかなか専任の人を用意してもらえないのではないかと考えているところです。","id":"exchange-040"},{"speaker":"若林委員","kind":"意見","question":"こうですよね。計画の案から支給決定、計画の案が外れるところは、３ステップ、何週間、何カ月ぐらい今かかっていますかとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"実際に、医師の診断書もいただくことを考えると、最低でも１カ月ぐらいはかかると思っています。２週間ぐらいで大丈夫だと思うのですが、主治医の意見書をもらったりという作業が入ることで、１カ月以上の時間を要することもあります。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"１回支給決定者の手を離れてというところも当然あるので、２週間とか１カ月半とか２カ月というと、ちょっと幅があり過ぎるのではないですかと。どうしても時間的に、どうしても少ない、どうですかというのをお聞きしたいと思います。","respondent":"中山障害者福祉課長","answer":"相談支援センターとも話をしながら、２級という級だけではない、一律の支給というのはなかなか難しいというようなお話はさせていただいています。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"要望が１００％通る、こういうことはどこかで最後は線引きしなければいけないわけですから、生活を日々送っていただきたい。丁寧にやっていただきたいなと思うのですけれども、要望というのではなくて、何かお話を聞いておきたいなと思います。","respondent":"中山障害者福祉課長","answer":"ただ、ご相談者の相談の受けとめのところをしっかりやりながら、最終的に支給の枠というのは全体のバランスとかということも出てくると思います。社会参加というのはすごく大事なことだと考えていますので、お一人お一人に向かって対応ができればと、これから頑張ってまいります。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"Ａ３の２枚目のサービス基盤のところなのですけれども、区外を利用されている方もいると思うのですけれども、これはそれぞれ区内の定員数なのですか。それぞれ教えていただきたいのですが、２３区で見てもやはり整備率が少ないと思うので、区外利用者の部分を伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型、Ｂ型のところですが、プチレーブがＡ型になります。なおかつ近隣の区外の就労継続支援Ｂ型を使われている方というのが、現在、大体２０人から３０人の間ぐらいと考えているところです。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"毎年出される要望という中では、そしてグループホームを増やしてほしい、これも団体の皆さんから毎年出される要望ですね。ここを増やしていくべきだと私も思うのですが、やっぱりもうちょっと増やしていくべきだと思うのですけれども、もう一度伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"荏原地域にという話は、当然、今回計画にも載せますし、所管にも話しています。そうした中で決まっていくのかなと考えていますので、事業者側と話をしながら、できるところから進めていければと考えております。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やっぱり２３区で見ても足りないというこの状況はぜひ改善させて、改善できるところだなと思いますので、積極的に進めてほしいと求めました。大崎、東と西で分けるという見方というのは、今までも障害者福祉のところではしていたものなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"荏原東、西というのは、より地域に点在したほうがいいだろうということで、荏原の地域も広いので、戸越・中延のほうと、あと旗の台・小山のほうと分けて考えてみればいいのかなという形で、今回このようにさせていただいています。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど専門的なところを求められてということで、１２人の方の資格を教えていただきたいのと、障害児の相談支援事業の体制も説明を求めました。","respondent":"中山障害者福祉課長","answer":"なので、１２人全員が、基幹相談支援センターの業務も担うのですが、それだけの業務をやっているわけではないというところです。この体制で全体の基幹相談支援センターですとか、あるいは区の役割、福祉事務所の役割を分担しながら担っているのが現状です。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、障害児の相談支援事業は、非常勤の心理の方が１人だけでやっているというところなのでしょうか。障害児の相談支援事業の体制、資格と人数を説明を求めました。","respondent":"中山障害者福祉課長","answer":"これも障害児の相談支援だけをやっているわけではないです。ほかに療育支援担当というのがおりまして、合計３人で、児の相談支援のところを担っております。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":48661,"voices":133}},{"id":"h30-20180122-8","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"建設委員会","time":"午後 １時００分～午後 ３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","agenda":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今度は禁止区域の境目で放置自転車が増えてしまったという話も伺ったそうで、１から１０番地、１０番の地区は今指定されていないところですけれども。伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"そちらのほうで、各駅に向かいまして警告文をつけて、それで撤去を実施しております。それから、皆さまの要望等、そういったところへ個別に区の職員が行きまして警告文を貼りつけて撤去するような対応をとっているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"大体禁止区域の撤去の頻度というのですか、それとあと区域外のところのそういった対応というのをどれぐらいの頻度で行っていらっしゃるのか。これ仮に１丁目全域指定された場合というのは、そのことでどのような影響が出るのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"昨年度は４月から１２月までの９カ月間で、それぞれ３,２４９台の警告文を貼りつけまして、１,３１８台を撤去しております。それぞれ陳情を受けまして、対応としましては１月から１２月までで５４６件の陳情を受けまして、５１６台の撤去を実施しているという状況です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと幾つかお伺いしたいのですけれども、現状の台数というのは先ほど伺ったのですが、全然わからないのですか。それをお伺いします。","respondent":"桑波田交通安全担当課長","answer":"やはりそこで働いている方ですとかそういった方も考えられますので、そういったところにご案内いただくように協力依頼を実施したところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後２点なのですが、大体いつぐらいにどういう経緯で拡大してきたというのがわかれば教えていただきたいのが１つと、充足しているのでしょうか。伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"駐輪場周辺の状況ですけれども、区営の駐輪場につきましては４８６台の駐輪スペースがありまして、あと民営が７７台ほど実施しております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。区もそうですが、そういった民間への附置も含めて増設をぜひ進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"放置禁止区域を広げてということですけれども、要はこの放置自転車をなくしてほしいということが一番のご要望なのだろうなと受けとめています。今後さらなる、もしこれが広げることでどういういい点があるのか、広げてどうなるのかというところの予想をちょっとお話をほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"今朝また朝一番でそういった場所も見てもらって撤去を完了したということで実施しております。なかなか五反田につきましては本当に足りない状況もありますので、なかなかすぐに拡大というにはいかないのではないかと考えております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"では、今区の駐輪場が赤で示されていますけれども、今後この地域で駐輪場が拡大をされるめどというのが何か検討されているところがあるのか。そこのホテルに対しての駐輪場の確保の要望ですとか、今後駐輪場がつくれるかどうかというところの見通しをお聞かせほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"施設の老朽化等もありますので、総合的にそれぞれの地区にあった何ができるのか、こういったものは来年度以降検討してまいりたいと考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"ちょっとそこに時間を見計らって行っていただいて、直接お話をしていただくというようなこともお願いができるのかどうか。そこまで区としてやっていただけるのかどうかというところを確認をしたいのですけれども、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"日にちを変え、朝であったり午後であったり、そういったところでシフトしながら警告文等も貼っております。持ち主がいつ来るかわからないようなそういう状況がありますが、時間を変えながらそういったふうに添付していくような対策はとれるです。","id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"そういう地域の店舗さんたちも含めての自転車対策とかというのは議論したことはあるのでしょうかというのが一つ。地下駐輪場とかというのも必要になってくる可能性もあるし、利便性も含めて考えると、その辺は何か動きがあれば教えてほしいのです。","respondent":"桑波田交通安全担当課長","answer":"町会のほう、なかなか折り合いがつかなくて駐輪場の設置までには至らなかったというような状況もあります。ここの放置区域内ですけれども、放置自転車等は大体平均で１日２０台から３０台は確認しているという状況にあります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"駅ですから駅を利用されているのだから、ＪＲ、都営も走っていますよね。そこは事業者も区も含めての協力体制を仰ぐということは必要になってくるのではないかと思うのですが、その辺の動きはいかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"これは表看板ですとか客引きとか総合的なものなのですけれども、そういったところで駐輪対策等も進めておりますので、引き続き対応をとっていきたいなと考えております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"今の続きなのですけれども、東五反田一丁目１８番付近ということなのですが、周辺の東五反田二丁目、大崎五丁目、西五反田ということで、ほかの地域における同種同様な立地条件のところというのは、こういうような苦情なり話は出ているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"国道、都道であればそれぞれ第二建設事務所のほうにお声を伝えて対応を依頼しています。やはり個別に対応させていただいているですが、武蔵小山はそういった声はありますけれども、それ以外は特にございません。","id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"「公共の場所で」「区長は」ということで第１条に書いてありますけれども、陳情者１名ですけれども、どのように感じていらっしゃるのかとの意見を述べました。","respondent":"桑波田交通安全担当課長","answer":"これは歩道にありまして、この歩道は２メートルほどありまして、車両は通りませんけれども歩行者の通行には今のところ支障はないのかなという考えてあります。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、この陳情者個人で、陳情ですから賛同者がいないということは、この方個人の意思のもとにこの陳情が出されてきている。それはどうなのでしょう。","respondent":"桑波田交通安全担当課長","answer":"この陳情者の方の住所、住んでいらっしゃるマンションの目の前の道路を言われている状況にあります。ですから、裏取りはしていないのですけれども、やはりそういった自分の目の前の景観に対する思いみたいなものもあるのではないかと推測されます。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"地域の指定なのですけれども、陳情者は一丁目全域と述べておりますけれども、番地ごとに部分的な範囲の拡大というのはできるのかということをまずお聞きします。","respondent":"桑波田交通安全担当課長","answer":"番地といいますか通りですとか道路に関して指定をかけしています。どっちにしろ番地と絡んできますので、番地等で指定してきた、全域ではなく個別でも指定してきた経緯はあります。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"陳情者は、「通勤・通学のために日常的に使っており」というふうに述べておりますけれども、今課長からご答弁あったとおり飲食店や郵便局を利用される方もいらっしゃるということなのですが、割合というのは大体どの程度把握がされているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"昨年の１２月の段階で２０台ほどございまして、そういった警告等も効いてこちらには放置しないような状況になったと思います。さらに残っている部分は、やはり近隣でお住まいの方ですとかお店の利用者、こういったものが残っているような状況にあると考えております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"となると、残っている放置自転車、つまり飲食店と郵便局で利用されている方だと思われるのですが、時間的にはやはり放置する時間というのは短いというふうには区としては理解されているのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"やはりお昼の時間帯に食事をしている方が駐輪している場合もありますし、また朝から夕方になっても置いてある場合もそれぞれあります。短い時間のものもありますし、長い時間夕方までとめているような状況の自転車もあるです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"景観上の問題というのもかなり大きいと思いますので、適宜適切なご協力というのを引き続きお願いをぜひやっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"いながわ副委員長","kind":"意見","question":"本当に細かく放置エリアを区切っていくと、これは今五反田の話ですが、区内何カ所かに指定はされていると思うのです。それともとりあえず指定されたからあと１０年、２０年はこのままにしておこうかという考え方なのか、そこをちょっと一回説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"放置禁止区域は各駅で実施しているのですけれども、過去に平成２２年に区内一斉に放置禁止区域の見直しということで変更等を実施したところです。それぞれによって違うところもあるのですけれども、その辺は柔軟に対応してやっていきたいと考えているところです。","id":"exchange-018"},{"speaker":"いながわ副委員長","kind":"質問","question":"まさに８年以上たつ、どんどん１０年たってくるわけですから、そこはもう柔軟に対応していただく。ではこのぎりぎりのところに置いておいた自転車はどうなってしまうのですかという話もあれば、自転車が置いてありますね、一言あれば。","respondent":"桑波田交通安全担当課長","answer":"外へ外へとまた逃げていくような状況もありますので、やはりそういったところも勘案しながら、全体的な放置禁止区域もそういった状況の変化によって対応していきたいと考えているところです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"ましてや丁目全体となりますと影響もあるので、住民合意のプロセスを得るという点では少々課題が変わるというのは事実だと思います。まちづくり全体の中でというほかの委員からの話もありまして、そういったこともありますので、継続が望ましいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"西本委員","kind":"意見","question":"継続ですが、先ほども申し上げたように、ここだけではないと思うのです。同じような問題、もう少し広げてしっかり議論する場も必要なのかなと非常に感じましたので、継続的に議論してまいりたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としてもぜひとも再調査をしていただきたいのと、あとまたここの地域の状況を見守りたいということで、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"平成３０年２月都営住宅入居者募集","agenda":"平成３０年２月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"毎月募集ということでお話がありましたが、毎月募集実施の目的や背景をどのように区としては把握していらっしゃるのでしょうか、伺いたいと思います。それと、毎月募集がこれからあるということになると思うのですが、区民への周知という点ではどのようになされるのかお伺いします。","respondent":"長尾住宅課長","answer":"東京都から聞いているところですと、子育て世帯の入居機会を多様化するというところを主眼として、こちらの毎月募集を開始したと伺っております。区民への周知につきましては、区のホームページ上でも追加してご案内できるようにしていきたいと考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとなぜ比較的低倍率の住戸が募集の対象なのでしょうか。若者単身者が募集から除かれているという理由はなぜなのでしょうか、お伺いします。","respondent":"長尾住宅課長","answer":"おそらくその世帯に向けては定期的な時期に行うというよりはもう少し申込みいただく機会を増やすというところを検討されているのではないかなと推測…〔「単身がなぜ」と呼ぶ者あり〕 すみません、今回始まっているのは記載しているような若年夫婦・子育て世帯等の方を対象としたものになっております。募集されている住戸につきましても、２人以上の世帯向けという住戸しか掲載はされておりませんでした。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"若者の非正規雇用率が５割を超えていますし、親元にいざるを得ないというか、そういった状況が若者の結婚や自立を困難にしているのではないかと。ひいては、単身若者への住宅政策も考える必要があると思うのですけれども、ちょっと関連して区の見解をお伺いしたいというのが２点目です。","respondent":"長尾住宅課長","answer":"若者に限定せず単身者向けというところですと、区営住宅も都営住宅も一定程度はありますので、そちらのほうをご活用いただく。単身者用の住宅というのもありますので、そちらのほうを使っていただくという形になると考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、若者の単身者への住宅政策を考える必要があると思うのですけれどもいかがでしょうかと伺ったので、区の考えをお聞かせいただきたい。都営住宅、若者単身者も募集対象に加えることを求めたほうがいいのではないかと思うのですけれども、そういった先ほどの認識とあわせてお伺いします。","respondent":"長尾住宅課長","answer":"今あります区営住宅の維持管理を通して公営住宅としては引き続き提供していきたいと考えております。民間の住宅ストックとしては一方で一定程度あると考えておりますので、そちらを活用いただくというところがまずは前提になるかと思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから若者の自立や支援、やはり住宅政策の対象に加えていくべき若者がたくさんいるということを言いたいのです。そういった認識をぜひ今後ちょっと持っていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"ということは、最低でも５０はあいていますよという話ではないですか。多分そこら辺はどういうからくりになっているのかなと思うのですが、いかがか尋ねました。","respondent":"長尾住宅課長","answer":"今までの都営住宅の運営上このぐらいはあくだろうという見込みも立てながら都営住宅としては公募をかけているのだと推測されます。詳細なところまではちょっと今把握しておりませんので、現時点でわかっている内容だけのお伝えになってしまいます。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"だけれども、入れるのはもしかしたら４月になるかもしれないし、６月になるかもしれないしというような。だから、とにかく５０戸の中に入れば何とか１年の間に入れるかもねという程度で、その辺のニュアンスはいかがか尋ねました。","respondent":"長尾住宅課長","answer":"ご案内できるような段階になれば、住宅供給公社から申請者へご連絡が行くということになりますので、同じ時期に皆さんが入れるとは限らない状況です。","id":"exchange-029"}]},{"id":"topic-03","title":"（仮）品川区環境基本計画の素案について（パブリックコメントの実施）","agenda":"（仮）品川区環境基本計画の素案について（パブリックコメントの実施）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ですから、２０１３年を基準にするというのは私はちょっとどうなのかなという思いがあるのです。率直に伺いたいと思います。","respondent":"小林環境課長","answer":"これをしっかりやっていけば区としてのしっかりとした役割というのは十分果たしていけるべき計画になっているかなと考えています。ただ、今回１０年間示した部分ですが、先につなげるといった意味でも十分対策はとられた計画ではないかと捉えているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０１３年にこだわらずもっと、例えば京都議定書の場合は９０年比なわけですから、そういったことをやるべきだと思いますがいかがでしょうか。目標について、家庭部門は１人当たりの排出量の目標になっておりますが、床の総量が増えるか増えないかというのは問わないということなのか尋ねました。","respondent":"小林環境課長","answer":"２０１３年比というところについては変わりないと考えているところです。建物の更新等々について進んでいけばある程度ここまで下がるという将来予測を立てた上で今回この数字を策定したというか、目標を設定したです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"冊子のほうの１７ページとかに書いていますね。そういった予測というのは立てていらっしゃるのか伺いたいと思います。","respondent":"小林環境課長","answer":"建物を運営していく上でエネルギー管理を行うために、一定規模の建物につきましては、省エネに対する配慮がなされていると考えているところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ただ、今の大きなビルというのは基準があるから高性能ですからという話も何回か伺っていますが、それはそのとおりなのですが。再開発ビルから排出されるＣＯ２の算出、そして公表する仕組み、いかがか尋ねました。","respondent":"小林環境課長","answer":"確実に業務部門、新しいビルが建て替わったりあるいは大きなビルができたとしても床面積が増えている中でも十分に削減が図られているです。区として新たに何か監視していく必要があるかというところにつきましては、現在のところ考えているところではございません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、目黒川対策、水質改善という点では今回の計画にどのように盛り込まれているのかお伺いしたいというのが１点です。やはり柱立てというのをしていく必要が私はあると思うのですけれども、そこについてもぜひしていただきたいのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"自然エネルギーですが、先ほどご説明しましたとおり、そういったところで自然エネルギーについての活用事例等々も今回打ち出したところです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"前回説明会をやっていただきたいということで要望させていただいたのですけれども、ましてや温暖化対策であったら地球全体にかかってくることだし。ぜひ積極的にこれはパブコメとあわせて説明会の設定などをやってほしいと求めましたが、これも要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"温室効果ガス削減目標なのですが、２０１３年を基準にということで、今２０１７年度はどこまで来ているのでしょうかというのを教えてください。もうちょっとかわいいというか何というのでしょうか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"かわいいですか。今後の課題なのかもしれませんけれども、ぜひそれも考えていただきたいなと考えていますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"２０１５年までの傾向で行きますと、やはり削減傾向にあるというのが傾向として見えるところです。〔「バッテン印ではないだろう」と呼ぶ者あり〕 家庭に対して助成等を行っているところですが、啓発として区として進めていければと考えているところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"もうちょっと工夫していただきたいなと思いますので、これは要望としてお願いしたいと思います。２０１５年。","respondent":"小林環境課長","answer":"２０１５年、１６ページですが、区における温室効果ガス排出量の推移というところがあります。この段階で２,２３２という数字がありますので、徐々に減少傾向にあるというふうに考えられるところかと考えております。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"本当に数字として示すことが可能なのですか。それの全体の品川区の状況、エネルギーの必要性等を含めて考察はどこまで進んでいますかということが非常に気になるのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"温室効果ガス排出量につきましては先ほどご説明した１６ページですが、使った量に対する推移をお示ししています。品川区内でいきますと、先ほど説明がありましたように、やはり特に使用量という観点からいきますと削減傾向にあるのはやはりありますので。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"なぜかというと、では確かに震災があって省エネということを非常に皆さん意識しながらやっていましたけれども、でももう７年たつわけです。今のお話だけだと、ちょっとこれ本当に４０％ってやるのって、その辺見直しとか今後の検討とかどういうふうにされていくのか尋ねました。","respondent":"小林環境課長","answer":"１つは品川区だけでもちろん取り組むことではなく、区がそれぞれ連携し合いながらそれぞれの施策を進めていくことが一番重要かと考えています。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"もしかしたら４０％行ってしまうかもしれないのですかね、そういういろいろな要素を見ながら考えていくと。目標値というものをより正確な数値に近づけていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"最後３点目なのですけれども、３６ページの生活環境のところで、騒音については過去のデータは載せられないのでしょうか。環境基本計画として生活環境について騒音を減らしていくというふうにも記述されているので、その点いかがお考えなのか尋ねました。","respondent":"小林環境課長","answer":"それとあわせて、例えば自動車だけではなくてシェアサイクルの活用とかそういうところも少し捉えながら進めていきたいと考えているところです。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"定期的に啓発というのを打っていかないと、広報しながわでの広報を積極的にお願いしたいのですけれども、その点はいかがお考えでしょうか。２点目の広報についてのお考えを説明を求めました。","respondent":"小林環境課長","answer":"あるいはそういったところですが、例えば今も環境に関するホームページというのをまず環境情報活動センターを通じて発信しています。例えばアプリを活用した情報発信の活性化というのも今後検討を進めていきたいと考えておりまして、それらを使って。","id":"exchange-043"}]},{"id":"topic-04","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"西本委員","kind":"質問","question":"環境表彰式ということで、いろいろ受賞された方がいらっしゃるのですが、副賞が何かあるのでしょうか。何かいただけるのですかということですが、それをちょっと説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとそこら辺を、具体的にできているものがあれば教えていただきたいなと思いますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"それと、お話がございましたとおり、基本的には区内で集めたものを区内でやはり消費するのが一番きれいな形かと我々も認識しているところがあります。今現在子ども食堂を実際に所管しているのが子ども家庭支援課ですので、子ども家庭支援課と今連携を図って。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"トロフィーということなのですが、トロフィーですか。これも子ども食堂の運営主体によってはいろいろと要望があるかと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"フードドライブについて、１点ちょっと教えてほしいと求めました。すごいたくさん使っていただきたいということで、この食料等が集まってきた場合に、その辺のお考えをお聞かせほしいと求めました。","respondent":"小林環境課長","answer":"２点目の、今、他区から情報をいただいて今分析をしている最中です。集まったものについては子ども食堂の中で十分活用できるのではないかというふうに捉えているところです。","id":"exchange-047"},{"speaker":"いながわ副委員長","kind":"確認","question":"宮前フラワーズですとかある中で、長谷工コーポレーションというのは、これは管理組合を指しているのですか。確認だけ。","respondent":"溝口公園課長","answer":"それに対してどういう維持管理をしているのか、そういったところを今回の第二部の中で、環境活動の一環として発表していただくという形で長谷工コーポレーションのお名前が出ているということでご理解いただければと思います。","id":"exchange-048"},{"speaker":"いながわ副委員長","kind":"質問","question":"みどりの顕彰はこの３マンションを代表して長谷工さんという認識でいいわけですか。なぜ管理組合が、そこに資源を分別して入れるというのは通常の流れのような気もしないでもないのですが、どうしてこんな管理組合が多いのか。","respondent":"工藤品川区清掃事務所長","answer":"この多い理由といたしましては、今現在、活動団体、２８年度末の実績ですけれども、大体６１６団体があります。その中で管理組合が４２８団体で登録されているというところがございまして、結果的にこのような形になったです。","id":"exchange-049"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"当たり前のような気がするので、ストックヤードがあるわけですから。簡単で構わないので。","respondent":"工藤品川区清掃事務所長","answer":"今お話ありましたように、そういった小さな団体でも継続して行われているとかそういった部分につきましては、当然この表彰の対象にも入れるような規定もありますので、そういったところもしっかり見ていきたいと考えています。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"フードイベントをやるわけですけれども、ここのところでやはり不特定多数から集めるというので、何かこれをやる中で事故が起こるとも限らない。危機管理上の何か今指針というか、そういうものが区のほうで対策を立てているのであれば、お答えいただきたい。","respondent":"小林環境課長","answer":"フードドライブに対しての安全性ですが、まず集めるときにお名前と住所等個人情報は基本的には伺う予定で今進めております。今詳細につきましてはもう少し詰めているところです。","id":"exchange-051"},{"speaker":"大沢委員","kind":"確認","question":"外見ですから確認できるわけではないのですけれども、これは責任の所在はどこがどう負っていくのか、方向性がありましたら説明を求めました。","respondent":"小林環境課長","answer":"そこの中で集めていただいたものというところで考えているところです。そういったものにつきましては、中身をしっかり見た上で全く問題がないものだけを基本的にはお届けするというところで考えているところです。","id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"缶は穴があかないのだけれども、これはどうか尋ねました。","respondent":"小林環境課長","answer":"缶についてですが、基本的には多分目視の調査になるかと思います。缶をある程度揺らした上で液体が垂れてこないか、そういったところもしっかりと見ていきたいと考えています。","id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"責任の所在についてはどのような方針を持っているのか説明を求めました。","respondent":"小林環境課長","answer":"責任についてですが、もちろんお渡しする上では責任については十分とるというか、しっかりと担保した上でお渡しするというふうに考えているところです。","id":"exchange-054"},{"speaker":"大沢委員","kind":"質問","question":"提供する方も善意で出すわけですから、これが何かあったときにこの事業に水を差す部分があるので、そこのところをやはり事業を行う主体である品川区が何らかのかかわり合いはもちろん持つでしょうけれども、そこのところをどのように考えているのか尋ねました。","respondent":"小林環境課長","answer":"まず社協を通じて子ども食堂にお渡しすることになりますので、まずは社協とその辺は調整した上で考えていければと考えております。は社協に届けるというのが区の役割だと思っているところです。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざま今いろいろな部分で善意が善意でなくなる場合もありますので、そこのところ、せっかく善意で皆さんが事業を行うわけですから、善意が善意で済むような形をとってほしいと求めました。","respondent":"小林環境課長","answer":"１点、先ほどちょっと答弁漏れというかご説明の中で不足がございました。すみません、副賞について今手持ちの資料がございませんではっきりと言えませんが、一応その３点です。","id":"exchange-056"}]},{"id":"topic-05","title":"平成２９年度 区内一斉防災訓練および各地区総合防災訓練の実施結果等","agenda":"平成２９年度 区内一斉防災訓練および各地区総合防災訓練の実施結果等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"「毎年同じなので多少内容を入れかえてほしい」などの意見が出て、これらの課題を踏まえて、お聞かせいただきたいというのが１点です。それと、本部訓練のほうは概要が載っていますが、本部訓練のほうの課題ですとかそういったものについてはどのようにお考えなのか説明を求めました。","respondent":"古巻防災課長","answer":"区としましても、そういった中でどんどん防災訓練のほうへの参加も進めていきたいと考えております。やはり今年やったような２日目以降のことですとか、そういったところをまた新しいメニューで今後も取り組んで進めていきたいと考えております。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"そういう人たちの気持ちやライフスタイルにかみ合った参加しやすい訓練というのですか、参加したくなるような訓練というのですか、改善していきたいとかお考えがあればお伺いしたいなと思います。","respondent":"古巻防災課長","answer":"若い方に対するアピールについては、今具体的にというとなかなか効果的な方法というのがまだ暗中模索なところ、試行錯誤なところがありますので、課題として認識は十分いたしておりますので、今後もこのあたり十分に研究してまいりたいと考えております。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"せっかくの機会ですので何かしら、一部の学年で参加できたとかそういった課題の認識ですとか、何か理由ですとかありましたら。個別の部分はちょっとわからないかと思うのですけれども、教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"１点だけお願いします。これはどのようなものか尋ねました。","respondent":"古巻防災課長","answer":"避難部屋割り当てシミュレーション、いわゆる避難所に充てる部屋の割り当てを実際の避難者に応じてやっているということで認識をしております。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"私、毎回要望しているものと似ているのかどうかわからないのですが、結局、発災時には避難所はいろいろな方がいらっしゃると思うのです。それをぜひ取り組んでいただきたいという思いがあるのですが、それはいかがか尋ねました。","respondent":"古巻防災課長","answer":"そういった考え方の周知啓発につきましても、避難所マニュアル等の充実でありますとかそういった中で十分進めていきたいと考えております。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"大崎中のこの件、ちょっと具体的に知りたいなというのがあるので、何か情報があったら教えてほしいのですが、今でなくて結構です。避難所に対する、避難所訓練にはならないと思うので、そこをまず研究していただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-06","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは周知の仕方はどうしているのか、このチラシですね、とあと実際全面改修はいつぐらいの時期を予定しているのかと２点お伺いします。","respondent":"多並道路課長","answer":"周囲の皆様にはビラを配る予定としております。今後の計画としましては、来年度それを踏まえ詳細設計を行い、平成３１年度から段階的に工事を行っていく予定と現在では考えているところです。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"あそこだと思うのですけれども、非常に子どもたちが遊んだりとかして暑い夏なんかは非常に涼んだりとかしているところなのです。なので、そういうのも全部入れて、いろいろ要望とかも入れて改築、整備という形の理解でよろしいか尋ねました。","respondent":"多並道路課長","answer":"委員のご指摘のとおり、そういうのも踏まえて概略設計ということで地元の皆さんにご説明をして、ご意見をお伺いしながら来年度それを踏まえて詳細設計ということで、時間をとりながら設計を行っているという趣旨です。","id":"exchange-064"},{"speaker":"新妻委員","kind":"質問・要望","question":"この品川区にかかわる部分で、例えばしながわ水族館の営業ですとか、あとそれ以外でも具体的な対応をされたところがありましたら教えてほしいと求めました。","respondent":"溝口公園課長","answer":"具体的に水族館ということのお話がありましたので、私のほうからお答えします。外部からの水も含めて遮断できるような飼育体制を整えているというところで対応済みという形で対応しているものです。","id":"exchange-065"},{"speaker":"新妻委員","kind":"質問","question":"品川区ではありませんけれども、東京都の野鳥の森公園が大井ふ頭中央海浜公園の先のほうですね、あると思うのですが、そこの対応はどうなっているのか尋ねました。","respondent":"小林環境課長","answer":"この１７日を受けまして、１８日に庁内会議を開催したところです。情報共有を行って、また何か死んだ鳥等を見つけた場合は速やかに環境課に連絡頂けるような周知活動を今行っているところです。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":48541,"voices":170}},{"id":"h30-20180122-9","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"文教委員会","time":"午後 １時００分～午後 ４時０９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度新入学の学校選択希望申請理由調査結果","agenda":"平成３０年度新入学の学校選択希望申請理由調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"魅力を感じなくなるというか、あまり小学校と変わらないというふうに感じてくるのかと考えているのですけれども、区の考えを伺いたいと思います。この棒グラフと円グラフの見方といいますか、別々で出している意味といいましょうか、そこを教えてほしいと求めました。","respondent":"有馬学務課長","answer":"この調査は複数回答ですので、その１つの項目について、どのぐらいの人がそこへチェックしているのかということをあらわしております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"グラフのほうからいきますと、全体の中での複数回答の割合ということで、円グラフだと見えにくくなるような気がするので伺ったのです。なかなか大変な状況だと思うのですけれども、この状況をどう捉えていらっしゃるのか、その辺のお考えを伺いたいと思います。","respondent":"有馬学務課長","answer":"中学校のほうは去年だと６１１名のうち６名が入れなかったということで、全体でみれば９９％以上が入学できている状況です。全体として見れば、その程度の割合では入学できているというところを見ていかなければいけないのではないかと捉えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"先ほどのご説明の中で、選択しても待機になって入れるかどうかがなかなかわからないといった中で選択制が問題になってきているのかとも思うのです。昨年度よりどういった状況になっているのか、入れない子どもが増えそうか減りそうかということはわかりますか尋ねました。","respondent":"有馬学務課長","answer":"そこは今、まだこうなりますというような明確な回答はできかねますけれども、それに近づけるかどうかというのは見ていきたいと考えています。日野学園の前期課程も含めると、その人数が若干増えていますので、そこもしっかりまた見ていきたいというふうに思っているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"２、３の順位が例年ほとんど同じという、そういうところをどういうふうに見ているのかというところを改めて伺いたいと思います。入学予定者が１０４名、転居も含めて対象の子どもが少なくなったということでいいのかどうか、そのあたりのことを伺いたいと思うのです。","respondent":"有馬学務課長","answer":"いろいろと学校を見る中で、学校説明会へ行ったりだとか、学校公開へ行ったりだとかして見ているというようなことがうかがえると考えています。入学予定者数は１０４名、そのときの住基人口が１０８名という資料をお出ししております。","id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"２５％程度、２５％から３０％程度が選択を希望されるという認識でいればいいということでいいのかどうか、そこを後で確認をしたいと思います。人口動態と就学人口の関係をどういうふうに見ていらっしゃるのか、どういうご苦労があるのか、その辺を伺いたいと思います。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"教育改革プラン２１以降、学校は学校選択制を１つのきっかけとして、これまでずっと努力をしてきました。学校と地域とのつながりが他区よりも濃くなっていると思いますし… 教室数の不足とか教室の確保に対応する部分ですけれども、０歳から６歳という人口が、住基上わかりますので。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"そこのところとの兼ね合いをどういうふうに見るのかと思うし、現場の先生に伺うと、風呂敷包みを持って家に帰る。あまりここばかりやっていてもあれだから、最後に１点だけ、その辺をどういうふうに考えるかというところだけ伺って終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松永委員","kind":"質問","question":"それとも番号を引いて、その番号が順位になっているのか、どのような形で第２位の方の抽選が行われているのかお伺いします。例えば、この日野学園については、キャパを超えているように感じるのですけれども、どのような形で対応されているのか伺います。","respondent":"有馬学務課長","answer":"ただし、もう今はこの時点では受け付けはできませんということを丁寧に説明して、そちらのほうの提出をお願いしますというような対応をしております。","id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"例えば、家庭科室とか図書室とか、どういったところを普通教室に変えるなど工夫をされているのでしょうか。〔「漏れた人ではなくて」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"報告事項と関係ないことなのですが、発言を認めてもらえれば。教育委員会、子ども未来部の皆さん、天気が大雪になってきましたけれども、とらなければいけない対応は大丈夫か尋ねました。","respondent":"大関教育総合支援センター長、高山子ども育成課長、佐藤保育課長","answer":"徹底するように通知を出して、各学校は今、そのような対応をとっております。警報が出た場合には、すぐに休校… 私どもは、児童センター、それからすまいるスクールを所管しておりますので、そちらの対応を報告します。１９時までの延長の時間帯もありますが… 公立保育園に関しましても、今、両課長から説明があったのですが、朝一番の段階で回覧で全保育園に必要な対応をするようにということをお伝えしております。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"１つは、このアンケートの内容は、毎年同じ内容なのでしょうか。もしくは、その年その年に応じて増やしている項目だとか、変えている項目があるのでしょうかというのが１つです。","respondent":"有馬学務課長","answer":"変更したときに今の形に変えておりまして、その平成２５年からは項目は同一で、特に変えているところはありません。は転居予定ですとか、未記入の方もいらっしゃるというようなことですので、おおむねそういった中身になっているところです。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問","question":"3)番と8)番の設問は、そうした設問が必要なのではないかと思うのですが、こういう考え方はいかがでしょうか。どのように思われますか尋ねました。","respondent":"有馬学務課長","answer":"何か一言でもコメントをいただくことがいいのかということを検討したこともありますけれども、検討はしているのですけれども、そういったところで。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"それはアンケートのやり方としてはどうかなと私も思いますので、非常にその辺のアンケートのとり方の難しさは理解しているつもりです。３年に１回なのか、運営に生かせる評価の部分という項目をつけるというのも１つあるのかなと思いましたので、お聞きしてみました。","respondent":"有馬学務課長","answer":"やはり平成２５年のときから見ますと、学校が近くて通学しやすいとか、友人・兄弟関係というのは上位にありました。それは学校がいろいろＰＲをされて、１つはそういう傾向が今は出ていることから、あえて今は項目を変えずに継続しているという状況があります。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先日も活躍した部活の話を伺いましたけれども、見られるような方の配置をぜひ東京都のほうに強く要望していただけると、その点についてです。３クラスなので、ここも１つ増えるので、そのあたりをお願いします。","respondent":"品川庶務課長、大関教育総合支援センター長、有馬学務課長","answer":"１年生から和式トイレの使い方等は説明をしているのですけれども、この辺を見ながら、洋式化を進めていくよう学校の環境整備等を行っている状況です。… これは全区に対して東京都が支援を行っていく方向で今準備を進めているというふうに伺っておりますので、支援できるような形を、今。あわせまして… あるいは、すまいるスクールで使っていたところを１年生の教室にして、基本的に教室は確保していくという対応をとっているところです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"関連して伺いたいのですけれども、どこの学校がどういう状況にあるか、全体像を私たち委員としてもつかむ必要があると思うのです。出所は覚えていないのですけれども、１週間に１回あるいは２回ぐらいは休みなさいという通達ですか、それについて品川はどうか。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"今、具体的にはここでは１つずつはあれですけれども、そういったところをまず教室にしていくというようなことで対応をしているというものです。いざとなったらそういうふうな対応もしていくというようなことで… 各区はそれがおりてくるのが３月か４月の時点で、区としてもそれを区の状況に応じて当てはめる方向で考えているところです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"これは蔓延してしまったというか、もうおさまったと考えていいのかということと、どういった対応をされてきたのか伺いたいと思います。保育園のほうも昨年から４倍になったというところで、この原因についてはどう考えていらっしゃるか伺いたいと思います。","respondent":"有馬学務課長、佐藤保育課長","answer":"翌週ですけれども６年生までということで、しっかり対応していかなければいけないということが、今回の旗台小学校の例でわかったものです。それをはじめとして… １月、２月という３カ月ぐらいに分かれて行われておりますが、１２月にピークが来たというふうにはある程度見込んでおるところです。","id":"exchange-015"},{"speaker":"鈴木（博）副委員長","kind":"確認","question":"保育園によっては、インフルエンザの検査をして陰性なのを確認してから子どもを寄こしてくださいとかと指導しているところが、私立の保育園である。ということで、一言いかがか尋ねました。","respondent":"有馬学務課長、佐藤保育課長","answer":"きちんとした対応さえとれば発症することはやむを得ないという部分も理解できましたし、兄弟の部分もわかりましたので、今後は学校のほうにもそういうことをきちんと伝えていきたいと思います。 委員ご指摘の趣旨を踏まえまして、区で定めている保健マニュアル等も適切な状態にして、各園に周知を努めてまいります。よろしくお願いします。","id":"exchange-016"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"２ｍ以内で咳とか鼻とかを浴びた場合に移るので、あと２ｍ以内にできるだけ近づけないということに関してご指導をしっかりお願いしたいと思います。〔「うがいはいいんですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"みんなも気をつけなさいとか、それこそインフルエンザに対する啓発なども含めて、そういった所管をまたいだ連絡などはどのようになっているのか尋ねました。","respondent":"有馬学務課長、高山子ども育成課長","answer":"すまいるスクールをやっておりますので、子ども育成課、それから保育課のほうに情報提供という形では行っているところです。もう１つ、教育総合支援センターも含めて、その３課には、毎日、その都度… 今、すまいるスクールに関しては児童センターの館長が一時的な統括をしている関係にありますので、情報提供という形でつながっております。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターに遊びに行った小学生が、隣の小学校でこうなっているとか、そういうのがわかるのでしょうかということです。","respondent":"高山子ども育成課長","answer":"そこまでの対応はとっておりませんが、館長としても、個別具体的に何々学校の何々学級というようなところまでの周知はしておりません。必要に応じて情報提供していくということが適当かと考えております。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"そういうことで、利用されている方や保護者の方に、具体的に何年何組が学級閉鎖というところは、いろいろ情報の面があるのかもしれませんが、今、学級閉鎖ですということは何らかの形で、掲示なり何なりして周知できる形がいいのではないかと思うのですが、検討をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までにお伺いしたいと思います。今年度は１９校３２学級が学級・学年閉鎖をしているという数字で、その傾向を教えていただきたいのと、まず説明を求めました。","respondent":"有馬学務課長、佐藤保育課長","answer":"昨年は、やはり１月に学校は爆発的に増えてきています。２週目に入って、また今週、来週で増えるのかなというふうに見ているところです。 保育園、幼稚園に関しまして、学務課長が答弁したとおり、昨年は一昨年よりも多かったというふうな認識です。今年度に関しましては、先ほどご答弁したとおり、保育園に関してはちょっと前倒し、幼稚園に関しては例年どおりの発生数です。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"予防接種をしているお子さんが何人かという把握などは、これは調査されていないと思うのですけれども、予防接種との関係はどういうふうに捉えていらっしゃるのか尋ねました。","respondent":"有馬学務課長、佐藤保育課長","answer":"小学生のインフルエンザの予防接種は、今のところ、保護者にお任せというような対応になっているのが現状ではないかというふうに思っています。ただ… 手洗いの励行、あと、園内のおもちゃの消毒等も徹底して防止に努めているです。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"所管が違うので、ここで参考までの質問は終わりにしたいと思うのですが、やはり予防接種というのは大事なところなのかなと、今お話を聞いていて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"ぷりすくーる西五反田の今後","agenda":"ぷりすくーる西五反田の今後","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"子どもや保護者への影響はどういったところが変わってくるのか伺いたいと思います。こちらも継続されるのかということをお聞きしたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーる西五反田は、設立当時より、保育から幼児教育まで一貫して対応していく理念のもとに進めてまいりました。それから、地域子育て支援センターについては、これは今後も継続してまいります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"今回の場合はどうなっていくのかということをお聞きしたいのですけれども、何を貸し付けて、公私連携がどういうことになるのか伺いたいと思います。伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"公私連携法人をつくる際に、ぷりすくーる西五反田については、土地、建物とかの無償貸付等を想定しております。そういうような形で分かれておりますので、認定こども園になったからといって、特にその辺が大きく変わるものとは認識しておりません。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今の既に保育園と幼児教育部門とで生活リズムが違う中で問題点は特に出てきていないということでよろしいのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"現場のほうから伺っている段階では、そのようなことで特に問題等は聞いておりません。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"公のところは品川区という意味なのかとも思っているのですけれども、その辺の説明を改めて伺いたいと思うのが１つです。当初３園だったのが４園、その辺について、どういうふうに現状を評価しているのかということを改めてお伺いします。","respondent":"吉田保育施設調整担当課長","answer":"公私連携幼保連携型認定こども園の運営を継続的かつ安定的に行うことができる能力を有するものであると認められる法人に対して公私連携幼保連携型認…既存の条例におさまるかどうかというところにつきましては、その辺を含めまして、また今後検討していきます。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"これからも詳しく検討していくということなのですけれども、大まかに今のところがどうなっているのかだけ最後に教えていただきたい。保育時間との関係で、報告がないから齟齬はないと思うのですけれども、その辺の関係を今のところで教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"平成３０年度に検討していく中で、認定こども園を進めていくにしても、環境整備等が一部必要になります。平成３０年にその辺を検討してまいります。 これは通常の保育園の中に就労要件を伴わない幼稚園みたいな形が各クラス５名です。法人格がないというところで、今の形態の施設だと、この３つがあるということです。","id":"exchange-028"},{"speaker":"南委員","kind":"意見","question":"それを煩雑という言い方をしたら語弊が生まれるかもしれないけれども、あまり種類をそろえる必要はないのではないかと個人的には思っているのです。それはわかるのですけれども、いろいろな種類があるということについての区の考え方はどうなのかを知りたいと思っていますとの意見を述べました。","respondent":"佐藤保育課長","answer":"それが１点あります。今、対外的にも説明が認定こども園であったり、わかりやすくさまざまな施設の整備というところで進めていきたいというところで考えておるところです。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さっきの質問の方と似てしまうのですけれども、そこを１つ、どういう位置づけなのでしょうかというところを教えていただきたい。その後というところでは、そこをどう支援するかというところがわかりにくいので、その点をお尋ねしたいです。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"保育園は０歳から預かってますのでそういう面を目的に設置しています。平成２７年に行われた法改正の経過措置が５年でありますので、来年度、本格的に幼保一体施設の今後について検討してまいりたいと考えております。 社会福祉法人への支援ということですけれども、実際に社会福祉法人化したときの土地とかの貸付の支援とか、考えていく予定です。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどお話があった譲渡の話になると経理課ですか、そういったことも含めると、今ちょっと保育教諭の話に関連してお伺いします。公私連携幼保連携型とした後に引き続き、１つの候補としてというのでしょうか、そういった体制を整えていくという大きな流れになるか尋ねました。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"前半のご質問ですけれども、まず幼保一体施設の今後のあり方につきましては、保育課が主体として検討してまいります。そういった体制で考えてまいります。 公私連携法人、今後の予定となる法人に対して、又は譲渡するものとするという定義があります。この条文をもとに、検討するなかで社会福祉法人化を進めていくことを来年度検討してまいります。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"社会福祉法人化するのに、今お話があった第３４条で貸し付けて、それで、そうなったから社会福祉法人化できるという考え方でいいか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"正確に言いますと、第３４条の最初のところで、この団体がそれに値するという形で、公私連携法人を指定しまして、そこと協定を結ぶ形になります。そこが協定を結んだ後、必要であれば施設等の整備のために土地等を貸し出すというような順番になっております。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"その協定を結ぶときは、まだＮＰＯ法人ですか。ＮＰＯ法人では今お話があった認定こども園をできないから、先に社会福祉法人をつくらなければいけないということなのだと思うのですけれども。","respondent":"吉田保育施設調整担当課長","answer":"申し訳ございません。ＮＰＯ法人から社会福祉法人をつくりまして、社会福祉法人を公私連携法人ということに指定するという形で、このような順番で考えております。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"ＮＰＯ法人が社会福祉法人化するときの支援をしていくということとなると、財産を持っていたり、いろいろな要件が必要なのですけれども、そういうことに関して区が積極的にというか、携わっていくという考え方でいいか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"委員のおっしゃられるとおりで、そのとおりです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"改めて今の関係ではっきりさせておきたいと思ったので再質問になりますが、今の状況はどうなっているのか、そこを説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"現在のぷりすくーるは区立ですので、区の資産です。","id":"exchange-035"},{"speaker":"南委員","kind":"意見","question":"そこに同じように貸し付けをしていくという、整理すると、こういう考え方でいいのかとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"順序としては、今のところはそのように考えております。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"質問をしていいですか。１回集まってから出願させるか、その辺は、ぜひ事故などがないように対応をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"出願関係は、休校になっても学校の教員は出勤しておりますので対応はできますので、個別に対応をすることになろうかと思います。なお、本日も、各校、出願等について何かその後困っているという連絡は、現時点では受けておりません。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"１番がメインで、２番と３番は１番から派生する項目だと思うのですけれども、その辺はこれを３つ並べてもいいのか尋ねました。","respondent":"高山子ども育成課長","answer":"委員ご指摘のとおり、基本的には相談に対応していくというのがこの事業の中核となってくる、これはもう間違いのないところです。産後の家事育児支援サービス、そうした周辺の支援事業についても拡充ということで事業方針に当たっては視野に入れた、そういったものです。","id":"exchange-038"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"例えば、「しながわパパママ応援アプリ」で、ネウボラについて宣伝はされているのでしょうか。例えば、これを１回、ネウボラ経由にしたらどうかと思うのですけれども、その辺の見解はいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"来年度の予定では、品川、荏原のほうも調整しながら区内全域に相談員が出向けるような場の確保に努めてまいりたいと思います。相談の中に直接的な拡充支援が必要ということであれば、その相談の対応の中身の中で、区の事業をご紹介するなどといった取り組みはしていますので。","id":"exchange-039"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"だから、人数的に足りているのかどうかというのは非常に心もとないのですが、それを増強する計画はあるのでしょうか。その点をお願いします。","respondent":"高山子ども育成課長","answer":"ご質問の２点目と３点目は関連いたしますので１つでお答えしますが、現在は５館で対応しています。それから、人材確保と人材育成が課題になってまいりますので、この点については並行して進めてまいりたいと考えております。","id":"exchange-040"},{"speaker":"こんの委員","kind":"確認","question":"考え方を１つ伺いたいのですが、産後の家事育児支援の利用の対象ですけれども、出産した方で生後６カ月になるまでの乳児を育児している方、基本的なところの確認ですが、生後６カ月までとしたのはどういう意味なのかというところをまずお願いします。","respondent":"高山子ども育成課長","answer":"産後の家事育児支援の利用助成のお尋ねの中での利用要件のお尋ねかと思います。やはり多くの方のつらい時期を等しく支援していきたいということから、ある程度対象を絞った上での支援という形で構築させていただいたものですので。","id":"exchange-041"},{"speaker":"こんの委員","kind":"確認","question":"生後６カ月以降はいわゆる離乳食が始まって、どうしたらいいのかというところを、ネウボラに相談をするというのでされていくのだと思うのです。１人に対してなのか、２人なので倍の利用ができるのかというところを確認したいのと、そのことについてお願いします。","respondent":"高山子ども育成課長","answer":"１点目の多胎児への対応ということにつきましては、現在、検討していますので。やはりこれもママがとりやすい産後の３カ月とか、直接的な家事育児支援が必要な時期というお話もお伺いするにつけ、今後の検討課題と考えております。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"課題として延長も必要ではないかと最初に課長がおっしゃったということは、課題として認識をされているのだろうというところが伺えました。そこはどうなのか、１人だけを見ているのではない、その点はいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"その上で、この期間については今後の検討をしていく中で適切な期間の設定について検討してまいりたいというふうに考えております。兄弟関係について、そういった兄弟支援については、今後も検討してまいりたいと考えております。","id":"exchange-043"},{"speaker":"のだて委員","kind":"確認","question":"あわせて、助成は１,０００円ですけれども、利用料としては幾らぐらいになるのかも伺えればと思います。やはり今、品川でも年少人口が増えている中で、相談体制が十分なのかというところを確認できればと思います。","respondent":"高山子ども育成課長","answer":"そして２点目の利用料の負担の考え方ですが、先ほど申しましたように、１時間当たりは１,０００円の助成です。例えば安い方ですと３,０００円ぐらいから、１,０００円を差し引いたものが自己負担となっているというふうにお考えいただければと思います。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、個人事業者の方が２１名いらっしゃるということで、その中で合う方を選ぶということでよろしいか確認させてほしいと求めました。１人の方にずっとしていくというところで、そういったところはどういった対応をされているのか、問題など発生していないのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"１点目の、説明が上手にできなくて済みませんでした。そういった意味で、現在、相談員が不足していて業務に支障が出ているというような状況まではいっていないというふうな認識で考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"相談員の方が非常勤になっていることで、今年度は同じ方がやるということですけれども、なかなか言いにくいとは思うのですけれども、相談員の方から常勤になりたいと、そういった声はないのか尋ねました。","respondent":"高山子ども育成課長","answer":"週４日の勤務ということで、特に勤務時間が短くて困るとか、収入面で不満があるというふうな直接のご相談は私どものほうには寄せられておりません。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり核家族ですから、２時間おきぐらいにお世話しなくてはいけない、本当に大変でした。そういう点で、さっき言ったように、実績がどの程度あるのかというところも教えてほしいと求めました。","respondent":"高山子ども育成課長","answer":"今後も注力してまいりますので、５名で足りるかと言われたら、今後も増員を図りたいという思いでいるというところは現在も考えているところです。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"だから、できるだけ実績も見ながら、早いうちにもう少し拡大できるようにしてほしいという思いで質問いたしました。ぜひその辺を受けとめた上で、対応もしていただきたいというふうなことが思いとしてありますので、この辺にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひそちらもお願いしたいのですが、２種類、その辺の説明をいただきたい。ここの切れ目というのでしょうか、その辺の情報の共有というのでしょうか、そのあたりをどう考えられているのかという２点をお願いします。","respondent":"高山子ども育成課長","answer":"それを来年度の必要な相談員として採用していきたいという趣旨のものですので、そのような違いがあるというふうにご認識いただければと思います。実際いろいろと検討を行う中、例えば支援が必要であったり、要支援者に対する情報共有は現在やっています。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56229,"voices":151}},{"id":"h30-20180122-5","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"総務委員会","time":"午後 １時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"住宅宿泊事業法の施行","agenda":"住宅宿泊事業法の施行","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひいろいろな意見を聞いていただきたいと思っていますが、この法についての品川区の考え方、受けとめ方を伺いたいと思います。より広く聞いていただきたいと思うので、その辺をもう少し詳しく説明を求めました。","respondent":"柏原企画調整課長","answer":"国のほうとしますと、民泊サービスが日本にも普及していることで、やはり多様化する宿泊ニーズといったことへの対応が必要だというところがあります。いずれにしましても、いろいろな方のご意見を伺いながら、条例、制度の構築といったところを進めていくです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区としては、これを受けとめて積極的に進めていくという考えなのかどうか、そこを伺いたい。だから、その点をしっかりやはり第一義的に掲げていただきたいと思っているのが１つです。","respondent":"柏原企画調整課長","answer":"今検討しているですので、そういう方向性で検討したい、規制はかけていくという形で検討するものです。オーナーさんの考え方等々がありますので、直接きちんとした判断がマンションの中でできるようにということでの情報提供を、今させていただいたです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"旅館業法など現在きちんと守られている部分を継続すべきで、今住んでいらっしゃる住民の方の安心・安全は守られないのではないか。きちんと中身が説明されて、区民の隅々にまでやはりこの中身が理解されないといけないと思っているのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"ただ、その部分においていかにその地域の方々のご意見を聞きながら、その実情がうまく反映できるかというところで検討しているというものです。そういった考え方も含めて、今、いろいろなところからご意見を伺いながら、実情に合った形で検討していきたいです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"これは、法が６月に施行されますよね。その辺をお伺いしたいのと、今後の進め方、スケジュール的なもの説明を求めました。","respondent":"柏原企画調整課長","answer":"その後の受付というのが３月から、法令上は３月１５日になっていますけれども、これからの調整になります。６月には法律が施行になりますので、そういった形でその施行に向けて準備を進めるということになります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"提案","question":"スケジュールのことなのですけれども、なぜ伺ったかというと、本当に３月から届出が始まるわけですよね。区の姿勢はどうなのだろうとはっきりしない提案であると私は思ったので、スケジュールも当然お伺いしたのですが、よりよいものをつくるのであればとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"は２点お伺いしますけれども、１点目が、今回のこの法律の制定によって、区の責務と業務というのがどのようなものになっていくのか。やはりその辺も区の条例制定にいい効果をもたらしてもらえるようなヒアリングをしてもらいたいと思いますが、その点について、２点お伺いいたします。","respondent":"柏原企画調整課長","answer":"その事業者の登録であったり、そういうことが仕事になります。事業者といいますか、関係したところからの意見を聞きたいとは思ってありますので、その手法については検討したいところです。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"意見は聞いて損することはないと思うので、ぜひ様々な窓口を使って聞いてほしいと求めました。やはり２４時間の何らかの対応がどうしても必要になってしまうのかなと思うのですけれども、まずその点をどのように考えているか説明を求めました。","respondent":"柏原企画調整課長","answer":"その時間帯であるとかをどういったものにするかというのは、今後の課題ということで内部で検討しています。それぞれの今の業務分担のところで対応しているということになりますので、窓口というか対応をしていくということになるです。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる法どおりの１８０日はオーケーにするとか、いわゆる家主がいるのといないので、しっかり区別をしてほしいと求めました。届出事業者の確認は受付の時にしっかりやっていただきたいのと、いわゆる事業者の公表についても台東区は今ルール化をしようとしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"最初に、これは言葉の整理みたいな感じなのですけれども、届出が必要となっていますが、これは届出制と理解していいのでしょうか。それがちゃんときちんと実施されない場合のペナルティになるのか、それとも取り消しとか何かそういうことがあるのか、その辺をまず１つ伺います。","respondent":"柏原企画調整課長","answer":"営業とか運営をしたということになるとどうなるかといいますと、届出がないということになりますと、旅館業法のほうで罰則規定にかかってきます。そういったつくりになるので、旅館業法のほうの規制というところにつながるというつくりになっているものです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"その旅館業法をちゃんと調べていなくて申し訳ないのですけれども、そうしますとこの届出に必要な内容がきちんと実施されなかった場合は、旅館業法のほうの規制で、例えば民泊が続けられなくなるとか、そういうふうに理解してよいということか尋ねました。","respondent":"柏原企画調整課長","answer":"おっしゃっていただいたとおりでございまして、旅館業法の規制の範囲、罰則規定もありますけれども、そういった事業ができなくなるというのは、そちらの法規制のほうで規制がかかるというものです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう一点、質問として伺いたいのは、今ここで出されているレベルの民泊の事業をこういう条例をつくって始めます。ちょっと質問だか意見だかわからないかもしれないけれどもそのように思うのですが、もしそれに対して見解があれば、お願いしたいと思います。","respondent":"柏原企画調整課長","answer":"どういった考え、もっと細かいいろいろなお話を聞いていますけれども、そういったものを参考にしながらです。区の考え方をお示しして、一定程度の案を考えなら、ご審議いただくべく検討していくものだと思ってあります。","id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"そうなると、これは条例のほうが優先されると考えてよろしいのでしょうか。法令上は３月１５日から受付開始になっておりますけれども、先ほどスケジュールの話もありましたけれども、そのスケジュールの確認をさせてください。","respondent":"柏原企画調整課長","answer":"法令上の動きのスケジュール感ということをお示ししました。どのような対応といいますか、条例をつくるのも含めて対応がよろしいのかというところも含めて、併せて検討したいというものです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"やはり区としての条例を決めるのであれば、それにのっとった受付がその後開始されるべきではないかと思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから品川区のほうに要望したいのは、例えば苦情とか何かも品川区に来てしまうわけですよね。意見だけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"そうでなければ、簡易宿所のほうが結局日数とか地域の縛りがなくなるわけですから、皆様そちらのほうを選んでくる。要するに法的にいわゆる旅館業法上の民泊がこれから増えるという見込みなのか、その辺について何か情報があれば教えていただきたいのが１点です。","respondent":"柏原企画調整課長","answer":"旅館業法関係は保健所が受付をしておりますので、細かい数字のところはちょっと私も今手元にはないです。そういった意味では、どちらを選ぶかというような話で、ちょっとその辺は様子を見ながらということにはなってくると思ってあります。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"確認","question":"これは本当に間違いないのかどうか確認で、いわゆる担当課からこれはもう本当に出されているのかということが１つ。例えばそれについて、自分のマンションの何々号室で、そういった内容も通知で出ているのかどうか説明を求めました。","respondent":"柏原企画調整課長","answer":"出したのは直近だと聞いておりまして、１月に入って、まだ先週とかそういう時期だと聞いています。国土交通省で出している基準であるとか、そのガイドライン的なものを添付しながら、周知、お知らせしていると聞いています。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"１００万円の罰金を無視するかどうかわかりませんけれども、誰に連絡すればいいのか、警察に連絡すればいいのか。そういったところについてもぜひ検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それとあと、大田区も地元経済団体といろいろ連携して様々な取組みをやっていると思うのです。今現段階でどのように、これからこの地域活性化のために情報提供も含めてやっていくのかどうか、お知らせほしいと求めました。","respondent":"柏原企画調整課長","answer":"大きな商店街のあるところであったりとか、あと大井町駅近辺、五反田駅近辺といったところは商業地域というところになってあります。我々も一緒に企業部門だったり観光部門といったところと連携しながら、考え方が出せればと考えていますので、併せて検討していくというものです。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３点お伺いしますが、１点目、地域について区の考え方がある程度あったら教えていただきたいのが１点です。どう解決していいのかが真っ先に浮かんでくるわけですけれども、問題があった時にどこがどう問題点を改善していくのかというのが２点目の質問です。","respondent":"柏原企画調整課長","answer":"事前の説明であったりという部分につきましては、その手法、それにつきましてはこの制度を考える中で併せて検討していきたいというものです。そのための情報共有で、統一化したシステムができ上がるということで聞いています。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明の問題、ここのところは本当に丁寧にやっていただきたいし、事業者の責務というのも明らかにすべきであると思っています。デメリットばかりであると思うので、私たちはやはりこの家主不在型というのは認めないでいただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-02","title":"デジタルサイネージ（電子掲示板）の設置について","agenda":"デジタルサイネージ（電子掲示板）の設置について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"音声的な説明というのは考えていないのですか。そこが削られるというようなことはないのかどうか、説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"３点ございまして、多言語、音声のほうなのですけれども、実際今のところは音声のフォローについては考えておりません。それから、窓口案内そのものの態勢につきましては、これが入ったことで何か変わるということでもございませんので、今まで同様という形です。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"正面玄関のところはすごく大きくて立派なものだと思ったのですが、予算のところを調べてこなかったので、予算がどのくらいかかっているのか説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"今年度の予算ですが、およそ３,０００万円です。実際ランニングコストも同様ぐらいの規模感で考えておるところです。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ちょっとだけお伺いしたいのですけれども、あそこが一つの受信機になっていると思うのですけれども、その辺を確認したい。より区民の方の使い勝手がよくなってくるのかなと思うので、その点もぜひ検討してほしいと求めましたが、いかがか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"３点ございまして、まずちょっと訂正ですが、先ほど経費の件ですけれども、今年度ランニングコスト込みで３,０００万円です。それから、実際に所管への行き方であるとか、スマホとの連携につきましては、ご意見頂戴しまして、検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問","question":"地域センターによって２０町会とか自治体があるようなところもあると思うのですけれども、募った町会の情報を載せるのかどうか。どのようにやり取りをしていくのかということをお聞きしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"今予定では、来年度、これから予算をご審議いただいきますけれども、来年度で全地域センターに配備完了という形を考えております。情報なのですけれども、そういうものを地域センターのほうで読み込ませてデータ化をして、それで載せるというような運用が現実的になると思います。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"１月中は試行運用で、２月１日から運用開始ということで、単純な質問ですみません。だから、今みたいなご意見が取り入れられて、多少改良されて本格運用になるのか、その辺の試行と本格運用の差や違いを説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"一番大きなところは、これから各課の研修を行いまして情報をアップする、その態勢が整って２月というような形を考えています。今は暫定的に広報課のほうで区のお知らせという形で載せていますが、今後は各課が情報発信をしていくという形で、本格運用という形で考えております。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"あの辺も、こういう情報提供を進めるというこの機会に、もう一度わかりやすいような検討をしてほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"室内というのやはり営業時間外はほとんど見られないということですから、その辺に一つ盲点があるので、ぜひ検討していただきたい。目に飛び込んでくるというものなので、すごくいいものができたのだなと感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"オープンデータ利活用による地域課題を考えるワークショップの成果発表について","agenda":"オープンデータ利活用による地域課題を考えるワークショップの成果発表について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"あまりよくこの中身が理解できないというか、現在７０項目のオープンデータというのをインターネットで調べたら、いろいろなデータが入っていますね。どのような方々がここに参加をして、どのような過程でこの成果物を生んでいるのか、ちょっと流れを教えていただけたらと思います。","respondent":"仁平情報推進課長","answer":"こちらのほうは最初から区のほうでこのテーマについて考えてみませんかというような進め方ではなくて、そういうことを皆様が検討したものです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"今後やはりこういうワークショップを続けていきながら、いろいろな分野の拡大をしていくのかどうか、その辺を伺いたいと思います。","respondent":"仁平情報推進課長","answer":"これは広くいろいろな方に見て使っていただいて、またご意見等を寄せられれば、次への改善につながっていくかなとは考えております。引き続き今年の課題等に取り組むと同時に、仕方を続けて、区民の皆様と一緒に事業を進めていければと考えております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひまた見せていただいて、区民の皆様からこういうものがあったらいいなというようなご意見をどんどん具体化していっていただけたらと思います。ここに協働と書いてありますけれども、プロの方からどのような援助を得ているのか、ちょっと説明を求めました。","respondent":"仁平情報推進課長","answer":"こういう取組みを自主的に行っている団体でありまして、会社とか企業とか、そういう形の団体ではないということです。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"企業ではないということですが、ＮＰＯとかどういう団体なのでしょうか。そこだけ最後お聞きします。","respondent":"仁平情報推進課長","answer":"組織的にはＮＰＯではないです。いろいろな課題を考えるというワークショップを開催していて、そういう取組みを行っている自主的な団体の集まりという形になっております。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問","question":"権利関係というのはどこがどのように持っていくのかということがどうしても生じてしまうのと、それによっても大きく変わってくると思うのです。その点、区として今どのように考えているのか説明を求めました。","respondent":"仁平情報推進課長","answer":"やはり商業ベースに乗せたいということで、商業ベースに乗るのであれば、それなりの権利関係とかをきちんとしていくことが必要になります。公表等に区のほうは支援はしていきますけれども、制作者のアプリという形になりますので、非公式なアプリという形です。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"意見","question":"何らかの形でそういう発信の部分に関してもその参加者の方たちと話し合いながら、連携してできることを発信してほしいと求めましたので、その点との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"公表するということは、その辺の発信の仕方もあくまでこのワークショップの人たちが何か発信するのか、それとも区が発信するのか。今のご意見の続きみたいな質問なのですけれども、今後誰でも使えるようにするというところに、区はどのように絡むのか、お考えを説明を求めました。","respondent":"仁平情報推進課長","answer":"誰でも使えるという点におきましては、アプリそのものは一般公開していきますので、誰でもが使えるという形の公表の仕方になります。計画にもなっておりますし、アプリが公開されているというところの周知、ＰＲの支援というのも区のほうで行っていきたいと考えております。","id":"exchange-034"}]},{"id":"topic-04","title":"八潮地域センター複合施設非構造部材耐震化その他工事請負契約","agenda":"八潮地域センター複合施設非構造部材耐震化その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ガラスフィルムも全ての窓ガラスに張られるのかどうか、そこを教えてください。下の関連工事のところのその他電気設備工事、その他機械設備工事というのは、具体的にどのようなものなのか説明を求めました。","respondent":"立川経理課長","answer":"ガラスフィルムにつきましては、全ての窓について実施するものです。その他電気、機械設備工事ですが、北棟のエレベーターの改修を実施するという内容です。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"工期が３月３０日までになっていますけれども、工事する場所でやはり閉鎖したり使えなくなったりする部分があると思うのですが、その辺がどのような手順で行われるのか、周知がどうなっているのか説明を求めました。","respondent":"立川経理課長","answer":"予約は３月３１日までできないです。基本的には居抜きの工事ですが、現状、レク室と音楽室とスポーツ室については利用できないです。","id":"exchange-036"}]},{"id":"topic-05","title":"不動産の寄附受領について","agenda":"不動産の寄附受領について","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"本来町会に寄附してくれると遺言で書くということだったのですけれども、急に入院して亡くなってしまったものですから、実際心配していたのです。町会としては鈴木さんの面倒を見ていたので、その後の計画なのですけれども、これは地元にやはりいろいろな説明みたいなものをされるのか尋ねました。","respondent":"柏原企画調整課長","answer":"活用を検討する中で、区民の方も一緒に説明といいますか、お話し合いをしていきたいと思います。現段階で何かというところで具体的に何か決めているところではありませんので、今後検討しながらということになるかと思います。","id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"地元の方たちの意見を十二分に聞いていただきたいと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"場所もいいし、相当な金額になるのかなと思ったのですが、大体どれぐらいの価値があるものなのでしょうか。参考に教えていただければありがたいです。","respondent":"立川経理課長","answer":"実勢価格は抜きにしまして、路線価等から勘案いたしますと最低２億円以上ということです。","id":"exchange-039"}]},{"id":"topic-06","title":"品川区原動機付自転車ご当地ナンバープレートデザインの決定について","agenda":"品川区原動機付自転車ご当地ナンバープレートデザインの決定について","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"この優秀賞２作品と特別賞というのは、例えば区広報紙などで公表されるということなのでしょうか。そのコピーライトごと、このナンバープレートの権利みたいなものは品川区に帰属するということなのか尋ねました。","respondent":"伊東税務課長","answer":"優秀賞については現時点では、その受賞者の方に関しては、一応副賞をいずれどういう形かは別としてお渡しするという形です。このまま使えるという形になっていまして、著作権関係は全て区のほうにいただくという形で、本人との了解は得ているところです。","id":"exchange-040"},{"speaker":"吉田委員","kind":"意見","question":"大々的にではないにしても、せっかく応募してくださって特別賞ということであったら、何かちょっと配慮がいただけたらいいなと思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":35769,"voices":109}},{"id":"h30-20180123-14","meetingId":"h30-cm01","date":"2018年1月23日","dateIso":"2018-01-23","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ５時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"区有施設、公有地等活用に関すること","agenda":"区有施設、公有地等活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それから、やはりここに今つくっていくというチャンスだと思っているのですが、この方向性とか活用内容（案）というところ。ぜひ、そういった中身を活用内容（案）にも示していただきたいなというふうにも思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"ご利用可能な施設ということで検討しているものですので、さまざまな方ということで、多様な面から検討したいというふうに思ってあります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"どのように考えて、そしてどのようにして、この活用内容（案）というのが決められているのでしょうか。伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それをうまくトータルで考えたときに、この土地にはどういった施設が一番よろしいのかと比較検討する中で決めていくということであると思います。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう中で見ても、このチャンスを逃したら荏原東の地域はどうするのだろうというほどの状況ではないかなというふうに思うのです。ぜひ入れていただきたいですし、入れるべきだし、その辺のお考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"資料にお示しをしているとおりというところではありますけれども、先ほど来申し上げているとおり、さまざまなニーズ、それから地域の実状等々ありますので、そういったところを考えながら、施設構成は考えていきたいというものです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今の段階では、そういうご答弁になると思うのですけれども、本当にここに求められている。地域の声ということもありましたので、ぜひその声を受けとめていただいて、行政需要として区が主導で進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討に入れるべきだと思いますし、増やすという方針は区も持っているわけですから、この検討に入っているかどうか伺いたいと思います。５,０００平米のことに関しては、やはり５,０００平米以上の取得を求めていただきたいということで、具体的に伝えているのか。","respondent":"柏原企画調整課長","answer":"この施設というのも考えながら、さまざまな施設構成を考えているですので、トータルの考えの中で検討しています。実際公園のほうを広げる際の東京都の防災上の計画の考え方とか、今の段階に至っては厳しいかなという状況はあります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"「近隣への圧迫感を考慮し３～４階建て施設を想定」とありますが、調べますと、建築上の制限は実際どうなっているのか伺いたいと思います。本来であれば、大体何階建てぐらいまでが可能なのかを説明を求めました。","respondent":"柏原企画調整課長","answer":"この施設構成を考える際に、当然のことながら、ボリュームチェックということで、どのぐらいの施設が可能なのかということで検討はしています。マックス値ということではそういうことになります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"最大限行政需要に応えられるような施設規模に、さらに拡大できるように工夫してほしいと求めましたけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"例えば５,０００平米とかとれるにしても、その上に建物を建てたときに、なかなかボリュームをとることが難しいという。ですので、そういった近隣の方々のお声というのも十分に聞きながら、施設構成は固めていきたいというふうに思ってあります。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"状況はわかりました。建物をどこの位置に建てるかということも含めて、最大限工夫をしていただいて、さまざまな行政需要に応えられる施設にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"１つ、平成３０年度がどうなるかという、不確定の要素をこれから国とどういうふうにつめていくかというのを１つお聞きしておきたいと思います。延焼遮断とかというお話もあるので、そういったところの観点というのは、何か考えられることがあるのかどうかというところをお聞きしておきたい。","respondent":"柏原企画調整課長","answer":"５階建てが建ちますというようなお話はしておりませんので、この土地を有効に活用する施設構成ということで、考えたいと思ってあります。建物が必要なのは間違いありませんので、東京都ともこれは話をしながら、考えていきたいというふうに思っています。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":10541,"voices":26}},{"id":"h30-20180125-18","meetingId":"h30-cm01","date":"2018年1月25日","dateIso":"2018-01-25","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"建設４団体からお話があるように、やはり品川区内の建設労働者や建設従事者というのですか、このかかわりとしては何かあるのかどうなのか。品川区のこの工事に関して、品川区がここまで気運醸成している中で、何か入っていける要素があるのかどうなのかも含めてお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、しかるべき手続を踏みまして、東京都といたしましては、受注者、建築工事等の会社をもう決めているところです。その辺、区の方がどうかかわるかというのは、区といたしまして、そこまで踏み込むことはできないという状況です。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"確認することもできないので、せっかく意見書や要望を出したのだけれども、それが実現しているのかどうかもわからない。なかなか腑に落ちない点も出てくるので、できる限りそういうのを見ていくような仕組みを今後つくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"検討しているのはいいのですけれども、これはいつごろ決まるのか。終わった後の話というのはいつごろまでに、結論が出るというか、どう考えておけばいいのでしょうとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"現在、東京都のほうでも後利用の考え方が出されておりまして、それがいつからどういう形でという具体的な表記はまだしていないところです。区といたしましても、多目的利用ということは同じ思いですので、そうしたことは働きかけ続けていく所存です。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3351,"voices":15}},{"id":"h30-20180126-10","meetingId":"h30-cm01","date":"2018年1月26日","dateIso":"2018-01-26","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"お手元に資料を配付しておりますので、ご確認ください。以上の部分について、結論が出ましたら、今回の平成３０年予算特別委員会からタブレット端末を用いた資料提示を行っていきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"２月の委員会の終了後に、各委員会でどういう内容を議会報告会で提案説明するかというご議論を一定程度行っていただければなと。２月２６日、２７日でしたか、お諮りさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"提案","question":"２７日の委員会報告なども出てくるでしょうから、２月２０日ぐらいまでに、こういう話を報告としてやったらどうかという案を事務局に出していただく。２７日でも当日の報告もあるわけですから、２７日には決定をしていただいて、それは提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"でも、２６日からの厚生委員会の資料というのは、２月２２日ぐらいでないと来ないですよね。第１回定例会というのは結構いろいろなものが出てくるのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"２６日、２７日を否定するわけではないので、そこでやるので、資料は出てくるわけで、その中で意見を言えるわけですから。１回そこで２０日ぐらいまでに出してもらったほうがいいのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":8869,"voices":44}},{"id":"h30-20180220-10","meetingId":"h30-cm02","date":"2018年2月20日","dateIso":"2018-02-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"平成３０年第１回定例会","agenda":"平成３０年第１回定例会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"議案説明会のときもちょっと質問したのですけれども、国保の条例というのはいつ頃出るかというのは、今日報告がないと思うのですけれども、条例がいつ頃かというのはまだわからないという状況か尋ねました。","respondent":"久保田区議会事務局長","answer":"私どものところにはまだそういう話が来ていませんので、ちょっとわかりませんが、もしそういう話があれば、また議会運営委員会等のほうで上程の手続等のために行いたいと思ってあります。","id":"exchange-001"}]},{"id":"topic-02","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"タブレット端末等の使用基準に定める会議への持ち込みを認める情報端末に、資料記載のとおり「携帯電話」を追加しておりますので、ご確認ください。ですから、こういう基準をもとにして、携帯電話の導入を確認したです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"地元の要望をというお話で議長会の中で発言をされたということなのですが、どのような発言でしょうか。競馬組合とも話したり、そういうことを考えると、どのような方向で地元の要望をおっしゃったのかというのだけ確認をさせていただきたい。","respondent":"松澤議長","answer":"軽いものは修理しましたけれども、今このように競馬事業が好調なうちに、ある程度直す計画を持つべきではないかということでお話をしました。本会議で一般質問でやりましたけれども、一般質問で出るのは議長会で初めてということで、いろいろと協議をしながらも行ったところです。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話はぜひ品川区議会の中でも話をしてほしいと求めました。その辺のところはぜひ、もしそういう発言をされたのであれば、議会としてもそういう議論をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"意見","question":"何らかの発信をしていく必要があるのではないかと思っているのですけれども、その点について検討をする時間があってほしいと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"話も出ました。ちょっとあれですが、議長のお考えもまず先はそちらだろうと、厚生委員会は後づけだという話をしたのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"南委員がどういういきさつで厚生委員会でそういう報告があるとお聞きになったのかは、どういう報告の仕方をするのですかという話は素直に聞きました。だから、今の段階では私の委員長の立場としては、それに対する行政の感覚の予想みたいなものを入れ込むのはやめてという話はしたということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"しかし一定程度の病院ですから、しかも大病院で総合病院なので、区民の皆さんのいろいろな思いというのはあると思うのです。そこのところで、ここの品川区議会として区民の要望をどう受けとめるかというところは表明していく必要があるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"区が把握している事実をちゃんと伝えて、だからどうなるという予想は、先ほども言ったようにしないと。それは厚生委員会の委員長として、その他のその他で受けるそんな話ではないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"私は、やはり違うのではないかと思うし、もう売ってしまったわけですから東芝に言ってもしようがないということはもう大前提ですよね。区民の間でそういう問題が非常に大きくなってきているというところは受けとめる必要があるのではないかと思いますので、その点について述べたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"何科減らしてどういう科を増やすなど私は知らないですが、それは逆に言えば議会だってホームページのとおりですと言うことしかないのです。それは別だけれども、そういうことを言うなら、私は委員長としてそれは厚生委員会のその他のその他の話ではないと思いますよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":15072,"voices":54}},{"id":"h30-20180223-3","meetingId":"h30-c-budget","date":"2018年2月23日","dateIso":"2018-02-23","committee":"予算特別委員会","time":"午前１１時１６分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち副委員長","kind":"意見","question":"ただいまご推挙いただきました公明党のたけうち忍です。委員長をお支えしまして、実りある委員会にしてまいりたいと思いますので、どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/757192?Template=document&Id=1070#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1904,"voices":17}},{"id":"h30-20180226-6","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"区民委員会","time":"午前１０時００分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"第１４号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第１４号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そこにも関わりますけれども、５号認定になりにくいという事情や実態というのはどういうことなのか。その点についても補足でご説明ほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"それから、先ほど説明の本来想定し得ない大震災でありますとか、品川区としましては速やかにそのときに制度を構築するということを考えています。考えだということは、ＰＲ、説明はしています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"緊急資金のことについて、１つ伺いたいのです。いわゆる不況と言うよりも恐慌と言ったほうがいいのでしょうか、となってくると、どういうことがその時々に応じて対応できる範囲なのか。","respondent":"山崎商業・ものづくり課長","answer":"１ヶ月半かかるような期間的なものも勘案しまして、速やかに銀行は融資を実行しなさいということができるようになっています。いろいろな企業活動にとって致命的な状態になれば、それに応じた資金需要に応える制度を持って、最適に適用してまいりたいと考えています。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"必要な事業で進めてほしいという立場なのですけれども、きちんとした貸付がされるべきだと思うので、少し確認させてください。もしそうだとしたら、区の中のどういう立場の方が審査をするのかということを伺いたいので、そこを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"保証協会が返済できない分を銀行に、代位弁済と言いますが、お支払いをする形になります。そうした税が未納ですと、それが１つの審査要件になりますので、貸出しができませんということをチェックさせていただいている状況にあります。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"次に第５条のあつ旋手続なのですけれども「区長は、適当と認める者については、速やかに取扱金融機関の融資について紹介するものとする。」とありますが、紹介された後に、金融機関は金融機関として通常どおり審査があると考えていいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"企業は、その紹介状を持って銀行に行かれて、銀行内部の必要なチェックを受けるということになります。確認をしていただくような流れがあって、それが全て完了して、融資が実行されるです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"これは、第６条の融資については、金融機関は区長との協議によって審査をせずに融資を実行するという意味なのでしょうか。区長が必要だと認めた事業について、区内在住で何年ぐらい事業を行っているかなどの審査は、誰が行うのかということを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"審査につきましては、現行で通常に当たらせていただいている経営相談員の審査ということで考えております。こうした融資あつ旋条例の特例の流れの審査についても、現状と同様の状況になっているです。","id":"exchange-005"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"あえて、この２,０００万円の上限という考え方は、どういうところから来ているのかというのを教えていただきたいのが１つ。その辺の使われ方として、設備と運転資金ということで、この資金の借り入れの目的としてはどんな傾向にあるのか教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"２０人以下の小規模の、区としましては、セーフティーネットの考え方で上限１,２５０万円の設定がこの時代に合っているのかという議論がなされて。全てが１,２５０万円オーバーというわけではなくて、そこのメリットは、一部その辺には効果的に出てくるかと考えています。","id":"exchange-006"},{"speaker":"塚本副委員長","kind":"質問","question":"資金がたくさん必要で、中には２,０００万円では足りないという話、中にはあったりするのではないかと思うのです。そういうときに、この融資あっ旋の様々なメニューの中で、いろいろな対応がとれるようなところがあるのかどうか、最後にお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"同時に組み合わせて使っていただくようなこともやらせていただいております。ご質問の趣旨も含めましてしっかり対応させていただいているところではありますが、さらに今回充実させてまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"細かい平仮名のことなのですけれども、正式には「あっ旋」なのですか、「あつ旋」なのですか。パンフレットでは「つ」が小さくて、今まで「あっ旋」と言っていたのですが、正式には「あつ旋」なのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"「つ」の大きい、小さいということでは、条例で表記している「あつ旋」です。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"「あつ旋」と訂正しなければだめですか。訂正しなくて大丈夫か尋ねました。","respondent":"堀越地域振興部長","answer":"公式文書としての残し方だとご理解いただいて、私も確認してみますけれども、検索システムも「あっ旋」で大丈夫ではないかと思います。公式文書としての文字の残し方の大きさの違いだけだとご理解いただければと思いますので、よろしくお願いいたします。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"事業計画を見て、きちんと区がしっかりとしたアドバイスをしていただきたいなと思います。それで賛成です、必要な事業だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"品川区文化芸術振興協議会準備会","agenda":"品川区文化芸術振興協議会準備会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"懇話会の中でそういう要望が出されて、１点伺いたいのは、事前アンケートに取り組んでいるということです。その設問や内容など、この中身についてご説明ほしいと求めました。","respondent":"鈴木文化観光課長","answer":"基本的には、ご説明をした協議会の考え方や概要、進め方についての基本的な質問。今後の区の文化芸術関係に関するそれぞれの自由な意見という大きく３点でアンケートをお願いしたところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望を伺ったり、活動をお互いに紹介したり、そういう取組みに発展できないかなと思ったのです。まだ準備会の段階ではありますが、今後の方向性についてお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"特に文化センターなどを使いまして、日頃から活動していただいているサークルなど、そういう区民の団体の方がいらっしゃることは認識しております。先ほど申し上げた利用者団体の協議会など様々なチャンネルでご意見をいただくという形で進めたいと考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"文化という中において、そういうところにも関わっていただければと、私は個人的に思っているのです。今後の展開として、その辺はどのように考えているのか教えていただけますか。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおり、区としてはそういうジャンルも当然、文化芸術の１つだと考えております。その他の区内の団体でもそういう分野で参加いただけるというお話があれば、今後また加入をお願いしたいと考えております。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"エリアもそうですし、ジャンルもそうですし、そこではすごく長けていても、全区的な盛り上げのノウハウはおそらく別物だと思うのです。おそらく事務局機能的なことになると思うのですが、行政の関わり、立ち位置を説明を求めました。","respondent":"鈴木文化観光課長","answer":"区の大きな役割としては、各団体の個々の活動なり協議会全体の活動の支援と、その活動のための環境整備。この辺が大きな行政の役割になるかと考えております。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"おそらくここの構成団体以外の地域のニーズや要望を拾い上げるのは、各団体というよりも行政がやるべきことかなと、議会も含めて行政かなと思います。少し要望的になりますが、一番下の協議会主催のイベントというのは相当なインパクトを残せる可能性を持っているのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"一般質問のときに教育委員会が答弁しました坂本龍馬の像について、たしか出たと思うのですが、改めてそこをお伺いしたいのです。その辺についてお伺いできれば教えていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"来年度に向けての部課長のお気持ちをお伺いしたいと思うのですけれども、委員長、よろしいでしょうか。ぜひお伺いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17021,"voices":56}},{"id":"h30-20180226-7","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"厚生委員会","time":"午前１０時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件整理しています。","topics":[{"id":"topic-01","title":"第１９号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"第１９号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"授業料相当が最大１４０万円の貸し付けとなっているのですが、２年間なのか、そこのところを教えてほしいと求めました。医療型の療養病床というのは、この介護医療院のほうに変わっていくということはないのか、その辺も説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"今のところ、こちらが介護療養病床をやっておりますので、仮に転換があり得るとすればこちらが区内では唯一対象になると考えております。例えば新しいタイプの老人保健施設になるとか、いろいろな情報も出ていますけれども、可能性としてはあり得るというふうに考えております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年以上勤務して返済全額免除、それから２年以上従事したのちに退職したという方はどれぐらいいるのか、教えてほしいと求めました。今回地域密着型特定施設ということで、有料老人ホームで２９ベッド以下ということになると思うのですけれども、その点についても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"申しわけありません、医療施設では５カ所、ベッド数にして７４０床が区内にはあるという数字です。免除の対象施設に含まれております。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中でやはり職員の問題が相当絡んできて、上大崎はもう大分いろいろな方、開設前に交渉して、ここからも何人か入ったというお話も先日伺いました。直接薦められるわけではないけれども、奨学金と別にしても、将来の就学先ということで区内を薦められるように努力していただくよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"若林委員","kind":"質問・要望","question":"２の(2)でいわゆる障害者の総合支援法ですか、ここについては条項がずれるだけということで、それは承知をいたしました。３点目に、講師はどういう方が教えていらっしゃるのかとか、今どういうふうになっているのかということをお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"２年か３年かというところは申し上げられないのですけれども、障害者施設に就職して免除になったという方の人数は今現在、累計で１４名です。申しわけございません。","id":"exchange-004"},{"speaker":"若林委員","kind":"確認","question":"障害のある方の施設への勤務ということで、免除は１４名ということで確認をしました。今後２年以上３年以下の方の数字もしっかり押さえていただいて、ご答弁できるようにしておいていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問","question":"この貸し付け６５０名のうち、さまざまな理由があると思うのですけれども、どのように把握をしているのでしょうか。説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"実際、なかなか情報を全て把握するというのは大変困難でございまして、一身上の都合で退職されて返還するという方もいらっしゃいます。それぞれさまざまですが、奨学金を１つのモチベーションとして入っていただき、学校と力を合わせて持っていければと考えているところです。","id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"すみません。その辺の人数がわかれば教えていただきたいのと、これからさらに高齢化が進んでいく中で必要なのかなと思うのですが、その辺いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"実際に、２９６名のそれ以外の人については２年以内にやめてしまった方と全く就職しなかった方、これが実際にあると思います。介護の職にはついたのだけれども、区内の施設には入らず、区内に就職しなかったという方も若干名いるということは聞いてあります。","id":"exchange-007"}]},{"id":"topic-02","title":"第２０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺のところをどのように考えたらいいのか、そして２２％から２３％にということが何で決まるのかということをまず教えてほしいと求めました。各会派別に理事者のほうからいろいろと、総合事業でなぜ事業費の伸びを抑えることができたのかについてもお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"２３％になるといったことを踏まえて品川区としましては必要量を見込んで今回の保険料に反映させるという、そういう流れがあります。まず始まったときの考え方としまして、いわゆる介護であるとか、そういった全体的な制度の流れで結果的に抑えられたという発表になったです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その２号のパーセンテージが幾らぐらいになるのかというのがあるものなのか、その辺の考え方をちょっと教えてほしいと求めました。先日ほかの区のところにお話を伺ってきたのですけれども、介護報酬まで戻してほしいということを改めて要望しておきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それから地域支援事業の割合につきましては、開始時の、現行とほぼ同じ率での推移というふうに考えております。実施のときは東京都や国などに照会をかけたりして、この辺はニーズ、必要に応じていろいろ検討はしていく必要があろうとは考えているところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、そういう中で基金の取り崩しについて伺いたいのですが、基金の取り崩しは８億２,５９０万円だという答弁がありました。第七期に８億２,５９０万円を取り崩すと、第七期の最後には幾らになると想定されるのかということについてもお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"実際に先ほどの１０％、それからサービス料の見込みとしましては、具体的に幾ら減らしたかという数字を今ここで正確に申し上げることはできません。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この第五期、第七期もそうなるのではないかというような思いがするのですが、その辺のところはどう考えられているのかということが１点。それと、一番初めの骨子案のときには、それが５,６００円となった理由はどういうことなのかということについても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"平成３０年度予算を編成する際にそういう数値をベースにして給付額を見込んで、予算案として計上させていただいているという意味でもあります。第七期につきましても、今までいろいろ不特定であったり、まだまだ総合事業等のことも含めて見込みづらい部分もあるのですけれども。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１億５,０００万円もですから。平成２８年度の決算で１８億４,０００万円ですから、第六期のときには１１億５,０００万円基金を取り崩すというふうなことができたわけですから。","respondent":"寺嶋高齢者福祉課長","answer":"そのあたりは見込んで、今一番新しい情報をもとに見込んだところがこういった数字になっているということで、ぜひご理解いただきたいと考えています。わからないので、想定外に備えて基金を用意しておきたいというのが今の考え方だという内容です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのような感じのものだというようなことなのか、ちょっと改めて確認させてください。ずっと私は求め続けているのですけれども、区民が参加しやすいようにということで、１０回説明会を行っているのです。","respondent":"寺嶋高齢者福祉課長","answer":"定員が多くて２回目の抽選で申し込んだが継続できなかったのがちょっと残念だったなど、こういう内容の意見も含まれての６件です。それから説明会等々について、あくまでも周知をするというところが主目的なので、そのやり方は自治体ごとにそれぞれあると思います。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこのパブリックコメントが６件というのは、決して多い数字ではないと思うのです。私はそういう意見も吸い上げるような、改めて説明会は今後ぜひ持っていただきたいということで申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほどの２割、３割の自己負担のところは決算を見ないと、総合事業のところはもうわかるところなのではないかなと思うのです。総合事業を進めることで給付費を抑えるというのが国の目的でもあったと思うので、そこはわからないのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"利用者目線に立ったサービスを構築していった結果、過度なサービスが抑えられて必要なサービスに特化したということでの総合事業の、いわゆる給付費の抑止が働いたという趣旨の資料であったと認識しています。","id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ではそういう趣旨であれば、どれだけ抑えられたかというのはわかるということなのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"利用者数であるとか、そういったものについてはあれですが、今幾ら金額が変わったかという、総合事業を実施したときとしないときとの比較、そこまでの数字というのは、申しわけありませんが、持ち合わせておりません。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"(2)の所得指標の見直しの部分は、これは今回東日本大震災等に関連して、この租税特別措置法に規定される内容によってということで保険料が算定をされるということで、品川区民にとっての影響はどのように予想、押さえておられるかということをお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"被保険者数が８万２,０００名を超える中で、そういった譲渡所得があり特別控除対象になろう方が５３名という数字が直近では拾えたところで、これぐらいの人数の方が実際に対象者として出るという形です。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"去年１１月に示された骨子案、決定の経緯というのは説明をしたという認識でいらっしゃるのかということを１つお聞きしたいと思います。あのようなところとこの保険料決定についての関係、関連性というのは何かあるのかないのかということも確認をしておきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"今もずっとやってきたところではありますが、ご指摘のとおりそこが１つのご説明のポイントだと認識しています。それから地域の方も入っていらっしゃいますので、同じ内容のことをその後すぐにご説明をさせていただいたという、こういう関連性があります。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もし聞き漏らしていたら申しわけありません。他区の状況とか、他市町村、その辺の状況をちょっと確認だけさせてください。","respondent":"寺嶋高齢者福祉課長","answer":"ちなみに第六期も安いほうから３番目だったのですが、結果的に今、最新情報では３番目におさまっているです。それから軒並み６,０００円を超える自治体がかなり出てきているという情報も聞いております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"介護報酬を引き下げたまま、また基金の取り崩しについては、もっと取り崩して保険料をこれよりも引き下げることができると思います。本当に高齢者の皆さんも大変な中でやっていて、保険料の値上げに対してはこれ以上大変な実態というようなところがあると思いますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"第２２号議案 品川区指定地域密着型介護予防サービスの事業の人員、設備および運営ならびに指定地域密着型介護予防サービスに係る介護予防のための効果的な支援の方法の…","agenda":"第２２号議案 品川区指定地域密着型介護予防サービスの事業の人員、設備および運営ならびに指定地域密着型介護予防サービスに係る介護予防のための効果的な支援の方法の…","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この共生型サービスで、どのようなサービスがどのように変わるのかというところをまず教えていただきたい。それから品川が指定する(3)の1)の新設というところで、品川では、どの施設がこの対象になっていくのかという点についても説明を求めました。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"まず考え方としましては、なれた場所でそのままサービスを受け続けたいといったことに対応するために、こういった内容です。それから自立訓練の２種類、共生社会の実現として児童発達支援、こういった内容です。 児童発達支援、これら８カ所が、この生活介護に該当します。そのほか民間の事業所も今は増えておりますので、合わせますと児童発達支援が１２カ所、放課後等デイサービスが１２カ所というような状況です。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自立訓練で６５歳を過ぎた方というのはどうなっているのか、それが移らなくても済むというようになるのか、その辺のところ。そしてまた共生型サービスの指定を受けるとなると、その辺の仕組みについてもお聞かせいただきたいです。","respondent":"中山障害者福祉課長","answer":"６５歳を過ぎた方でも、その方の状況に応じて生活介護ですとか、あるいは就労継続支援Ｂ型に通い続けていただいているような現状があります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからあと障害者の自己負担というのは、その辺のところがどうなっていくのかという点についてもお聞かせほしいと求めました。それと、共生型サービスをこの２つが受けることで、サービスそのものがどう変わってくるのかということについてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"これは介護保険の適用になれば１割負担になることは、この間もご説明をさせていただいておりました。児童発達支援も放課後等デイサービスも、逆に刺激をし合うといいますか、今回のこの共生型の目的の１つにもしているのかなと思っているところです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６５歳だろうが、７０歳だろうが、そのまま障害の支援費のほうで受けられるということで考えていいのかということを１つお聞かせいただきたい。基本的には今までの障害者の同じ基準のまま、平米数も人員配置もそのままで、共生型サービスをとるということになるのか尋ねました。","respondent":"中山障害者福祉課長、寺嶋高齢者福祉課長","answer":"その支援区分によって１日当たりの単位数が違うのですけれども、２型という２種類しかないので、一概に比較がしにくいような状況にはなっています。ただ、例えば一番重い支援区分６の方が地域共生型に移られたときは… 今示されている内容として、やはり設備基準が圧倒的に介護保険側のデイサービスのほうが厳しいというところを踏まえてだと思われますが、約７％ほど報酬が低くなるだろうというふうに情報はとっているところです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区として考えられる課題というものがあったら、その点についてもお聞かせほしいと求めました。１割負担の償還払いなのですけれども、要支援の、その辺のところもわかったら説明を求めました。","respondent":"中山障害者福祉課長","answer":"なれた職員、ではそこ全体を日中活動の場としてどのように組み立てていくかということを考えたときには、かなり厳しい課題があるかなと思っています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中でもいろいろな委員の方が、すごく心配というか、障害の方は一人ひとり個別性が高いではないですか。そういった意味では本当にもっともっと障害として専門性を高めていくということが求められているときに、いろいろ書かれていたのです。","respondent":"寺嶋高齢者福祉課長","answer":"まだ情報が出たばかりということもありますけれども、具体的なご相談等に関しては、受けた実績はないということです。ただ、いかなるタイミングで相談にいらっしゃったときでもきちんと対応できるように、そういった動きについても注視しているといった状況です。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから２(1)3)の定期巡回のところで確認なのですけれども、地域の利用者に対してもサービス提供を行わなければならないと明確化すると。適正化を図る観点から指針の整備と出てくるのですが、これはどのように捉えたらいいのかという点を説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"全国的な話として、そうではない事業者もまだいるということでの改正であると捉えているところです。基本的にほとんどの入居施設において取り扱い方針を定めておりますけれども、こういった形での対応が改めて義務づけられたものと解釈しています。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"指針はどのように捉えたらいいですか。決まっているもの、でき上がっているものをつくれというだけでその内容に関してはタッチしていかないという感じなのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"この指定事業者の指導等の際には、その辺はきちんと把握して取り扱いについてはそれぞれに余り差が出ないように、きちんと対応できているかどうかの確認は今後していきたいと考えております。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"どういう規定なのか、どういうことを意味しているのか、内容を確認します。加えて新しいこの共生型というサービスを区としてどのように準備を進めていくのかという方向性、考え方をお聞きしておきたいと思います。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"１番目のご質問の定期巡回の部分、こちらは現在１社が対応しているといった形にはなっているのですが、引き続き検討課題だと認識しています。それから… まずは所管の連携を密にして、そのような事業所が立ち上がったときに一緒に育てていくような視点で入れればと考えております。","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問・要望","question":"私のほうからは２点ほどお伺いできればと思いますが、そうでない場合を除いて禁止をされているというふうに出ています。(6)地域密着型のほう等にも、またそういう認知症の方、どのような体制で臨まれているのか説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"何か寄与できるものがあるかということについて、前向きにというか、積極的に検討していく必要があろうかと考えているところです。施設のほうにつきましては、そういった研修については積極的に機会を設けて、今後も受けていただくというように進めていきたいと考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"連携とかというものはあるべきだと思うのですけれども、先ほどから出ていますように、それを充実させることが必要だと思います。応益負担の廃止というようなことを約束したわけですから、今回のこの条例に対しては、２本とも反対ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-04","title":"第２３号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例の一部を改正…","agenda":"第２３号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例の一部を改正…","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めに、ここの指定介護予防支援等というところは具体的にどういう事業者なのかということをお聞かせほしいと求めました。ケアプランの交付を義務づけるとか、介護報酬として評価されるという部分というものがあるのかということについてもお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"居宅介護支援事業者の予防部分、いわゆる要支援等に関するケアマネジメントを行う事業所が対象となっております。設備基準等ではなく、取り扱いのものがメインになっておりますので、報酬等に関して大きな改定があるというふうにはなっておりません。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"もしもそういうことであれば、予防のケアプランをつくっている民間のところというのは何カ所ぐらいあるのか、そこの点についても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"区内の２０の在宅介護支援センターにつきましては、予防のケアプランもつくっております。は２０の在宅介護支援センター以外に、予防のプランをつくっているのは２０の在宅介護支援センターということになります。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"第２章の「人員に関する基準」というところで、そこに「指定介護予防支援事業者は、これはここの指定介護予防支援事業者も１以上の保健師を置かなければならないという規定ということで読んでいいのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"品川区に関しましては、指定自体は１カ所、品川区が指定を受けているということなので、この規定はそういった形になります。先ほど申し上げた２０の在宅介護支援センターは、機能を地域に分担しているということなので、品川区内での指定事業者は１ということになります。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"品川区の地域包括支援センターということで捉えていいのかということの確認をお願いしたいのと、それからあと(3)の障害福祉制度の相談支援専門員との密接な連携というのは、またどういう意味でこのようなことが入ってきたのかについても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"品川区内の地域包括の事業所としては１カ所ということで、先ほどご答弁申し上げたとおりです。それから(3)の障害福祉制度の相談支援専門員との密接な連携というのが今回明文化されたということは、そういった強化がありましたので。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こうやって地域包括で高齢者のケアプランも障害者のケアプランも一緒につくっていくという意味合いというのも、ここにはあるのでしょうか。この中には、その意味合いでこのように出されているのか、そこの点について説明を求めました。","respondent":"中山障害者福祉課長","answer":"ただ、そこの連携がうまくいかないためにサービスの調整であったり、利用者への上手な説明ができなかったりということも考えられると思います。そういう形で、ご本人支援がうまくスムーズに移行できるようにということで、このたびこのような条例の改正があったところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"両方というのはすごい大変だという意見はお聞きしているところなのですが、ここのところはとりあえずそういう地域包括でケアプランも全部受け入れますよということではなくて、連携をしていくということで捉えていいのかということだけお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"あくまでも地域包括でつくのは介護保険上の予防のケアプランということになっております。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の質問のところの指定介護予防支援等というところは、そうすると在宅介護支援センターはこの指定を受けていないということなのですか。そこをちょっとお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"統括型の在宅介護支援センターと、それからあと２０の在宅介護支援センターということで１つの連携を持ってやっていたのですけれども、先ほど申し上げたように機能を各在宅介護支援センターに分散していて。","id":"exchange-038"}]},{"id":"topic-05","title":"第２４号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例","agenda":"第２４号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１回基準を教えていただきたいのと、それから在宅介護支援センターで今多分７５％ぐらい作成していると思うのですけれども、在宅介護支援センターでの１人当たりの持ち件数というのが何件ぐらいなのかということだけ説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"１人の常勤、１人の持ち分が３５人分ということになりまして、それを超えた場合は減算の対象等になっております。品川区の在宅介護支援センターも同基準に応じてやっているところです。","id":"exchange-039"}]},{"id":"topic-06","title":"第２５号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","agenda":"第２５号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"来年の３月から開設ということで、わかっていたら教えていただきたいのと、説明会で出された意見というのがありましたらお聞かせください。これは蓄電池もあるということで、このように太陽光パネルと蓄電池をセットで設置するというのは初めてだったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今までのゆうゆうプラザというのは、委託ではなかったですか。指定管理者だったのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"これまで指定管理者で運営しているところは、平塚橋のゆうゆうプラザで三徳会が運営しております。そのほかのところは委託になっております。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回指定管理者で公募する、それからこれからも多分シルバーセンターなどをどんどんゆうゆうプラザに変えていくという方針がありますよね。そのようなところも指定管理者でやっていくという考えなのか、その点についても聞かせてくださいとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"こちらのほうも１階部分と２階部分ということで、多機能であるということで、指定管理が適切だろうと判断いたしました。その際の施設運営につきましても、指定管理者にするか、委託にするかという方法については最適な方法を考えていきたいと考えています。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"多世代交流とこういうしつらえの考え方というのですか、整合性というのか、その考え方をお聞かせほしいと求めました。子育てにしても、近くには公園もありますけれども、この屋上緑化を何か活用するというお考えはあるのかどうかというのをお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"近隣のほうにはご理解いただけるよう、直接お伺いをして説明しています。高齢者の方で、在宅子育て支援世帯が集まるときに一緒に、その高齢者団体とのコラボレーションといったような交流の方法もあろうかと考えています。","id":"exchange-043"}]},{"id":"topic-07","title":"第２６号議案 品川区立高齢者住宅条例の一部を改正する条例","agenda":"第２６号議案 品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では、そのようなことは、区がその思いになればできるのかどうか。そしてそれであればぜひやっていただけないかなと思うのですけれども、いかがか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"今後、新たに結ぶ締結はまた引き続き１０年ということで考えております。こちらの高齢者住宅は、東京都のシルバーピアに準じてつくっているものです。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その住民税非課税の方の減免されたときの部屋代というのは、区として決めることができるのかということを教えていただきたいです。そのようなことでできるのであれば、そこに半分でも回していただくというふうなことは可能なのかどうなのかということでお聞きしたいです。","respondent":"松山高齢者地域支援課長","answer":"やはりシルバーピアということで、管理人を置いておりますので、その分をどう考えるかということになってくるかと考えています。それぞれの方々については、今のところ特にこれ以上ということは考えておりません。","id":"exchange-045"}]},{"id":"topic-08","title":"第２８号議案 品川区後期高齢者医療に関する条例の一部を改正する条例","agenda":"第２８号議案 品川区後期高齢者医療に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"介護保険でも、そういうところでは、後期高齢者医療だけがなぜ今になってという感じがするのです。なぜ今までそうだったのかということを説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"で、国民健康保険の方に関しましても、国保の中での住所地特例制度がございました。今回はそれを引き継ぐということで法律の改正がされたという趣旨です。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回、国保の人が他道府県の住所地特例施設等に行って、後期高齢になったときに住所地特例となるということですね。わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]},{"id":"topic-09","title":"第２９号議案 品川区住宅宿泊事業の適正な運営の確保に関する条例","agenda":"第２９号議案 品川区住宅宿泊事業の適正な運営の確保に関する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"例えば新宿などでは、パブリックコメントでどのような意見が出されたかという報告をして、そしてその後で条例の提案というような形を踏んでいます。","respondent":"井浦品川区保健所生活衛生課長","answer":"最終的な実態が明確になったのが昨年の１２月末であるという形で、検討の余裕が非常に短かったというところがあります。国の指針が明確になる前に検討会を開いていたという自治体も聞いてありますが、あるいは修正をすることも余儀なくされるところもあります。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"総務委員会で議論した、そういう時期に、私は厚生委員会の中でもぜひ提案していただきたかったなと思っています。東京都２３区で１万４,５００件が登録されているということで書かれていたのですけれども、品川区ではそういうものをつかんでいるのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"こちらもＡｉｒｂｎｂのサイトについてはご承知かもしれないのですけれども、私どもではなかなか件数を把握するところが難しいです。あるいは先ほどのＡｉｒｂｎｂでの無許可の登録についても、サイトから抹消するというような形で是正を図っているです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうものは品川の条例で規制することができるのでしょうか。少し今の説明ではどこの条文にどうあるのかというのがよくわからなかったので、そこのところもお聞かせほしいと求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"ほとんど、今回の住宅宿泊事業法が６月１５日に施行されますと、正常な形でのきちんとした民泊だけが残るという形になるのではないかと考えています。具体的な標識の設置ですとか、国の定め以上に、品川区としては適正な運営を確保しようということを図ったものです。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"適法な民泊しか許されず、違法な民泊は許されなくなるということなのですけれども、今でも違法な民泊が見つからないわけではないですか。従事者の営業時間中の施設への常駐、品川区としてもやるべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"区の窓口で適法に届出を行い、その関係で届出がされていないものについては現行の民泊サイトから次々に削除されると見込んでいるところです。このような仕組みを踏まえ、住宅宿泊事業者の責務をるる定めることで、生活環境の確保を図ってまいりたいと考えているところです。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何かあったときにどうにもならないのではないのかなと思ったのですが、東京都のガイドラインとは違って、常駐というふうになっているのでしょうか。区商連だったり、商店街だったり、そういうところの意見というものは聞かれているのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"この２４時間対応する、苦情等の対応については誠実に対処していただくというような形で指導していこうと考えているところです。余りそのようなエリアでは利益目的の無責任な民泊というものは出てこないのではないかというふうに見込んでいるところです。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７日以上の連泊になった場合には定期的に面会するということですけれども、これ誰がどのような形で面会するということになるのでしょうか。マンションとしても全体が民泊ではないわけですから、マンションの１室のような形になったときに、ポストぐらいしかないのではないかと。","respondent":"井浦品川区保健所生活衛生課長","answer":"当然営業者の責任できっちりと対応をしていただくという形でルール化していこうというふうに考えてあります。防犯上ということもあると思いますから、しっかりと協議をしていただいた上で、標識の設置場所を決めていただくというように考えているところです。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"マンションで民泊禁止にしようと多数決で規約が決まったら、そのときまで民泊をやっていたところを禁止するというふうなことも可能なのでしょうか。その辺のところの手続がどうなるのかということについて説明を求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"受理を判断していこうと考えているところですので、迷っている間に民泊がされてしまうということがないような運用を私ども考えてあります。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それがない限りは民泊は認められないということで考えていいということでしょうか。確認をお願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"品川区内には１,６００ほど分譲のマンションがございまして、３月に間に合うように規約に取り組まれているのではないかと考えています。それについてはガイドラインの中でしっかりと管理組合の意思というものを確認した上で慎重に対処していこうと考えているところです。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今の質疑の中で、苦情がたしか２２件あるとおっしゃったのですけれども、その主なものをちょっと教えてほしいと求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"その中でやはり言葉としては、民泊のように使われているのではないかというような形で、私どものところに連絡が入っているものです。あるいは警察を通して事実関係を確認するというような形で対応しまして、民泊のサイトからも削除したというような報告ももらっているところです。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"旅行客などがバッグを持って歩いていると、ああ、多分あそこに行くのだなと思って見ています。ですから地域の方はいつもそういうものを見ていると思うので、それをどう対応していったかということをもう１回教えていただけますか。","respondent":"井浦品川区保健所生活衛生課長","answer":"ごみ出しについては３件ございまして、清掃事務所とも連携し、是正に取り組んでいるというようなところです。それから騒音が２件ですとか、あるいは外国人が出入りしていて、これは適法なのかどうなのかというようなことの問い合わせ等々が具体的なところです。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区として、先ほどの課題を考えたときに、これからどういうことを課題に考えているのか。もっと細かいところがこれから出てくると思うのですが、その辺の課題があったら説明を求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"あるいは一定の、事実行為としての業務委託というようなことの可能性があるのかというようなところが今後の課題として考えているところです。当面の課題としてはそのようなところです。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"意見","question":"区としてどこまでそれが権限を持って、またその違法なものに対して指導だけで済んでしまうのか、それ以上のものはないのか。取り消しをすることがそこでできるのかどうか、条例に入ってくるのかどうか、それが見えなかったのでそこをとの意見を述べました。","respondent":"井浦品川区保健所生活衛生課長","answer":"大きく２つありまして、そして営業の停止の命令、あるいは登録の抹消等という行政上の措置という権限が１つあります。それから２つ目としましては、勾留をして刑事手続、そのような形で違法については是正していきたいと考えているところです。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認なのですが、あれは届け出して何か表示がされるのでしたか。そこに宿泊者が入っているのと民泊の部分の区別がつかないというか、余り歓迎されない部分の中で、その辺をどう見ていったらいいのかと。","respondent":"井浦品川区保健所生活衛生課長","answer":"問い合わせ等については誠実に対応していただくようにというようなことを、要綱に基づいて指導しています。民泊につきましても、こちらの条例に基づきまして適切に執行していきたいというふうに考えているところです。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それからもう１点、条例の第４条に出てきた中で、例えば建築だと建築の説明会をやりますよね。ここにいう周知というのはどういう形の周知をすればいいのか、それも説明を求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"例えばポスティングによる説明資料の戸別配付を行う等、問い合わせ先に関する案内も行うようにというような形で指導を考えているところです。東京都が２３区共通なのですけれども、民泊を行う敷地から１０メートル程度の範囲というふうに考えているところです。","id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その辺がどうなのかなというのが１点。その１０メートル範囲の説明会、やったかどうかという確認もその申請のときに、そこの点をもう１回お願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目のところです。あるいは緊急時の連絡先、案内をしていただいて、その対応の記録も届出書に添付した上で申請をしていただくというふうに考えているところです。","id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこでクレームが起きたときに、もしなくなってしまったら区のほうに対してその辺の請求をすれば、話があったときにすぐしていただけるのかどうか。これからいろいろな苦情がまた出てくると思うのですけれども、そういったときの区内の連携体制というのはもうできているのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目の、庁内の連携ですね。そして住宅課が主にマンション管理組合とのパイプがありますので、１０課ほど関係する課がありますので、庁内での連絡会を設けているです。","id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問","question":"管理人がいなくて、１日なら１日泊まった人が、結局そのごみをどうすればいいのかわからない。その指導と現実の辺りのギャップが出てくるので、その辺についてもぜひうまく管理してもらいたいと思うので、その辺のお答えをもう一度お願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"現時点での法施行前の水面下の違法な民泊で出てしまったごみというところは、なかなか悩みの種といいますか、近隣でもお困りかと思います。このあたりの情報も清掃事務所と連携を密にしまして、ベストな対応というような形でやっていくことになろうかと考えています。","id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"なぜこの民泊という、見れば見るほど不安になるガイドラインの中で、この住宅地で土日可にする理由というものを伺いたいと思います。管理組合のないワンルームマンションだったり、そういう場合は管理会社が了承してしまえばできるようになってしまうのか、そこを伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"住居地域について、土日については可能になるですが、国の住宅宿泊事業法の趣旨として、やはり一方で宿泊需要への適切な対応というところもあります。","id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"もう不安きわまりないのではないかと思うので、ちょっと土日で利益も出ないということなのであれば、ゼロにしてほしいと求めました。そこへのこうしてほしい、こうすべきだといういろいろな意見もまた、そういったものは柔軟にどんどん改善させていけるものなのか伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"こちらについては、大田区は特区民泊をやっている関係で、議論のあるところであるというふうに新聞等でも報道されてあります。やはりガイドラインについては１回つくってそれで決定ということではなくて、節目節目で適切な形でガイドラインも修正していきたいと考えています。","id":"exchange-066"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"すみません。品川区のガイドラインはいつ出るのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"国の法律の施行が３月１５日となってございまして、３月を過ぎて、適切な時点でガイドラインを固めていきたいと考えています。","id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"では３月１５日以降になってくるのか、もうちょっとかかるということなのでしょうか。それをやるのは保健所なのかということもちょっと伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"そのあたり事前相談という趣旨も踏まえまして、できるだけ早い時期に案という仮の形であっても、早目に公表していきたいと考えています。それから２点目の衛生管理のところにつきましては、保健所としてしっかりと監督指導していくです。","id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"何といいますか、衛生監視員というのですか、そういったものも国会の中では話にあるのですけれども、とてもとても人数が足りていないと。もう月に１回も見回りができていないという、品川区でいうと、それで民泊の衛生管理というものが監視できていくのかを伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"節目で監視していくというような体制をとってありますので、新たに住宅宿泊事業が監視計画の中にこれから入ってまいりまして、計画を策定していく中で適切な監視のサイクルというようなものを樹立していきたいというふうに考えているところです。","id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"住宅地へは宿泊ゼロ日というものをぜひ規制していただきたいですし、そういうところも結構、民泊の場所になりやすいところだと思うのです。それを察知するのがおくれると蔓延していくということにもなりかねませんので、ぜひ厳しい対応をさらに、国や都よりもしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"マンションの建築紛争だって予防条例の中で説明会を義務づけているではないですか。この民泊をやることによって、どれぐらいの宿泊客の需要を見込むのかという、そのような予想というのを立てている部分というのはあるのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"私どもくれぐれも事前説明、また今後の事例等、ガイドライン全体を見直す中でこの周知について改善できる点があれば改善していければと考えています。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８０％ということであれば、今の旅館やホテルでもうどうにもならないという状況ではなくて、まだまだゆとりはある、そこに民泊をさらに入れていくという感じなのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"現在の旅館、ホテルの平均稼働率が、イコール民泊との関係でまだゆとりがあるというふうに言えるのかというところについては難しいかなと考えているところです。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、１回もう規制緩和したところに規制をつくっていくというのはなかなか難しいと思うのです。だから、とにかく住居専用地域は民泊ゼロ地域ということで始めるということに、ぜひしていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"私から２つ、第５条の宿泊者の責務というところで、意義だったりを教えてほしいと求めました。先ほども区の相談を担保していくということがあったと思うのですが、どのように行っていくかというところを教えてほしいと求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目の相談窓口のところにつきましては、現在保健所生活衛生課が窓口として行っております。私ども持っている情報を踏まえまして、皆様の不安の声に丁寧誠実に対応してまいりたいというふうに考えているところです。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"一体どうやって周知をしながら、これを見たときに思ったので、その辺を教えていただきたいです。そういったときに総合的に、ここに電話してもらえればそういう関係は全部承りますというような考えはあるのか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"私どもが対応するとお答えしましたけれども、国がコールセンターを開設する予定になってございまして、４月になりますと８時半から２２時まで。","id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"どう対応してもらうかというのは本当に難しいところではあると思いますが、ここの第５条に書いてあるので、しっかりやっていただきたいなと思います。例えば２２時まで国のほうの相談窓口はやっているけれども、今は警備員の方、その辺の対応というのはどのようになっているのか説明を求めました。","respondent":"井浦品川区保健所生活衛生課長","answer":"まず１１０番等々で対応していただきまして、あるいは国を通じて保健所に届くというぐあいに連携していくのかなというふうに見てあります。ご指摘の趣旨も踏まえまして、効果的なルールづくりというようなことは課題にしていきたいというふうに考えているところです。","id":"exchange-076"},{"speaker":"若林委員","kind":"確認","question":"いわゆる民泊について品川区はどういうふうに向き合おうとして、どのような姿勢でこの条例をつくられたのかということを、基本姿勢として確認だけしておきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"２つございまして、面積的には８０％ぐらいのエリアですが、こちらについては厳しく民泊を規制していくというような考え方です。","id":"exchange-077"},{"speaker":"若林委員","kind":"質問・要望","question":"そのまま住宅街については、民泊、規制はするけれどもやりたい方はどうぞという基本スタンスですよね。初めての条例ということもありますので、またその都度見直しをしていくということの確認をさせてほしいと求めましたが、いかがか尋ねました。","respondent":"井浦品川区保健所生活衛生課長","answer":"守っていただくべきところはしっかりと守っていただくというところは揺るぎない形で進めていきたいというふうに考えてあります。そのような中で営業者、それから区民の方の不安ができるだけ起きないような形で、生活環境の確保を図っていきたいと考えています。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。民泊をつくっていくという、こういうところでは本当に不安がますます増えていくという、規制が余りにも緩過ぎるということで反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"}]},{"id":"topic-10","title":"第３８号議案 東京都後期高齢者医療広域連合規約の変更","agenda":"第３８号議案 東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成３０・３１年度の保険料率についての最終案ということで、今ご報告いただきましたけれども、これは広域連合のほうで決定をするわけですよね。その決定はいつされるのかということと、なぜ均等割を上げて所得割を下げたのかというところをちょっと教えてほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"広域連合の議決の関係ですが、平成３０年１月３１日に広域連合議会定例会において、規約の変更の了承をいただいておりました。制度発足以来、この４項目の特別対策や所得割独自軽減は継続しておりまして、引き続き保険料が値上がりしないように対応しています。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっと恒久的にこういう形を続けていただきたいと思うのですけれども、そのような、恒久的な制度にというのは全然話に出たりしていないのでしょうか。ぜひそのような希望をしていただきたいと思うのですけれどもいかがでしょうかということと、私先ほど伺ったのは、その考え方か尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"５項目という形になっておりまして、保険料の大幅な上昇が見込まれたため、どうしてもこの２年ごとということになっております。所得割に関係してきますのが２割程度となっていますので、その関係でどうしても均等割を上げていくということになっております。","id":"exchange-081"}]},{"id":"topic-11","title":"今定例会の代表・一般質問に係る所管質問ですが、今定例会の代表・一般質問中、厚生委員会に係る項目","agenda":"今定例会の代表・一般質問に係る所管質問ですが、今定例会の代表・一般質問中、厚生委員会に係る項目","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、産婦人科は廃止ということではなくて、体制ができ次第また再開するということで確認させていただいていいでしょうか。その再開のめどというのは、いつぐらいなどというのはわからないものなのか、その点お願いします。","respondent":"川島健康課長","answer":"ですので、少しお時間がかかるという話でして、そのまま廃止にするということは当然言っておりません。ただ少しお時間をくださいというような説明を、現行の東芝病院のほうでもそういう説明を今しているところですので。","id":"exchange-082"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、やめられていく医師の名前も、診療科別で出されたりしているのです。その後がやはりどうなってしまうのだろうということで、今の課長の話だと、各診療科も再開に向けて鋭意努力がされているということなのか尋ねました。","respondent":"川島健康課長","answer":"今副委員長がおっしゃったとおり、努力している最中だということ、それから引き継ぎに伴う医師の確保の関係でというようなところですけれども、そのままなくなってしまうというような形ではなくて、努力を今続けている最中だというふうに話を聞いてあります。","id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":86331,"voices":300}},{"id":"h30-20180226-8","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"建設委員会","time":"午前１０時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を123件整理しています。","topics":[{"id":"topic-01","title":"はじめに、第３０号議案 品川区営住宅条例の一部を改正する条例","agenda":"はじめに、第３０号議案 品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"制度の周知方法はどうしていらっしゃるのでしょうか。申請がないと行わないということなのでしょうか、お伺いします。","respondent":"長尾住宅課長","answer":"収入の報告の件ですけれども、毎年６月ごろに入居者の方に対しまして収入の報告を出していただいております。減額を受けられている方の割合としましては、概ね７割から８割の方が一定程度の減額を受けている状況があります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。それと収入申告をすること等が困難な事情があると事業者が認める者とは、具体的にどなたがどのように判断をされるのでしょうか、伺いたいと思います。","respondent":"長尾住宅課長","answer":"その内容に応じて減額をするものになりますので、その報告が受けられないと、減額が適用できないという制度になっております。報告をしていただく補助をしたとしても、なかなか収入の把握ができないような場合を、困難な事情であると捉えることになると考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"では、個々に認知症テストをするとか、そういうことではないということなのでしょうか。向こうから定例の６月の申告がない、全てそういう事情にあると認めるということでよろしいのかという確認をお願いします。","respondent":"長尾住宅課長","answer":"入居者の方全てに対して、認知症等に当たるのかどうかということをチェックするわけではございません。病院でその診断書を書いていただいたり、そういった書面をもってその確認をさせていただいて、報告義務を免除していくという考え方になります。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"これができたということは、今までご本人ができなかった場合に、管理をしているところでどのように調べて報告をしていたのでしょうか。それから、今までどのような状況だったのか、もう少し聞きたいのですけれども。","respondent":"長尾住宅課長","answer":"必要な書類の準備の仕方とかがわからないという方もいらっしゃいますので、そういった方には指定管理者のほうが個別に補助をしながら出していただいていたというところで、今までは収入報告をちゃんと入居者の方全員からいただけている状態になっていました。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"逆に言うと、今までの情報というのはかなり個人情報が入っていたと思うのです。それも含めて今までやっていたということなので、それには何か許可とか規定とかあった上で、そういう権限があってやっていたことなのか尋ねました。","respondent":"長尾住宅課長","answer":"指定管理者には入居者の管理の業務をやってもらっていますので、通常その入居の手続きの際も、その収入の状況の確認であるとかはやっておりますので、それと同じ内容でということになります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"管理をする側はいいのですけれども、出す書類もわからないという方々に対して、その応対も含めて実際わからない方もいらっしゃると思うのです。そういう場合に、指定管理者の方たちはそこまで調査することができる権限を持って今まで対応していたということなのか尋ねました。","respondent":"長尾住宅課長","answer":"指定管理者につきましては、それにのっとって入居者管理の際に出てくる個人情報に関しても、ちゃんと保護しながら扱っているという状況にあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"それだけの権限を持った上での、要は調査権みたいなものなのですかね。結局家賃とかいうのはその収入に応じての家賃の設定になっていると思うのですけれども、その点はどのような形に今後なっていくのか尋ねました。","respondent":"長尾住宅課長","answer":"そういった方がもしいらっしゃれば、福祉部門のほうにつないで適切な支援が受けられるようにというところは考えております。その確認した収入がもし高い収入を得ているような状況があるのであれば、それに応じた使用料を払っていただくという形になります。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"ということは、収入がわからないわけではないですか。それをどういう形で調べて、どういう責任を持って設定するのか尋ねました。","respondent":"長尾住宅課長","answer":"収入の確認の方法なのですけれども、官公署の書類の閲覧というところは、具体的には税務課のほうでの収入の確認であるとか、あるいはその方が働いていらっしゃるのであれば、もうその働いている会社自体に確認をするとか、そういったところが考えられます。","id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"先ほどの話の中で、知的障害、精神障害を含むという言葉があったのですけれども、ちょっとそこのところをもう一回説明をお願いしたいとの意見を述べました。","respondent":"長尾住宅課長","answer":"公営住宅法の施行規則の第８条の中で、具体的に定められております。知的障害者福祉法で規定する知的障害者、精神保健及び精神障害者福祉に関する法律に規定する精神障害者という定義が示されております。","id":"exchange-009"},{"speaker":"大沢委員","kind":"確認","question":"では、今後この「認知症等」という言葉で表現をしますけれども、とどのつまりは区が名義人であるこの方たちの家賃を、さまざまな書類・判断によって区が家賃を設定できるというのがこの改正の趣旨であるのか、もう一回確認させてください。","respondent":"長尾住宅課長","answer":"不利益をこうむらないように、区のほうで使用料の決定ができるような法整備がなされたので、それに合わせて条例も改正するという内容になっております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"その中で、入居者というには、名義人である本人と、それと同居人という２者がやはり家の中にいるわけです。ここの改正においてどのようにかかわっていくのか、あるいはかかわらなくていいのか、そこのところを説明を求めました。","respondent":"長尾住宅課長","answer":"ただ、これまでは通常同居されている方がいらっしゃれば、その方と連携・協力して収入の把握というのはとれていたという状況はあります。同居されているご家族とか、そういった方がいらっしゃる場合は、そういった方たちとも連携をとっております。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"この改正の部分においては、同居人がいなくて単身で生活をしている方たちにとっては、この制度というのが、今までより勝手のいい制度に変わったということで認識していいのか尋ねました。","respondent":"長尾住宅課長","answer":"そのような場合に、入居者にとっては不利益をこうむることが少なくなると理解していただいて結構かと思います。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"公営住宅法等が改正されて、それに基づいて品川区の条例の整備ということなのですけれども、この公営住宅法等が改正された時期というのはいつごろなのか尋ねました。","respondent":"長尾住宅課長","answer":"こちらが法改正されて施行されたのが、昨年の７月２６日になっております。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"昨年の７月２６日なのですけれども、条例のほうが半年以上たってからなのですけれども、大体法改正に伴っての条例改正という時間というのは、大体半年ぐらいかかってしまうものなのか尋ねました。","respondent":"長尾住宅課長","answer":"そういったこともありまして、平成３０年度の使用料決定に必要な収入報告というのは、改正法が施行される前の昨年６月にもう既に実施しておりました。","id":"exchange-014"}]},{"id":"topic-02","title":"第３１号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"第３１号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"横山委員","kind":"質問","question":"今回賃貸借契約に移行という話なのですけれども、４７戸全て移行になるのでしょうか。通知ですとか、賃貸借契約もスムーズに進んでいらっしゃるのかどうか、その状況だけ説明を求めました。","respondent":"長尾住宅課長","answer":"１年前に当たります昨年８月末ごろに、そちらの情報もあわせてご案内しているところです。入居されている方の中でそのまま住み続ける方と、あと出ていかれる方のご予定というところまでは、こちらのほうでは把握しておりません。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"１９戸ということで、昨年８月に通知のほうは全てしていただいていて、新しい管理会社の方ともつないでいただいているということを確認できました。今後、また出られる方がいらっしゃるということなのですけれども、スムーズに移行が進むようにサポートのほうをぜひ要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"新旧対照表のところに、この資料の日付を見ると、「平成２９年１２月１４日」となっているのは、これはどういう意味なのでしょうか。議案を審議する段取りの時系列というものを説明を求めました。","respondent":"長尾住宅課長","answer":"こちらは、新旧対照表を印刷する際に、その印刷日が入っていただけでありまして、特に改正する期日との連動ということはございません。大変失礼いたしました。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"入居者にとって管理が変わることでの具体的な変化というのはどのようになるのかというのを区としてはどのようにお考えなのか聞かせていただきたいの…それと、順次今回のように借上型住宅の位置づけが廃止されてきたわけですが、そういうのはなかったのかというのをちょっとお伺いしたいと思います。","respondent":"長尾住宅課長","answer":"現行の区民住宅の設定家賃を参照して、そういった意味でも、特に大きな変化はないと考えております。オーナー側、順調に引き継ぎのところについてもできていると考えておりますので、今のところは特に問題はないと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"位置づけが公の施設ではなくなったということで、その後こういう空いていたところというのは埋まっていっているのでしょうか。それはもはや区の施設ではないのであれかもしれないのですけれども、区としてはつかんでいらっしゃるのか、その状況をお伺いしたいのが１点。","respondent":"長尾住宅課長","answer":"区民住宅が建てられ始めたのが平成５年ですけれども、そういった中で、今人口も増加傾向にある状況もあります。区民住宅としては、建設型・借上型を含めてありましたけれども、一定程度定住化に対しての役割というのは果たしていると考えております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと何か今のご説明ですと、一定もうこの目的は達成されているのでという話に聞こえてしまうのですが、今後区民住宅というのは、どのような考えで区としては事業を進めていく考えなのでしょうか、伺いたいと思います。","respondent":"長尾住宅課長","answer":"当初の契約で２０年間というところで借り上げておりましたので、その契約の終了をもって、返還をずっと進めてきているところです。平成３０年度に区民住宅のあり方について検討する予定ですので、その中で今後の活用の仕方も改めて考えていきたいと思います。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"４７戸あって、１９戸しか入っていないということは、いつからこういう状況だったのでしょうか。それはどのぐらいの品川区の負担があったのだろうかと思うのですが、いかがか尋ねました。","respondent":"長尾住宅課長","answer":"昨年４月時点のころは半分ぐらい埋まっていたはずですので、２４戸とか２５戸あたりが入居されていたと記憶しております。逆に出ていかれる方が結果的には出ていったので、現時点では１９戸に入居されているという状況にあります。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"そしてまた出られる方もいらっしゃるということになると、やはり何か不都合があったのでしょうか。何かわかればと思うのですが、いかがか尋ねました。","respondent":"長尾住宅課長、藤田都市環境部長","answer":"そういった中で、募集の仕方の工夫であるとかはしたものの、結果的には新しく入ってこられる方がいらっしゃらなかったと。入居されていた方の中で、やはりその方の収入と家賃とのバランスを考えた時に… 先ほど１年ほど前、その後８月ぐらいに、管理形態が変わるのであればこの際転居をしようと思うような方もいらっしゃったということだと思います。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ単に管理体系、もうこれ去年４月の段階で半分ぐらいという形ですから、その運営状態がどうだったのかなという疑問がやはり私は出てきます。これを機会に、ちょっとほかのところもオーナーとしっかりと話をしながら進めていただきたいと考えていますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"第３２号議案 品川区手数料条例の一部を改正する条例","agenda":"第３２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"田園居住地域についての参考で、ご説明が資料にありますが、生産緑地がある区とはどこになるのでしょうか。それと、この許可申請が仮に行われて許可された場合というのは、具体的などのような制限がかかるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"現在２３区の中で生産緑地のある区としましては、世田谷区、江戸川区、杉並区、板橋区、練馬区、足立区、葛飾区です。ご質問の２点目ですが、あるいは資材置き場ですとか、生産緑地の保護の観点からできるようになるというものです。","id":"exchange-024"}]},{"id":"topic-04","title":"第３３号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３３号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区部分の再開発の部分の都市計画決定というのは３月に予定をされていると伺っていますが、なぜこちらだけ先にやるのかと。それと、区の都市計画決定が都の決定後の３月予定になっている理由が何かあれば、お伺いしたいと思います。","respondent":"稲田都市開発課長、鈴木建築課長","answer":"では、なぜ大崎駅西口Ｆ南地区第一種市街地再開発事業の都市計画決定が３月の予定なのかです。Ｆ南地区ともあわせましてこのＥ西地区を変更して、事業系の事務所等、そのような形でやっていくということです。東京都の都市計画決定後、ただちに本条例について改正するその理由ですが、やはり都市計画決定のみですと基本的には届出行為です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"私がやった質問の中で、なぜ区の部分は都決定の後の３月予定になっているのですかという理由を伺ったので、聞かせてください。ただ単に航空法で目いっぱいということですから、心配されている近接の方々が住んでいる住宅地のそれぞれの用途地域はどうなっているのか。","respondent":"中村都市計画課長、鈴木建築課長","answer":"一体として絶対的なことで区が考えているというものではなくて、地区計画と再開発、それぞれ決定をしていくです。ただ、これが２つ合わさることによって… 日影につきましては、基本的には日影の規制がかかっているところについては、その日影の規制を遵守するです。計画の中では容積率が高いところがありますが… ここは変わらないところはそのまま、その周辺の日影規制は変わらないところはそれを遵守しなければならない。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとご説明いただきたいのが、開発計画地の北側にあるところの住宅地の用途地域は何で、具体的にはどういうルールがかかっているのですか。何時間とかあるのではないですかという、そこら辺が聞きたかったのです。","respondent":"鈴木建築課長","answer":"北側につきましては第一種住居地域でございまして、日影のほうが４時間、２.５時間です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"今回の１４９ｍのビルの事業者はみずからの１棟の計画にしか縛られないのです。私は行政しかないと思うのですけれども、あるいは出させるよう指導するべきだと思うのですけれども、そういった考えはあるのか伺いたいと思います。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"複合日影というものの考え方を取り入れますと、ほぼ品川区内、隣接地に日影が落とせなくなってしまうというような計画の規制になってしまいます。周辺環境も一定程度確保しているというような考え方で、確かにお考えはわかりますけれど… こちらの開発のほうからの考え方としましては、品川区におきましても都市活性化という点、このまちづくりを進めているというのが根本的なところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"大崎の同様の再開発でそのような計画はあったのでしょうか、伺います。半数以上が単身住宅という計画が、大崎のまちづくりでみずから上位計画に掲げているまちづくりと合致していると考えているのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中に住宅も含まれておりまして、このまちづくり、大崎の周辺を活性化していこうというところで住居機能も入れているです。そういう中におきましては、ファミリー層向けのところ、それから単身者向けのところということで適正配置を行ってきてあります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"確認","question":"適正だという認識があるというふうに聞こえたのですが、それでいいのでしょうかという確認と、私は適正なのかなとかなり疑問があります。それがどうなのかということを考えるべきであって、やる考えはないということなのですか、伺わせてください。","respondent":"稲田都市開発課長","answer":"ファミリー層、それから単身者層等々を全体的に考えながらやっていくというところで、そのような単身向けのものも配置してきたです。複合日影を検討させないのかというような話ですが、先ほど来言っていますように、基本的に私どもはこの条例・基準を守りながらやっているです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"これを進める上での地区計画ということですから伺うのですけれども、大崎駅のあの状態で、私はまちづくりを進める品川区としてどうかと。私は大崎駅のあの状況を見たら、もう人口を集めることありき、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"これはやはり大きな区の方針であります品川区まちづくりマスタープラン等々に基づきまして、都市型住宅というものを進めていく拠点の整備です。事務所機能も必要、商業機能も必要というところでまちづくりをやっているところですので、ご理解願います。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"これもまちづくりとして大問題ではないかと思うのですけれども、あそこの区道の混雑の問題は現時点で品川区はどのように認識をしているのでしょうか。問題ないと考えているのでしょうか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"大崎駅の混雑ですけれども、こちらのほうはＪＲのほうにも引き続き改善に対する検討を進めてもらうようにしています。これからも進めてまいります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、問題だと思っているのですかというか、混んでいるという自覚があるのですかというのが一つ伺いたかったのです。その辺がちょっとわからないなと思って、そこら辺もお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"まず再開発事業を行っていくときには、開発等をこのような形で今検討していますよということで、協議をずっとしながらやってきているです。それと、大崎陸橋の混雑についてですが、もちろんこのＦ南地区を検討するにあたりましては交通量調査等々をかけてやってきてあります。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"この３番のところの4)の風営法なのですけれども、今回は従前のものを適用するという考えなのか、これはどういうことを言っているのか。これは今どういう熟度になっているのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"いやいや、この地区はやれるようにしてもいいのではないかという議論を各地区で今後行い、順次地区計画のほうも変えていかなくてはいけない。基本的には各地区計画が制定したとおりの考え方に伴って、「用途地域上できない」というふう… こちらは現在準備組合で検討が進められて、平成２６年に準備組合ができたのですけれども、今それで検討が進められているところです。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"そうなってくると、議会のほうに全部出てくるとうことなのかと思ったのですが、そういう感覚でいいのでしょうかというのが一つです。今、これからのスケジュール感というのはどのようなスケジュール感をもって考えていればいいのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"今のところその進め方についてはちょっと内部で検討しているところなのですけれども、個別でご検討いただくというよりも。ですので、各地区でご意見を聞いて、その各地区ごとで例えば条例改正を一個一個やっていくというところではなく… 現在準備組合への加入促進も図りながら検討を続けているというところでございまして、言われました商業的な話とか、まだまだ検討している状況です。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"その整備を含めて、風営法ですから、ただ単に法律が変わったのでという形だけでは住民は納得いかないところがあると思うのです。なので、この地区の再開発に関する考え方もお知らせいただきたいのです。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"風営法の中身については、やはり一番はダンスホールが風営法の法改正で一番大きなところです。なぜダンスホールが風営法から外れたかというところはしっかりわかりやすく説明をして、お考えいただいて… 商業機能、大崎駅周辺を拠点としてつくっていくというのが基本的な考えですので、基本は権利者がまず検討してというところで今やっているところです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そこまで含めての対応をお願いしたいのです。なかなかこれは理解を求めるのは難しいところがあると思いますので、ぜひそこをお願いしたいという意見と、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"意見","question":"反対です。さらに区の再開発事業のかかわる都市計画決定もまだされていませんので、そういった時期の問題から見ても問題だと思いますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"}]},{"id":"topic-05","title":"平成３０年請願第９号 コミュニティーバスの運行に関する請願","agenda":"平成３０年請願第９号 コミュニティーバスの運行に関する請願","exchanges":[{"speaker":"新妻委員","kind":"提案","question":"コミュニティーバスの提案ということで、行きたい公共施設に直接行けないというような不便さもあるのは事実だと思うのです。まず１つ、どういう形で要望していただいているのか、どういう可能性があるのかというところを教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"区としてこのコミュニティーバスの考え方といたしましては、１つは新しい道路が整備されるに伴いまして路線を増やしていったりですとか、あるいは路線の延長を積極的に機会あるごとに働きかけるという形で行っております。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"区が要望していただいた中で、具体的に今後このようになっていきますというような現段階で見えているところがあるのか尋ねました。","respondent":"中村都市計画課長","answer":"１つは代表的なところでいきますと、現在２６号線の整備が東京都によって進められております。事業者のほうは、この開通に合わせて今検討を行って、実施の方向で作業を進めていっているところです。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"１時間に１本であったり数時間に１本であったりというような、利便性としてはちょっとやはり欠けるところがあるのかなという思いはいたします。区としてはこの地域においての改善策というのはどのようにお考えなのかというところをお聞かせほしいと求めました。","respondent":"中村都市計画課長","answer":"１０分に１本ぐらい、路線が別々のところが来ますので、やはりご要望の中ではこの便数を増やしていくというところが解決策にはなるのかと思います。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後高齢化が非常に進む中では、コミュニティーバスがあってもなかなかそれでも改善できないというようなところも出てくるのではないかと思うのです。コミュニティーバスも一つなのですけれども、そのほかにもそういうようなお考えがあるのかというところを確認したいと思います。","respondent":"中村都市計画課長","answer":"ただ、その中にも全く歩行ができない方に対しての対応というのはまた考え方が違ってくるのかもしれませんけれども、歩行の機会をとっていただく。この辺を鑑みまして、いろいろ検討の仕方もあると思いますので、まずは声をかけていきたいと考えております。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"２３区の中でのコミュニティーバスの実施状況をどうつかんでいらっしゃるのか伺いたいと、区としては実施状況をどうつかんでいるか、１点目です。多くの区では区民のニーズに応えてコミュニティーバスを走らせているのですが、なぜ品川区はやらないのか、改めて理由を説明を求めました。","respondent":"中村都市計画課長","answer":"走らせていないというのは定義がいろいろあるところですけれども、区のほうではご指摘のとおり、約２０区近くが実施をしています。先ほどの繰り返しになりますけれども、今のところコミュニティーバスの運行は慎重に検討したいと考えています。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"２０区近くが何らかの形で実施しているということですが、タクシーですか、そういう考えはないのですか。住民の移動の権利保障は自治体の責務だと考えていないのか、まずそこら辺はしっかりとお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"簡単に廃止したり、あるいは値上げしたりできないように、それぞれ自治体とも協議をしながら進めて運行してもらっているところです。それぞれの事業者で、これからも引き続き運行が適切に行われるようなコントロールをしていくべきだと考えています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"それを保障するのは自治体の責務なのではないですかとお伺いしましたので、そこら辺はしっかりどう考えているのかお伺いしたいというのが１点です。なぜ走らせないのかというところで、最近は全然言わないのですけれども、では財政問題は特に理由ではないということでよろしいのか尋ねました。","respondent":"中村都市計画課長","answer":"そういった面からいたしますと、やはり路線の選定には非常に慎重な検討を要すると思いますし、今現在品川区の中では。そういったところで、やはり今ある路線の延長と、これからも進めていくという考えを先ほどお示ししたところです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜこの建設委員会の資料では７００ｍで出すのか。区がつくったこの地域交通検討会では５００ｍなのに、なぜ７００ｍなのかというのをお伺いしたいと思いますし、お伺いします。","respondent":"中村都市計画課長","answer":"この駅勢圏、あるいはバス停勢圏の考え方としましては、例えば駅勢圏などでは、国や都の考え方では通常は駅から１ｋｍというような見方もあります。今度まずは福祉部門との連携支援を考えを意識しつつ、一つの考え方をもって解決していくといった方法があるかと考えています。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ出さないのでしょうかというのをちょっともう一度お聞かせください。地域交通検討会の資料では、そういうことでよろしいのですかというのを伺ったので、しっかりとお聞かせほしいと求めました。","respondent":"中村都市計画課長","answer":"この駅勢圏、バス停勢圏の距離の考え方については、これはそれぞれ考え方がありますので、この５００ｍという距離は一つの考え方です。今回お示しした７００ｍというのは、これは通常歩行が困難な方でも、ゆっくり歩いても１５分以内で来られるということでお示しをしたものです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"これは区は認めますよねということをお伺いしたので、なぜあえてこの区が招集した会議で出している資料を出さないのかなというのがちょっと解せないということで伺ったのですけれども、何かあればそちらもお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"通常歩行が困難な方に対して歩ける歩行距離というもので、区が設定しているのは７００ｍです。特に困難な方の場合には、これはまた別の側面から支援が必要だという考え方に基づく資料の場合は、そういった短い距離で出す場合もあります。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"この資料と建設委員会の資料との答弁のずれがあるのはなぜなのですか。どちらなのですかというのをお伺いします。","respondent":"中村都市計画課長","answer":"それから、公共交通の地域交通検討会の中でお示しした資料は、別の福祉的な支援が必要な方も想定された中での徒歩圏というような意味です。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはそんな期待されるのですか。どのような道路なのですかというのをちょっとお伺いしたいのですけれども、そこら辺もちょっときちんとお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"これも、今区内で進められている計画道路というのはそれぞれ路線がありまして、それぞれについて目標年次というものがあります。新しいバス路線も考えられる、また検討の余地がある、積極的に検討すべきであるといった考え方をその資料の中ではお示しをしているものです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここはどういう道路が通る予定でそういう期待がされるのですか。この地域でどのようなコミュニティーバス以外の解消法があると考えていらっしゃるのか、しっかりと伺わせてほしいと求めました。","respondent":"中村都市計画課長","answer":"福祉的な支援が必要な方に対しての交通不便地域という表現の仕方もあると思いますけれども、それはまだ決定しているというものではございませんので。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"やはり交通不便地域だと書きながら、どういう道路計画があるのかというのもお示しできない、今書けない。しっかりと地域の実情に応じたコミュニティーバスの運行が必要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"筒井委員","kind":"質問・要望","question":"武蔵小山から例えば八潮まで一気に行けるような路線をコミュニティーバス路線として設けるというのはいかがお考えでしょうか。その点についてご意見をいただきたいのですけれども。","respondent":"中村都市計画課長","answer":"この路線が確かにご指摘のとおり、長ければ長いほどいいのかもしれませんけれども、運行を開始するにあたっては、まずはある一定程度の設定が必要だですので、その辺は今後バス事業者とともに詰めを行っていきたいと考えています。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区も今、そうした品川区の都市型観光を進めるという点、それに関連してコミュニティーバスを走らせるというお考えはないのでしょうか。その点はどうか尋ねました。","respondent":"中村都市計画課長","answer":"それは品川区内のほうは、先ほども説明申し上げましたとおり、この路線バスで大体巡れるというようなバス停勢圏になっております。今後、必要に応じてその辺はまた検討していく必要はあるかと考えております。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひともその東西を横断する、八潮から武蔵小山に一気に行けるような路線のほうも、ぜひとも検討していっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"その中で、品川区として費用対効果を何か検証したことはありますでしょうか。ほかのところの運営状況がわかれば説明を求めました。","respondent":"中村都市計画課長","answer":"ある区、車両の導入に際して約３億円の費用全額補助、それからあと毎年ランニングコストとして１億５,７００万円といったところです。区といたしましては、１つは路線を延長した場合はどうかというところを検討した時に、約２,０００万円の負担が出るという試算があります。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"たしか２６号線の開通の時に、それがコミュニティーバスという形をとるのか、地域の方々もご納得していただけるかなと安心をしたのです。今後需要の中で検討するという余地があるのかどうかということはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"今ある既存の路線バスの事業者と十分な協議をするとともに、ここら辺も負担をするような考え方も必要になってくる可能性もあるかと考えております。いずれにしましてもそういった協議が必要だというところで、非常に慎重な検討が導入には必要だと考えております。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ここのところはちょっとやってほしいという場合での補助を出すということも考えられないことではないのかなと思うのです。ぜひそこら辺はきっちりとけじめをつけた形での議論を私たちもしていく必要があるのかなということを強く感じますので、これは意見ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"大沢委員","kind":"質問","question":"１００ｍ、０ｍ、家の前までドア・トゥー・トアみたいに果たしてコミュニティーバスを運行しているのか尋ねました。","respondent":"中村都市計画課長","answer":"今、それを満たすためには網の目のようにバス停なり路線なりを走らせなければいけないというところで、非常に難しいところがあります。そういった一部の路線でありまして、このバス停の間隔が狭くなるような運行をしているところは特にはございません。","id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すで、採択なのですが、やはり住民の移動の権利保障をしっかりと自治体の責務として果たしてほしいと。かなり大事な深刻な現状だと思いますので、しっかりそうした願いに応えるということが必要だと思いますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"そういった状況の中で、常にアンテナを張ってバス事業者と協議を重ねて、何が最善であるかというのを見出してほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すで、不採択。利便性、もしくは観光や福祉の観点も含めて総合的に考えていかなければいけないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺をもう一度説明いただきたいのですけれども、お伺いしたいと。それと、広場と道路の計画についても、世帯数と建物の立ち退きはどれぐらいになる計画なのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"それから、こちらは１２月に行われた説明会の中で、東京都からは２５軒の方にご協力をいただくというような回答がございました。今後測量等で明確にしていく予定です。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"高架化に伴う立ち退きのほうの請願にあるような、専門家等第三者による検討はされたのでしょうか、伺いたいと思います。それと、都市計画案への意見書の数と反対・賛成意見の内訳は大体どのような感じなのかというのを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、冒頭でご説明したとおり、東京都が検討・調査を行っているものです。それから、説明会におきます意見書の数です。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"おそらく意見書なども出しているのではないかと思うのですけれども、伺いたいというのが１つです。広場のほうの資料の具体的な中身についてお伺いしたいのですけれども、２、それはちょっと伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、私ども説明会の中でもご説明させていただいておりまして、そういうような措置で分けていきたいという考えです。駅前広場の中でできる構造物がどのようなものがあるかというところについて、今後検討をしていく予定です。","id":"exchange-065"},{"speaker":"安藤委員","kind":"確認","question":"これはそのように伺っているということなので、では別に区が確認しているわけでは、調査したわけでも測定したわけでもないということなのでしょうか。十分にこういうところで少し対応すれば、こういう対応で全然問題ないと思うのですけれども、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"旧東海道品川宿周辺まちづくり協議会からのご意見としては、地域の意見としてどういう対応ができるかという部分は今後考えていきたいと考えています。都市計画の定める中でどのような対応ができるかというところで、今後も検討を進めてまいります。","id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"それ以前に実態として、こういったことを課題に挙げて地域の方に大きな負担をかけるような計画というのは、やはり見直すべきだと思います。一旦やめますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"新妻委員","kind":"質問・要望","question":"できること、できないことあると思うのですけれども、できることを最大限に寄り添ってほしいと求めましたので、よろしくお願いいたします。いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"今回、駅前広場につきましては１,０００名を超える署名を伴う請願が出ているということは、皆様のご意見として重く受けとめているところです。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"その際に私の意見を申し上げたと思うのですが、高架化に伴っての用地、立ち退きというところは出てくるでしょうという話をしていたと思うのです。なかなか時間的に１２月ですか、そういうふうに提示すべきではなかったのではないかと思うのですが、その辺はいかがなのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"どういう考え方で都市計画を進めるのかという説明会を行った後に、事業者として権利者の方に当たっていくというようなスタンスです。高架化のほうの事業につきましては、東京都が事業主体となり進めていくものですので、権利者の方には丁寧な対応をしていくつもりです。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"そのご協力いただいている方々には丁寧にご理解を求めていくということは、交通広場については、これは品川区独自の考え方だと思うのです。これはどのようにこれから進められようとするのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"広場計画につきましては、現在都市計画案としての説明を行っているところです。今、１年近く都市計画審議会まですので、それから東京都とか警察等の調整といったものを進めていきたいと考えています。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"その中でのこの交通広場というのはどういう位置づけになるのでしょうか。地域の方のご意見もたくさんあるかと思うのですが、今後のやり方についてはいかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"駅周辺を重点検討区域と定めておりまして、こちらがまずマスタープラン、それからまちづくりビジョンでの位置づけを行っているところです。品川浦周辺地区再開発協議会では、この駅前広場のところも含む地域につきまして、今再開発のコンセプト等の検討を行っているです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、それがあるがために全体像がちょっと見えにくくなっているというようなことになってはいけないと思うのです。そういう考え方もあるのではないか、その中で十分に地域の方々と再開発も含めて議論して、その辺の考え方はいかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"そういったものを目標にして進めているというところでありますので、その目標を達成するように広場づくりを進めていきたいと考えています。再開発につきましても１０年スパンで行うような事業ですので、そことの整合性はとっていきたいと考えております。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"もっと延ばせば今度、品川の新駅について、そこら辺からリンクしている計画の一つであるという認識でここの高架化に対する問題はとらえていいのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"平成７年当時、京急線八ツ山橋付近の立体化の検討を建設省・東京都・品川区、それから鉄道事業者といったところが入って検討していった結果として。こういった大きな流れ、そういった大きな流れによってこちらの計画が進んできたものということで理解しております。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、この計画によって、今、課長がおっしゃった３つの踏切の除却をすることによって、交通アクセスまたはその立地の利便性がさらに上がると。この部分についてはそういうような副産物というか成果物が生まれてくるというのは、確信を持っていいのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"踏切解消をすることによりまして、駅が高架化します。東西のまちにつきまして行き来がしやすくなる、まちの一体化ができるというようなところもありますので、委員が今おっしゃったとおりです。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問","question":"この請願にありますように「現在のルートが唯一無二であることを証明するような」ということなのですけれども、これは現実問題できることなのでしょうか、お伺いしたいです。","respondent":"東野まちづくり立体化担当課長","answer":"地下にする、そういった地形的なところまで、それから構造物も含めたところまで考えてこの線形になったということで聞いてあります。私どもはそういう東京都からの報告を受けまして、これが適切な線形だと考えておりますので、これ以上東京都に何ら言うことはないと考えています。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"この２つの請願に共通して言うと「立ち退きのない形で」という文言がありますけれども、利便性がよくなってくるという比較衡量的なものをよく説明をしていただきながらこの事業を進めていただきたいと思うのですけれども、いかがお考えか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"委員がおっしゃったところは非常に重要なところだと考えています。ご協力いただく方の生活再建を十分に考えた上で、そういった説明についても行いましてご協力を求めていきたいと考えています。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問","question":"そういった観点を踏まえて質問しますけれども、それは今現行通っている路線があるから、これを使えないという理由なのですか。この鉄道橋を活かすことはできないのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"鉄道の立体化につきましては、運行に支障がない範囲の中で進めていくという形になります。そういった意味では、運行させながらというところは非常に難しいものです。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"東京都が長年調査した結果、これしかないということだと品川区もお認めになっていますけれども、果たしてそうなのかと。なかなかよくないことかなと考えておりますので、新しい別途第二の意見を持った専門家の方たちにご意見を聞くというお考えはないのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらも冒頭にご説明していますが、この高架化計画につきましては東京都が計画し、東京都施工で進めるものです。これも専門家と言ってもどこがという部分がありますけれども、改めてそういうところに調査を出すということについては考えてございません。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。この交通広場が必要なのですというその逆算してこの交通広場が必要だという説明がなかなか見えないと思うのですけれども、その点いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"そういった流れから、まちづくりを進めているというようなものです。駅前広場という部分につきましても、京急の高架化の機会に合わせまして進めていくという位置づけになっているものです。","id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"一方のまちの方のご意見によりますと、やはり品川浦に行くには、直接品川駅からタクシーなり徒歩なりで行ってしまうので、わざわざここに交通広場をつくる必要はないというご意見もあるのですけれども、それについてどうお考えか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"それから国道、御殿山のほうから来る方についてはちょうどここの交通広場部分を通って行かれる方、そういったいろいろなルートがあります。そういったところ、全体を加味しながら考えているものです。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問・要望","question":"立ち退きを迫られる方々との引き続き丁寧な説明と意見交換をしていっていただきたいと考えておりますので、その点よろしくお願い申し上げます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"計画案作成段階で、住民意見を反映させるというのが都市計画法第１６条ですが、その都市計画法第１６条違反ではないでしょうか、伺います。第１７条の説明会を開いて案をつくったのに、なぜ同じ都市計画決定なのに、この広場ですとそれをしないのかもあわせてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"まちの方々の意見なども伺った上で、意見をまとめて都市計画案の説明会として、第１７条にかわるものとしまして１２月に説明会を行っているものです。特に地権者への説明、公に区のほうで説明を行っているものでございまして、意見の反映に努めているところです。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺がちょっとわからなかった、答弁もなかったので、１つお伺いします。それぞれ伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発の説明会との違いというお話がございました。昨年１月の都市計画素案の説明会につきましては、その時は沿線住民の方、広い範囲でご案内をした上で台場小学校で開催させていただいたものです。","id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"ですから、清水横丁はなくなっても仕方ないと考えているということなのですか。それは区の姿勢としてどうなのか、もう一度伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"駅前から旧東海道に抜けるところにつきましては、やはりそれでは不十分であるということで考えてあります。こちら清水横丁につきましては、そういった清水横丁があったという記憶を残すようなしつらえを考える中で対応をしていきたいと考えております。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"ですから、伺いたいのは、立ち退きのない範囲での計画に変更したとして、何か問題でもあるのでしょうか。それで何も支障がないと思いますけれども、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"まちの発展のためにきちんと道路に面した駅前広場というものが必要と考えていますので、今現在としては考えていないところです。協力をお願いしていきたいと思います。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"この範囲の中で何か支障があるとは全く思えないのですけれども、具体的にそこら辺の機能に照らして何か問題があるのですか。いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは旧東海道側に抜けることを目的としてございませんので、こちらの交通広場部分でロータリー型のものを計画する形になります。車の車輪の関係、そういったものをきちんととった形での計画が必要になってありますので、このぐらいの大きさのものが必要と考えているものです。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"その中で言っているように、区長は京急に広場が本当に必要なのですかと話をしたのでしょうか。そこら辺をちょっと伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"そういう意味では、安全な歩行者空間やたまり空間、他の交通との乗り継ぎというのが駅前の機能として必要なものと我々のほうは考えてあります。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"区長はこの場にいないのであれですけれども、どうなのですか。まちづくりの部隊としてはどのように考えるか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"区長の発言の趣旨としましては、先ほど来私が答えているものと何ら変わらないと考えています。一貫してこちらの駅前広場づくりにつきましては区として進めているものですので、何らぶれているものでも何も変わらないものです。","id":"exchange-088"},{"speaker":"安藤委員","kind":"意見","question":"ちょっと区民の普通の感覚から言って、区長のあの当時の答えというのは、とてもそのように言ったとは私は受けとめられませんでした。ぶれはないのだということですが、こういう不誠実な対応を重ねているこの事業についても、やはりこれはしっかりと見直してもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと確認なのですけれども、国道１５号からは右折できないということなのですよね。国道１５号から取付道路、それを確認します。","respondent":"東野まちづくり立体化担当課長","answer":"国道のところにつきましては、真ん中のところが抜けられない形になりますので、右折はできません。左折インで、左折アウトで出ていくという形になります。","id":"exchange-090"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、この取付道路はどれほどの効用があるのかなというのはかなり疑問になってきます。第１のルートとして、品川浦のほうから都営アパートとかあのあたりから来て、それで第一京浜に抜けるということを想定されているのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"今、委員がおっしゃったように、国道側からは北側から入るものを想定しております。なお八ッ山通り側から入る車につきましても、ちょうどこの取付道路部分と書いてある部分を抜けていくというところも想定しています。","id":"exchange-091"},{"speaker":"筒井委員","kind":"質問","question":"それがどれだけ交通需要があるのかということと、あと旧東海道もそのまま入っていって、南に下る方もやはり増えるかとお思いでしょうか。歩行者の通行安全上、ちょっとどうなのかなという危惧もありますけれども、そういう安全性についてはどのようにお考えなのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"交通量調査ですと、旧東海道は１日に１,２００台ほど交通量があります。そういう効果もあると考えていますので、この道路をつくることによって若干減るのではないかという予測をしています。","id":"exchange-092"},{"speaker":"筒井委員","kind":"質問・要望","question":"いずれにしましても本当にこの道路が区にとって意味があるもの、その点、どうかよろしくお願い申し上げます。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"３カ所踏切が解消されるということですが、３カ所解消することによってどういうメリットがまず生まれるかとお考えか。逆に言えばもう大田区まで含めて立体になるのかどうなのかというのをまず１点お願いします。","respondent":"東野まちづくり立体化担当課長","answer":"踏切等と電車が交錯しないという部分では、安全な通行が可能となるという部分があります。それから、品川区内につきましては、京急線につきましては全て高架になるという形になります。","id":"exchange-094"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"これはこういう請願が上がってきているということですから、どのような方向性が一番ベストなのかというのを、幅広くやってほしいと求めました。その辺の、何か全体においての見直しというのを今後どう考えているのか、説明を求めました。","respondent":"東野まちづくり立体化担当課長","answer":"品川駅側へというような考え方もございましたけれども、交通の立地上、それは致し方ないということで判断をいたしております。東京都ないし警視庁のほうとも協議をした上で、この計画を立てているものですので、ご理解いただければと思います。","id":"exchange-095"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"わざわざ歩道橋で国道を渡って向こうに行ってということになるわけじゃないですか。だから見直しも含めて、考え方の再考も含めて、お考えがあるかどうかというのを説明を求めました。","respondent":"東野まちづくり立体化担当課長","answer":"国道側につきましては、まず最初国道側での計画ができないかというところで区のほうも考えたものです。はベイ形式のものとしてできないかという検討もしたのですけれども、こちらは図のほうにもありますとおり、交差点から近い形状になってあります。","id":"exchange-096"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"しっかりとした立体、そして駅前広場を、つくるのには別に反対ではないですよ。どうしても引っかかるのがさっき言った部分なので、それがもし技術的に無理なのであれば、それだけは真摯に受けとめてやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"その結果、だめだと言われたのかどうかというのを確認したいというのが１つ。ですから、何をもってここにバスベイができないと判断しているのか、そこら辺をきちんと伺わせてほしいと求めました。","respondent":"東野まちづくり立体化担当課長","answer":"品川警察署のほうとの協議も行っておりますし、そういう都市施設についてはこちらの国道側へはつくれないというようなことを言われております。品川区としても、その計画につきましてはまた別の案として、今現在の計画を立てたという形になってあります。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"最初国道側にも考えたのだけれども、つくれないと言われたと言いますけれども、何でつくれないと言われたのですか。品川区がそこにつくろうという考えがないからではないのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"言われた内容といたしましては、交差点から３０ｍ以上離さないと、ベイみたいな形のものは切れないと言われております。我々のコンサルタントのほうとの協議も行っておりまして、複数案をもって警察との協議に当たったというものです。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"原則そうかもしれないけれども、だめではないのではないですかというのを１点お伺いします。国道側にバスベイができればそういう問題はなくなる面があるわけですから、そこら辺はどうなのでしょうか、伺います。","respondent":"東野まちづくり立体化担当課長","answer":"いろいろな案について検討し、どういうものができるのかというようなことをさまざま検討した結果として、国道側へはできないと判断したものです。こちらの計画につきましては、さまざまな検討をした結果として、ここに配置を考えたものです。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択で行きたいのですけれども、やはりあらゆる方法で立ち退きがない状態で、高架ができる方策を考えていくということは大事だと思いますので、ぜひそこを最後まで努力をしていただきたいと思っていますので、趣旨採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"言っていることが心に響いているか私はわからないですけれども、これは本当に地域の話をしっかり聞いてやっていただきたいというのが大前提です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"東京都の事業だからという、しっかりとこれの必要性であるとか、ご納得する形をぜひとっていただきたいと思っています。この後も補償問題などが出てくると思うのですけれども、それについても十分に話し合って、もうできる限りのことをやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"安藤委員","kind":"意見","question":"採択でお願いしたいのですが、やはり東側のほうに広場をつくることありきということで進めているというところも感じとれましたので、これは採択すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"真摯に受けとめていただいて、できる限り区民の要望に沿えるような形でやっていただきたいと、もう見守るだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうとしては、本来は継続して審議をしていただきたいという思いがありました。議論する必要があるかなと思ったので継続といたしましたが、否決されましたので、趣旨採択ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"安藤委員","kind":"意見","question":"この内容は本当にもう採択すべきものだとは認識しているのですが、趣旨採択だというご意見の方も複数いらっしゃいますので、やはり少しでも前に進めたいという思いもありますので、趣旨採択に変えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"今の所長の訂正をお願いしたいのですけれども、積み上げられていた「ごみ」を収集したと。損害賠償しなくていいわけで、ごみではないので、そこのところはちょっと訂正してほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"積み上げられています「ごみ」と私のほうは説明いたしましたが、積み上げられているタオルです。大変失礼いたしました。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、お互いに気をつけていかないと、また同じことを繰り返すのではないかと思うのですね。ご配慮いただきたいということと、そこで何かご迷惑をおかけしたのですが、そこはどういうお話をされたのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"間違えたと言う部分では変わりはございませんので、私どもとしましても美容室のほうに丁寧に謝りを入れ、ご了解いただいたです。ただ、先ほどご説明いたしましたように、そういった部分のいわゆる通常出しているごみの位置を再確認をするようなお話をしたところです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"要は事業所のほうも、ある程度の間違いを起こさないようにというような努力はしていただきたいと思うのです。同じことを繰り返さないようにと思っているのですが、何かその辺の工夫をぜひお願いしたいと考えていますので、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"}]},{"id":"topic-07","title":"の(2) 品川区景観計画における「武蔵小山駅周辺地区」重点地区指定","agenda":"の(2) 品川区景観計画における「武蔵小山駅周辺地区」重点地区指定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"景観計画上の区の届出ですとか、景観審議会の意見聴取の過程などで、建築確認が下りないなどの事態が発生する可能性はあるのでしょうか。２項道路とかの場合ですとたしか一定あったかと思うのですけれども、どのようなものがあるのか、お伺いします。","respondent":"中村都市計画課長","answer":"この５０ｃｍの後退ですけれども、後退をしなければならないと言う表記はしてございませんので、これについて不利益があるということはございません。店舗の方、事業者の方が任意に使っていただけるですので、税の優遇は考えてございません。","id":"exchange-111"},{"speaker":"安藤委員","kind":"質問","question":"どうなのかなと思うのですけれども、考えるべきなのではないかと思うのですけれども、いかがでしょうか。景観法第９条では、どういう意見を反映するための努力をしたのか、そこら辺を伺います。","respondent":"中村都市計画課長","answer":"公聴会ですが、こちらのほうは説明会を２回に分けまして２日間ずつ、延べ４日間、権利者の皆様方にご案内をして意見を聞いたところです。説明会の意見も反映して、こういった５０ｃｍの後退の努力義務ですとか、地域の皆様方と一緒にここまで来たです。","id":"exchange-112"},{"speaker":"安藤委員","kind":"質問・要望","question":"高層化を誘導する方針になっているのではないかと思うのですけれども、これはちょっと問題ではないかと思うのですけれども、どうなのでしょうか。修正すべきなのではないかとは思っているのですが、区の考えを伺います。","respondent":"中村都市計画課長","answer":"例えば低い建物を建てようとしている事業主へ、つり合いがとれないので高層の建物を建ててくださいといった意味ではありません。むしろ抑えるほうの考え方に近いのかなと思いますが、それは決して高層化を助長して、望まない事業主に高層化を促すとかいうものではございません。","id":"exchange-113"},{"speaker":"安藤委員","kind":"質問","question":"私はちょっと今の説明では、強制力はないにしても、それをそうではないと言う根拠は何かあるのですか。そこら辺はいかがか尋ねました。","respondent":"中村都市計画課長","answer":"当然これを理由に区が高層化を迫るということは現実的には今までもありませんし、これからもそういったことは非常に考えにくいと思います。ただ、少なくともやはりここに書いてるとおりですが、調和を図るという以外に他意はございません。","id":"exchange-114"},{"speaker":"安藤委員","kind":"質問・要望","question":"他意はないということなので、ぜひこれで高層化を誘導するふうな手立てをしないでほしいとうことを要望したいです。ですから、パブリックコメントのご意見等というところにも出ていますけれども、やはり下町的地域だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"西本委員","kind":"確認","question":"６月１日施行ということなのですけれども、それから、現在合致していない店舗というのはどのぐらいあるのでしょうか。もう一つは、壁の使い方などもその店に合った形でつくりたいという方もいらっしゃると思うのですが、その自由度についてはいかがなのか尋ねました。","respondent":"中村都市計画課長","answer":"いろいろなパンフレットを配布したりですとかいったところも考えておりますけれども、この辺は周知をして混乱のないようにしたいと考えています。","id":"exchange-116"},{"speaker":"西本委員","kind":"確認","question":"では、現在は見た限り、景観計画に対してあまり問題がある、大幅に外れているということはないということの認識でよろしいのでしょうか。それぞれの店舗が必ず建築確認を取るという形でやっていくということになるのか、いや、その規制のかけ方というのは具体的にどのような形か尋ねました。","respondent":"中村都市計画課長","answer":"書面だけでやり取りするのではなく、届出だけでオーケーということではなくて、人と人で話し合いをしながら進めていくといったような感じになります。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりある程度の自由度を持った形で相談を受けていただきたいと思うのです。新しい一つの統一もありながらも特徴がありつつという形でのおもしろい地域になっていただいたらいいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"新妻委員","kind":"質問","question":"今回出していただいたここの変更がされましたということなのですけれども、これは当然ながら地権者の方も踏まえてのご意見と受けとめていいのか。例えばこういう規制をすることで、出ていかなくてはというようなことにならないようにするべきだと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"中村都市計画課長","answer":"既存の建物はそのまま使っていただけるということで、何か工事を行う時に届出がかかってくると。ただ、そういった同じ塗る場合にはこういうふうにしたほうがいいよとか、予算の範囲内で相談を受けられるような形がほとんどだと思います。","id":"exchange-119"},{"speaker":"新妻委員","kind":"質問","question":"それならば、当然専門家の方がアドバイスをしていただくということでよろしいのでしょうか。それと、何か例えば手を加えたいということで、商店街に対してのリフォームするにあたっての助成金とか、そういうのはあるのか尋ねました。","respondent":"中村都市計画課長","answer":"この相談を承るのは、当面最初区の職員のほうで対応して、調和を図った建物にしていただく、そういった届出をしていただくようになります。その方針に向けて改装をしていただいた場合に補助金が出るというような方向性を決めることができますので、引き続き取り組んでまいります。","id":"exchange-120"},{"speaker":"いながわ副委員長","kind":"質問","question":"あれだけ大きな商店街ですからやはりある程度のルールは必要だと思うのですけれども、この説明をする方は、それとも大家がやるべきなのか。ここではこういうルールがありますよという体制というのも必要なのかなと思うのですけれども、そこら辺どうお考えなのかということです。","respondent":"中村都市計画課長","answer":"そういったところで重要事項の説明の中でそういったものを説明していただくような、そういった形でもう入ってくる方ほぼ皆様、認知度は高いです。","id":"exchange-121"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"たしかそれほど多くはないと思うので、周知をしっかりしていただいて、よりよいパルム商店街をつくってほしいと求めました。そこに対しては今後何か、ちゃんと目をかけていただいているのかどうなのか、答えられる範囲で。","respondent":"中村都市計画課長","answer":"ほかもパルム商店街という認識でおりますけれども、今回重点地区をかけるところを足がかりにして、広げていければと考えています。それから熟度といったものも必要になってきまして、まずは一定のエリアをかけて始めて、そこから徐々に広げていければと考えています。","id":"exchange-122"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"荏原地区が活性化するようにしていっていただきたいので、残された商店街もしっかりとコーディネートしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":85558,"voices":339}},{"id":"h30-20180226-9","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"第１５号議案 品川区奨学金貸付条例の一部を改正する条例","agenda":"第１５号議案 品川区奨学金貸付条例の一部を改正する条例","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"説明を伺いました。逆を言うと、品川区民のうち、どれぐらいの高校生が対象者となるのかどうかをしっかり説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"国で実施しております就学支援金の制度、都で実施しております授業料の軽減制度と同じ方式で計算する所得制限に変更しようと考えております。というのも制度を導入する背景の１つであるのですが、年収ベースを上げた制度を検討した際に、そちらをご紹介していこうとするものです。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"予算を超えた場合については要望になりますが、必要な人が借りにこられるわけですから、そこはしっかり貸してほしいと求めました。４月１日に始まるので、その時点で規則ができていることですから、これは４月の文教委員会で報告を願いたいと思います。","respondent":"つる委員長","answer":"正副で調整します。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"スタートが今年度ですから、丁寧に周知、告知をされる方法を考えてほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"条例の中に、返還金免除について基準を定めると書いてありますけれども、既に定められているのか確認をさせてほしいと求めました。それから、これは必須になってくるのかどうかもあわせて伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"さまざまなプラスポイントが設けられる形をつくろうという方向で検討をしていますが、委員会等で報告させていただこうと考えています。それにプラスして、地域の活動をしたところも加点の扱いにするということなので、どれが必須というわけではなく、総合的に判断をする考えです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"それから、推薦書というのは、より優秀、トップクラスでないと受けられないのか伺いたいと思います。あるいは、入学準備金として、保護者への貸付を今まで行ってきましたけれども、それが変わるのかどうかも伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"先ほどもご説明したのですけれども、今回の制度は、申し込みの段階でいろいろな制度をご説明していった上でと考えています。入学準備金等の貸付は、今までも保護者に行っておりますが変更はございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"給付制に踏み出すべきだと思いますので、その実施も検討してほしいと求めましたけれども、いかがでしょうか。ほかに増額もされ、運用しやすくなるということで、賛成していきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"給付につきましては、当初の検討から、品川区としては考えておりません。ばらまきという考え方ではなく、その子のスケールで頑張ったことに対して返還免除を導入する趣旨ですので、給付をするつもりはございません。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは意見だけ言っておきます。ぜひ、多くの学生がこの制度を受けられるように、柔軟に対応していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"確認ですが、どういう家庭またはその状態を想定されて、こういう制度の導入を決めたのか。区がどういった認識から、この条例改正に至ったところをもう一度、確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"もう一つは、国とか都の検討の中で、給付等が何万円と一定要件を満たせば給付される制度がかなり充実したのです。生活の中で、そちらに対しても支援する制度を区として独自に導入したいところが背景にありまして、今回の検討結果となっています。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"子どもに行かせたいけれども、行かせられないというご家庭があるというのも伺っております。こうした制度があるということなので、制度の趣旨にかなう使い方をきちんとしていただきたいと考えますが、そうしたところはいかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"収入要件だけで判断するわけではなくて、高校生活を支援するものではありますが、その先の自立に向けた目的であるならば応援するべきだと考えます。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"その辺を詳しく教えてほしいと求めました。１度やったことがあるとか、具体例が決まっておりましたら、ご説明ほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"アンケートによると２２万円から１１０万円まで、平均が４９万円と出ているので、かなり差がある認識があります。ボランティアセンターで実施しているボランティア体験等で、防災課で実施するものであるとか、その中で参加しませんかということを考えています。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問・要望","question":"この選択制に関しては、１万円単位と理解をいたしました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私の質問も地域活動のところで、今までの委員とダブるところがあると思うのですけれども、これを導入する理由を改めて伺いたいと思うのです。ただ、地域活動を免除要件とした理由がどういうことかを伺って判断したいと考えていますので、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"公費を使うわけですので、地域の方、一般の区民の方のご理解が受けられないのではないかという考えが１つです。必須と考えているわけではなくて、特にすぐれたもの、何か得意なものを持っていない子のための加点となるもので導入したものです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"先ほどの説明を伺っていると、そういう場面を与えてしまうのは好ましいことではない、教育的ではないと私は思うのです。そういう点でどう考えるかを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"ただ、学校になかなか出席できなかった子もいるかもしれないので、返還免除を受けるためのプラスの要素として盛り込んだという考え方です。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"だから、加点というのであれば、それこそ総合的に判断されて、こういう括弧書きにしているところを「等」とすることがなぜできないのですか。そこがわかりません。","respondent":"廣田子ども家庭支援課長","answer":"面接を予定していますし、返還免除を申請したときに、その子が何を頑張ったのかがわからなくなります。お子さんに負担になるのでは本末転倒ですので、私どもとしてはそうならないように努めてまいります。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"一人ひとりにきちんと親子で面接をするという場を踏んでから貸し付けるわけですから、それを別に文書に記すことは全く必要ないと私は思います。それから、免除制度をつくることについては、審査会でどのような議論がされたのかを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"６０万円の金額につきましては、修学旅行について一番高く設定された学校が３０万円だったので、高校時代に大きな負債を持たせないという考えです。返還免除にあたっての考え方で、子どもたちの現状に即した、細かい意見が出されました。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"学校に推薦書を書くにあたり項目の１つとするということも含めて、教育的な観点からも、ふさわしいとは言い切れない。そういう意見を付しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ目は、在学応援資金は３０万円掛ける２０人で、何人の方が返還免除とするのかはまだ決まっていないということでよろしいのか。具体的な周知方法について、先ほどちょっとお話があったのですが、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"今、その方には個別に新制度についてご説明をするつもりです。なかなか周知が行き届かない部分があろうかと思うのですが、平成３１年度生以降については、知らない方がいないように努力しようとしています。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"何らかの形で周知する方法がないかと思って、なかなかいいアイデアがないのですが、どうでしょうか。中学校だと、そういったところと協力できればいいと思うのですが、その辺はいかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"現在の高校１年生、２年生につきましても、入学準備金以外は貸し付けを受けることは可能です。周知の方法については、まだ具体的に詰め切れていないので、委員のご提案も含めまして、これから検討したいと思います。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"先ほども質疑の中で申し上げましたが、地域活動を条件に入れることについては問題があると考えていますけれども、安心して修学ができる、そういう経済的な支援であること、そして、条件はつきながらも免除制度が創設されましたので、賛成をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"正する条例、(4)第１８号議案 品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(5)第３４号議…","agenda":"正する条例、(4)第１８号議案 品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(5)第３４号議…","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、この対象者は何人ぐらいいるのかということと、この変更で負担増になる人はいるのかも伺いたいと思います。品川区には該当施設があるのか、または、できる方向性があるのかも伺いたいと思います。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"１点目の対象者ですが、(1)の所得割の計算方法の関係ですが、乳幼児を抱える世帯としてはそれぐらいと見込んでおります。当面の間できる予定はないと所管から聞いていますので、(2)に関しましては… 就学前乳幼児教育施設、ぷりすくーる西五反田の該当者ですけれども、所得割軽減に対する該当者はございません。","id":"exchange-020"}]},{"id":"topic-03","title":"第３５号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例、(7)第３６号議案 学校教育職員の給与に関する条例の一部を改正する条例","agenda":"第３５号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例、(7)第３６号議案 学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、扶養手当が変わるということで、この影響なのですけれども、増える人と減る人がそれぞれ何人ぐらいいるのか伺いたいと思います。欠配一子の額が今まで１万３,７００円だったのが９,０００円に下がるということで、この部分が廃止となる理由について伺いたいと思います。","respondent":"熊谷指導課長","answer":"２点目なのですけれども、これは実は今から４８年ほど前の昭和４４年に、配偶者と欠配一子の額が同額となっています。そして、子どもに対する手当を上げるということで、手当の差が解消されることから廃止となった次第です。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"影響のある方は１３名いらっしゃるということと、全体としては、この手当額は変わらないことになるのでしょうか。そこのところを確認させてほしいと求めました。","respondent":"熊谷指導課長","answer":"１３名がこの扶養手当の見直しに伴う条例の改正により影響が生じる方なのですが、３名だけが平成３１年度は減ります。変わらない方が２名、８名が増える状況で、そういう状況にあります。","id":"exchange-022"}]},{"id":"topic-04","title":"第３９号議案 指定管理者の指定についておよび(9)第４０号議案 指定管理者の指定","agenda":"第３９号議案 指定管理者の指定についておよび(9)第４０号議案 指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、公募型プロポーザで２つの事業者が選定されたということですが、この選定にあたり利用者や専門家の声を反映する必要があると思うのです。聞いていれば聞いた内容を載せてほしいと求めましたが、聞かなかったということであれば、その理由を伺いたいと思います。","respondent":"横山品川図書館長","answer":"指定管理の運営にあたりましては、半年ごとにモニタリングおよびアンケート調査を行っておりまして、反応を確認しながら運営を進めてまいりました。この方法につきましては、第１期と同様です。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"モニタリングで利用者の声を聞いていた記憶が私はないのですが、どのようにそれで反映されているのかを伺いたいと思います。これまでのモニタリングで利用者や専門家の声が反映されているということがよくわからないので、もう少し詳しくご説明ほしいと求めました。","respondent":"横山品川図書館長","answer":"３グループ全てに応募することは可能ですが、選定については２グループまでという制限を設けて、指定管理の募集をしたところです。その結果、２グループと１グループの請負をする事業者が分かれた形になってあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのことを要望しておきますので、ぜひご検討ほしいと求めました。今回、この２つのグループになったということですけれども、ほかの運営事業者はどういったところがあったのかも伺えればと思います。","respondent":"横山品川図書館長","answer":"Ａグループに２事業者、Ｂグループに４事業者、Ｃグループに２事業者の応募がございました。Ｂグループの４事業者の残りの２つにつきましては、丸善雄松堂株式会社および株式会社ヴィアックスです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"提案","question":"地域特性に見合った提案ですとか、提案内容が具体的ということが書いてあるのですけれども、この事業者が一番よかったのかについてご説明ほしいと求めました。","respondent":"横山品川図書館長","answer":"３図書館について、また、そこの図書館の地域性に合った新しい事業の提案をいただいております。待遇のいい職員であれば、よりよい仕事ができるであろうという説得性を持ったご提案をいただいているところで、非常に評価が高いものでございました。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"しながわＴＲＣ・リディアグループについてもお伺いしたのですが、利用者の方にお話を聞くと、職員の方が頻繁にかわるとのことです。そういったことをやっていくには地域に根差した人員配置、職員が長く働き続けていけることが重要だと思いますけれども、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"指定管理につきましては、ご提案をいただいて運営をお願いする立場ですので、区がとどめることはできません。新しい、よりよいサービスにつながるように協力している形で、バランスをとってあります。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"図書館については指定管理者制度を肯定的には捉えていないこともありますし、区として、総務省が指定管理に図書館はそぐわないと考えている。この意図は何だと思っていらっしゃるか、区はそぐわないと考えないのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"先ほどご説明しましたように、管理をする形をとって、よりよいサービスに努めてあります。そういうものを品川区で考えた場合、よりよい形に協力していくという品川方式が、今のところでは品川区においてはベストな体制だと考えております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"意見","question":"１１館もあれば、異動しても次の図書館に移ることも考えられるわけです。そういったところが、区民へのサービス低下にもつながってきているのではないかと思いますとの意見を述べました。","respondent":"横山品川図書館長","answer":"いろいろなところで経験をし、新たに来る方も、ほかの図書館で経験を積まれた方が異動されてきてあります。区の職員につきましては、３年から５年のスパンで異動となり、図書館専門である事業者のほうがむしろ経験の積み上げは大きいものだと考えております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"総務省が２０１５年に調査をした資料ですと、法令遵守をしているかどうかというところに、評定に記載しているというところに丸がついております。こういったところでは、どういった基準になっているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"ですので、欠員という考え方は、多分、地元の方が、この間、会った職員がいないという意味で欠員とおっしゃっているのではないかと推定されます。","id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"私がお話を聞いたところでは、もともと２人いたところが１人になるとか、そういった状況から欠員になっていると聞いております。全体の中で必要な人数を把握されているといったところとは、ちょっと違うと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の事業を受けているのですから、そういう改訂にあたって、図書館事業が指定管理者の方々にどういう意見を伺って反映しようとしているのか。あるいは、幼稚園、保育園および病院などへの連携、それらが今までとどう違うのか、向上したのか、そのあたりについても伺いたいと思います。","respondent":"横山品川図書館長","answer":"先ほどご説明させていただきましたとおり、区の職員が直接モニタリングを日々行いながら、お互いの協力の中でサービスの質の向上を図ってあります。苦情やご意見につきましては、品川図書館と一緒に考えてご回答し、対応する形をとらせていただいております。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"６割でいいのかどうか、そこについて伺いたいと思います。そういう方々なのだという先ほどの説明もあったわけですから、そういう対応が求められるし、しっかり伺っておきたいと思います。","respondent":"横山品川図書館長","answer":"行いながらする形でモニタリングをして、改善を一緒に考えて、品川図書館と事業者が一緒に改善する形で努めてまいりました。一定程度、勉強をしないとなかなか難しいということも考えますと、資格だけを基準として選ぶのは非現実的なところがあるのが１つ。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"国会図書館以外が１００％でないからいいではないか、そんなことにはならないではないですか。そこを伺いたいと思います。","respondent":"横山品川図書館長","answer":"先ほどご説明させていただきましたように、経験を積みながら、図書館の中で過ごす機会を提供するという意味では重要な役割を果たしていると思います。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ずっと継続していただくとともに拡充をしていただきたいということは要望としてお願いしたいと思います。そういう点で、幾ら聞いても、そこはわかりませんので、きちんとそこについては答弁をしてほしいと求めました。","respondent":"横山品川図書館長","answer":"ご説明が不足して申し訳ございません。ぜひ実行しようということで、必ず反映をする形をとってございまして、間接的に区民の方のご意見を反映させていただいている状況と認識しています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"何回も聞いて、ようやくわかりました。ようやくここまで出てきたので、やはり適切に質問を理解していただいて、適切な答弁をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"提案","question":"今回は５年間にしたということは、３年間の指定管理がうまくいったから、この先は５年間でやっていくという認識でいいのかどうか教えてほしい。当然、すばらしい提案をしてきたのでしょうけれども、それに向かってやっていただけるのかとの意見を述べました。","respondent":"横山品川図書館長","answer":"３年間から５年間に期間を延ばしたことにつきましては、３年間、指定管理がよかったのかどうかを継続的に見てきたところです。事業を実施するにあたっては、各グループの連絡を密にし、いいところをさらに伸ばしていく運営方式です。","id":"exchange-037"}]},{"id":"topic-05","title":"平成３０年請願第７号 認可保育園入園のための制度改善を求める請願","agenda":"平成３０年請願第７号 認可保育園入園のための制度改善を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"請願が提出される際にお話を伺ったのですけれども、その方は第８希望まで書いても、また３歳のときに同じ思いをすることになってしまいます。そこは小規模もやっておりますし、認証保育所でも連携をやっていくべきなのではないかと思いますが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"１次の不承諾者が６４名、そのうち３６名は転園希望を出されていて、不承諾になっている方なので、実数としては２８名です。２次で空いている園を希望園の中に入れていただければ、ご心配せずとも認可保育園に入園できる状況です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"そういったところを考えても、来年度については３歳児が確実に入ることができると言えるのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"確実に入れる枠はあるというご説明をせざるを得なくて、そこについては、私が今の時点で絶対にということは言えません。それは小規模保育事業の方と指数の問題が違いますので、かなり低い方の場合は、希望園の状況によっては入れないということもある可能性はあります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"３歳のときに入れるのかは、３歳になるときも抱えということになってしまうと、安心して生活を送ることができない状況だと思うのです。小規模保育事業では連携がある中で、その負担を軽減していくためにもやっていくべきだと思いますけれども、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"不安とか安心という面では、２次募集の際に少し範囲を広げて希望していただければ、区内のどこかには必ず入れる状況ではあるということです。連携についてですけれども、３歳から入園を希望される方との公平性の観点から、連携園は今の状況では考えづらいです。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"枠的には入れるという話ですけれども、入れなかった場合に何か手立てを講じなければならないと思いますが、そのお考えはあるのか伺いたいと思います。安心して生活をすることができない、保育を保障していくのが自治体の責任だと思いますけれども、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"それは今後も新規開設を進めていくことと、できるだけ早い時期にお知らせして、選んでいただくということをやっていくことだと思います。認可保育園の開設を中心にしてまいりますけれども、さまざまな事業の実施により解決をして、解消をしていきたいと考えております。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"認可保育園に入りたいということが求められているのだと思います。認可保育園を希望する方が全て入れるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"区は新規開設をして３歳の枠を広げて、数としてきちんとそろえることで責任は果たしていると考えています。認可保育園の開設を中心に進めてまいりますけれども、認証保育所等も含めまして、解消に努めてまいりたいと思っています。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"待機児ゼロをしっかりと実現していくためにも、認可保育園の増設を区がしっかりと責任を持って進めていってほしいと求めました。質の担保の面でも、処遇改善をしっかりと進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"基本的なことを伺いたいのですけれども、認証保育所は今現在、何園あって、２歳までの認証保育所、子どもを受け入れるのは何人か、３歳児から就学前の５歳まで預けることが可能な所は、先ほど１３園とおっしゃっていましたけれども、改めて、そのあたりの数字を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"２歳までの定員は３０６人になります。","id":"exchange-044"},{"speaker":"南委員","kind":"質問","question":"先ほどの質疑を伺っていて、申請数に比べて５２３名あるので、枠はある。その辺も伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先ほど委員からもありましたけれども、０歳児から５歳児まで同じ園で過ごしたいご希望が多いと考えていますので、認可保育園を中心に進めております。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことから変更されたと伺ったのですが、改めて、そこは確認をしたいと思うのです。その点について、区の認識を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの２歳までの認証の定員数です。４１６名です。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"その辺を伺いたいのが２つ目です。そこのところの答弁がなかった気がするので、もう一度、そこを伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３１年４月の既存園の２歳児、３歳児の定員差は２１１名の予定です。本会議でも答弁がありましたけれども、そこの定員差と新規開設園でこの先も見込んでいけますので、３歳児の枠については確保できてあります。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"その点についてはどうなのでしょうか。そこは伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"品川区としては保育の責任があるわけですから、そこのところに今回のような事態が発生する要因があったのではないかと私は思っているのです。その点についての認識はいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"本格的に待機児童対策に取り組んだ平成２２年から、認可保育園はコンスタントに増やしておりますので、きちんと計画を立てて、それに沿って今後も開設をしていきます。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点については、どう考えたらいいですか。そんな負担をさせてしまって、どう思うのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園の開設は今後も進めてまいりますので、３歳児で路頭に迷うようなことは今後はございません。認証保育所と認可保育園の連携につきましては、公平性という観点から難しいと考えております。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"選択せざるを得ない状況に対しては、どう区としては考えているのですかと聞いたのですけれども、答弁がありません。答えてください。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園を開設していきます。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"２歳までの保育園ではなくて、何らかの形を考える必要があるのではないかという趣旨の発言をしました。答弁をお願いします。","respondent":"大澤待機児童対策担当課長","answer":"例えば認証保育所でしたら保育料を助成して、認可保育園に入った場合と同じ保育料にしているとか、それなりの対策はとっております。","id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"２歳児までの保育園に入れざるを得ない人に対しても、保育料を補助しているのだからいいというわけにはいかない。違う答弁だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"もっと言うと、例えば２歳から３歳のときに上がれなかったらどうするではなくて、例えば、１次で今回、確かに不承諾の方がいらっしゃった。課長、この先も基本的に２歳と３歳の問題というのは、あらあら品川区は順調にいけそうだと今日の審議の中では捉えてよろしいのですかね。","respondent":"大澤待機児童対策担当課長","answer":"現在の２歳児と３歳児の定員差、新規開設園の３歳児の枠で、申込者分は全てクリアできる数になっております。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"私のこの理解で合っているかどうかの確認が１つです。１番について問題はあるのですが、ご説明と、私の理解が合っているかどうかを確認させてください。","respondent":"大澤待機児童対策担当課長","answer":"認証保育所に在籍している方で、保育の認定を受けられる方については、３歳から認可保育園への入園は可能です。申込者の希望が減ってくれば、一定の役割が終わる時期が来るかもしれませんが、いましばらくは認証保育所の必要性はあると考えています。","id":"exchange-055"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"３歳児で移る、そこに入りたい方もいると思うので、それはそれで大事にしていただきたいのです。いろいろとサポートしていただきたいと思うので、その点では、ほかにどのようなことをされているのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"保育の質ということでは、東京都の指導検査のときに必ず区も立ち合うということで、いろいろ細かい点を見ています。認証保育所は、かなり緩やかな部分もありますので、中にはあえて選んで入園されている方もいらっしゃるかと思います。","id":"exchange-056"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"認証保育所に行かれているご父兄の方とか、現に生活しているお子様たちが非常に幸せに豊かに生活できるように、認可保育園に負けないように、その辺、区としてのサポートをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"何カ所もの保育園を施設見学させていただいて、いろいろなお話を伺っておりますので、そう受けとめております。２歳で保育園に通っていて、３歳に上がるのは、曲解はしないでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"３歳児に上がる際には、必ずどこかしらの園には入れるという話も伺っています。この先にも計画がありますし、まだまだ増えていっている状況であると思いますので、この請願に対しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほども確認をさせていただきましたが、ほぼ３歳のときに認可保育園に移る、そうした手続と流れになるように努力をされている話を理解できました。さらに努力をしていただきたい要望も含めて、このことについては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"今、区で努力をしている話は伺いました。特に請願項目の２番のほうも力を込めて進めていただきたいとあえて申し上げて、採択の理由にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"松永委員","kind":"確認","question":"請願項目の１番に関しましては、先ほどの議論の中でも確認をさせていただいたのですけれども、公平性に欠ける部分もあります。請願項目の２番に関しましては、今後も認可保育園の増設を進めていかれるということも先ほどの質疑の中で確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"意見","question":"０、１、２歳のところをいかに入れる形をとっていくかということです。今後も対応していくというところでありましたので、その点で進めているということで、この請願に関しては不採択でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"}]},{"id":"topic-06","title":"を行います。 専決処分の報告","agenda":"を行います。 専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"平成２７年ごろから滞り始めたということですが、もうちょっと詳しい経緯を教えてほしいと求めました。平成２７年に全く支払いが行われていないのか、それとも、断続的にではありますが、払っていたのか伺います。","respondent":"廣田子ども家庭支援課長","answer":"平成２６年までは順調にお支払いされていますが、平成２７年を最後に、今回の提訴に至っております。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"そうしますと、まだ相手方の状況はあまりつかんでいないということですね。体調が悪いということはありましたけれども、これは事業資金ですから、仕事を続けられないとかいったことも把握されているのか伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"先ほど申し上げたとおり、平成２７年１２月以降、連絡が全くとれておりません。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"訪問を行うなどの方法もあると思いますし、できるだけ手立てを尽くしてやっていくことが必要だと思います。ぜひ、そういった対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"南委員","kind":"質問","question":"どういう状況かということを、その辺の説明がないので、あえて伺います。こうなったということであれば、それはわからなくもないけれども、その辺をもう少し詳しく説明を伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"督促状におきましても、支払いができない状況であればご相談に応じますという連絡をしているにもかかわらず連絡がとれなかった状況にあります。払えないなりの状況をつかむ必要がありますが、この方と会うことができないので、会うための手段として提訴をしたものです。","id":"exchange-067"},{"speaker":"南委員","kind":"質問","question":"区がどういう対応をとっていたか、そこのところはわかりました。この返済済額が３８万８,０００円なのですが、返還があった最終日を改めて伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"平成２７年１２月１５日です。","id":"exchange-068"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この２次の空きと認証の枠、このうち０歳から２歳の空きは、年齢別で何人なのか伺いたいと思います。適切に在校時間を把握することは大切というご答弁でしたけれども、どのように把握していくお考えなのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58525,"voices":231}}]);
